INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4a2847c-eb33-459f-bf49-99298c6bfbd1', '田翁', '田翁', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["白髮星星筋力衰，種田猶自伴孫兒。","官苗若不平平納，任是豐年也受飢。"]', '["白髮星星筋力衰，種田猶自伴孫兒。","官苗若不平平納，任是豐年也受飢。"]', '诗', 'shi', '', NULL, '田翁 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f34f94b-db63-41bf-9671-0fbf98a2515c', '秋江雨夜逢詩友', '秋江雨夜逢诗友', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["故友別來三四載，新詩吟得百餘篇。","夜來江上秋無月，恨不相逢在雪天。"]', '["故友別来三四載，新诗吟得百餘篇。","夜来江上秋無月，恨不相逢在雪天。"]', '诗', 'shi', '', NULL, '秋江雨夜逢詩友 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('037ea122-96cd-42ac-bd71-0126010990d7', '感春', '感春', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["無況青雲有恨身，眼前花似夢中春。","浮生七十今三十，已是人間半世人。"]', '["無況青云有恨身，眼前花似梦中春。","浮生七十今三十，已是人间半世人。"]', '诗', 'shi', '', NULL, '感春 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bad8dc85-f0d8-4e36-8d2c-83e672f6628c', '題花木障', '題花木障', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["不假東風次第吹，筆勻春色一枝枝。","由來畫看勝栽看，免見朝開暮落時。"]', '["不假东风次第吹，笔勻春色一枝枝。","由来畫看勝栽看，免见朝开暮落时。"]', '诗', 'shi', '', NULL, '題花木障 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1271361-814a-4e11-bbec-f09c98c6dce5', '顧雲侍御出二子請詩因遺一絕', '顧云侍御出二子請诗因遺一絕', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["二雛毛骨秀仍奇，小小能吟大大詩。","想得月中仙桂樹，各從生日長新枝。"]', '["二雛毛骨秀仍奇，小小能吟大大诗。","想得月中仙桂樹，各從生日长新枝。"]', '诗', 'shi', '', NULL, '顧雲侍御出二子請詩因遺一絕 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9c00499-fd83-4d4f-8441-f0fc0fcefae7', '秋夕病中', '秋夕病中', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["壞屋不眠風雨夜，故園無信水雲秋。","病中枕上誰相問，一一蟬聲槐樹頭。"]', '["壞屋不眠风雨夜，故园無信水云秋。","病中枕上誰相问，一一蟬声槐樹头。"]', '诗', 'shi', '', NULL, '秋夕病中 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc6f3625-97b5-47d2-8ba8-69b278ae6dfd', '宿欒城驛却寄常山張書記', '宿欒城驛却寄常山張书記', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["一更更盡到三更，吟破離心句不成。","數樹秋風滿庭月，憶君時復下堦行。"]', '["一更更尽到三更，吟破離心句不成。","數樹秋风满庭月，憶君时复下堦行。"]', '诗', 'shi', '', NULL, '宿欒城驛却寄常山張書記 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddf6a309-913c-4b82-b919-652f7967622a', '湘江秋夕', '湘江秋夕', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["三湘月色三湘水，浸骨寒光似練鋪。","一夜寒鴻來不住，故鄉書信半年無。"]', '["三湘月色三湘水，浸骨寒光似練鋪。","一夜寒鴻来不住，故乡书信半年無。"]', '诗', 'shi', '', NULL, '湘江秋夕 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6c169fd-4227-4b07-9a09-45452e063aa6', '旅懷', '旅懷', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["蒹葭月冷時聞鴈，楊柳風和日聽鶯。","水涉山行二年客，就中偏怕雨船聲。"]', '["蒹葭月冷时闻鴈，楊柳风和日听鶯。","水涉山行二年客，就中偏怕雨船声。"]', '诗', 'shi', '', NULL, '旅懷 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2b57898-e523-401c-b48d-5461e7b6efb8', '贈崔道士', '贈崔道士', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["四海兵戈無靜處，人家廢業望烽煙。","九華道士渾如夢，猶向尊前笑揭天。"]', '["四海兵戈無静处，人家廢業望烽煙。","九华道士渾如梦，猶向尊前笑揭天。"]', '诗', 'shi', '', NULL, '贈崔道士 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4c1cb09-c9a8-402a-b9e4-043b163c0907', '題道林寺', '題道林寺', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["身未立間終日苦，身當立後幾年榮。","萬般不及僧無事，共水將山過一生。"]', '["身未立间終日苦，身當立後幾年榮。","万般不及僧無事，共水將山過一生。"]', '诗', 'shi', '', NULL, '題道林寺 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('770e1f7b-75a1-43ee-ba52-e9ba5e205058', '贈質上人', '贈質上人', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["枿坐雲遊出世塵，兼無缾鉢可隨身。","逢人不說人間事，便是人間無事人。"]', '["枿坐云游出世塵，兼無缾鉢可隨身。","逢人不说人间事，便是人间無事人。"]', '诗', 'shi', '', NULL, '贈質上人 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f4c9bbd-6eb6-4331-a09e-1ae4a1320861', '涇溪', '涇溪', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["涇溪石險人兢慎，終歲不聞傾覆人。","却是平流無石處，時時聞說有沈淪。"]', '["涇溪石險人兢慎，終歲不闻傾覆人。","却是平流無石处，时时闻说有沈淪。"]', '诗', 'shi', '', NULL, '涇溪 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae11534e-cbe1-49b2-b0b6-a0e6c01959ee', '夏日題悟空上人院', '夏日題悟空上人院', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["三伏閉門披一衲，兼無松竹蔭房廊。","安禪不必須山水，滅得心中火自涼。"]', '["三伏閉门披一衲，兼無松竹蔭房廊。","安禪不必須山水，滅得心中火自涼。"]', '诗', 'shi', '', NULL, '夏日題悟空上人院 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8a0731b-afba-45d0-8c31-29c8c8d053a3', '經嚴陵釣臺', '經嚴陵釣台', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["蒼翠雲峰開俗眼，泓澄煙水浸塵心。","唯將道業爲芳餌，釣得高名直至今。"]', '["蒼翠云峰开俗眼，泓澄煙水浸塵心。","唯將道業爲芳餌，釣得高名直至今。"]', '诗', 'shi', '', NULL, '經嚴陵釣臺 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8737efb-017c-480d-bf8e-577bb0bf346b', '關試後筵上別同人', '关試後筵上別同人', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["日午離筵到夕陽，明朝秦地與吳鄉。","同年多是長安客，不信行人欲斷腸。"]', '["日午離筵到夕陽，明朝秦地與吳乡。","同年多是长安客，不信行人欲斷腸。"]', '诗', 'shi', '', NULL, '關試後筵上別同人 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a03ae25b-86b5-4db5-af26-1e8d90eaf9bb', '鸕鷀', '鸕鷀', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["一般毛羽結羣飛，雨岸煙汀好景時。","深水有魚銜得出，看來却是鷺鶿飢。"]', '["一般毛羽結羣飞，雨岸煙汀好景时。","深水有鱼銜得出，看来却是鷺鶿飢。"]', '诗', 'shi', '', NULL, '鸕鷀 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46f2a563-fff3-4887-972b-242f290f90cb', '宿村舍', '宿村舍', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["野人於我有何情，半掩柴門向月明。","深夜欲眠眠未著，一叢寒木一猿聲。"]', '["野人於我有何情，半掩柴门向月明。","深夜欲眠眠未著，一叢寒木一猿声。"]', '诗', 'shi', '', NULL, '宿村舍 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd6efb88-60d1-4e01-9162-edf752da85b2', '題新鴈', '題新鴈', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["暮天新鴈起汀洲，紅蓼花疎水國秋。","想得故園今夜月，幾人相憶在江樓。"]', '["暮天新鴈起汀洲，紅蓼花疎水国秋。","想得故园今夜月，幾人相憶在江楼。"]', '诗', 'shi', '', NULL, '題新鴈 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12d26073-60b4-44e7-8d1f-22d156334d2b', '離家', '離家', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["丈夫三十身如此，疲馬離鄉懶著鞭。","槐柳路長愁殺我，一枝蟬到一枝蟬。"]', '["丈夫三十身如此，疲马離乡懶著鞭。","槐柳路长愁殺我，一枝蟬到一枝蟬。"]', '诗', 'shi', '', NULL, '離家 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9f777e7-e16e-4459-9ede-42b8ae1d82e4', '旅舍遇雨', '旅舍遇雨', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["月華星彩坐來收，嶽色江聲暗結愁。","半夜燈前十年事，一時和雨到心頭。"]', '["月华星彩坐来收，嶽色江声暗結愁。","半夜灯前十年事，一时和雨到心头。"]', '诗', 'shi', '', NULL, '旅舍遇雨 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3563aa31-ab93-42b9-a430-d762a9d40423', '送人歸淝上', '送人归淝上', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["巢湖春漲喻溪深，纔過東關見故林。","莫道南來總無利，水亭山寺二年吟。"]', '["巢湖春漲喻溪深，纔過东关见故林。","莫道南来總無利，水亭山寺二年吟。"]', '诗', 'shi', '', NULL, '送人歸淝上 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03b96410-b1e6-4863-be0e-4cebb2e2a8e6', '自遣', '自遣', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["糲食麤衣隨分過，堆金積帛欲如何。","百年身後一丘土，貧富高低爭幾多。"]', '["糲食麤衣隨分過，堆金積帛欲如何。","百年身後一丘土，貧富高低爭幾多。"]', '诗', 'shi', '', NULL, '自遣 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55157217-07e9-464e-9bb9-f940998cf5cd', '聞子規', '闻子規', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["楚天空闊月成輪，蜀魄聲聲似告人。","啼得血流無用處，不如緘口過殘春。"]', '["楚天空闊月成輪，蜀魄声声似告人。","啼得血流無用处，不如緘口過殘春。"]', '诗', 'shi', '', NULL, '聞子規 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10220ed5-bb62-4755-b379-5daf6a1a16a7', '秋夜苦吟', '秋夜苦吟', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["吟盡三更未著題，竹風松雨共淒淒。","此時若有人來聽，始覺巴猿不解啼。"]', '["吟尽三更未著題，竹风松雨共淒淒。","此时若有人来听，始覺巴猿不解啼。"]', '诗', 'shi', '', NULL, '秋夜苦吟 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('294c43b3-61e0-4c83-adf0-af85ca690bbc', '秋夜聞砧', '秋夜闻砧', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["荒涼客舍眠秋色，砧杵家家弄月明。","不及巴山聽猿夜，三聲中有不愁聲。"]', '["荒涼客舍眠秋色，砧杵家家弄月明。","不及巴山听猿夜，三声中有不愁声。"]', '诗', 'shi', '', NULL, '秋夜聞砧 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64c879a7-b7d2-48ed-a466-4f99196c15b0', '將過湖南經馬當山廟因書三絕 一', '將過湖南經马當山廟因书三絕 一', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["人說馬當波浪險，我經波浪似通衢。","大凡君子行藏是，自有龍神衛過湖。"]', '["人说马當波浪險，我經波浪似通衢。","大凡君子行藏是，自有龙神衛過湖。"]', '诗', 'shi', '', NULL, '將過湖南經馬當山廟因書三絕 一 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3860cd0-89e6-4720-afca-759b22203445', '將過湖南經馬當山廟因書三絕 二', '將過湖南經马當山廟因书三絕 二', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["貪殘官吏虔誠謁，毒害商人瀝膽過。","祗怕馬當山下水，不知平地有風波。"]', '["貪殘官吏虔誠謁，毒害商人瀝膽過。","祗怕马當山下水，不知平地有风波。"]', '诗', 'shi', '', NULL, '將過湖南經馬當山廟因書三絕 二 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0b27b2a-1f64-49d0-ad53-25aaa2266295', '將過湖南經馬當山廟因書三絕 三', '將過湖南經马當山廟因书三絕 三', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["九江連海一般深，未必船經廟下沈。","頭上蒼蒼沒瞞處，不如平取一生心。"]', '["九江連海一般深，未必船經廟下沈。","头上蒼蒼沒瞞处，不如平取一生心。"]', '诗', 'shi', '', NULL, '將過湖南經馬當山廟因書三絕 三 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('423c9943-3a32-416f-8027-284cdcc1698d', '梁王坐上賦無雲雨', '梁王坐上賦無云雨', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["同是乾坤事不同，雨絲飛灑日輪中。","若教陰郎長相似，爭表梁王造化功。"]', '["同是乾坤事不同，雨絲飞灑日輪中。","若教陰郎长相似，爭表梁王造化功。"]', '诗', 'shi', '', NULL, '梁王坐上賦無雲雨 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ffbf2c6-272d-46bd-9fd8-f797d936beaf', '小松', '小松', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["自小刺頭深草裏，而今漸覺出蓬蒿。","時人不識凌雲木，直待凌雲始道高。"]', '["自小刺头深草裏，而今漸覺出蓬蒿。","时人不識凌云木，直待凌云始道高。"]', '诗', 'shi', '', NULL, '小松 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87eb220e-34d5-4ec0-b6e7-9b591f0ee622', '醉書僧壁', '醉书僧壁', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["九華山色真堪愛，留得高僧爾許年。","聽我吟詩供我酒，不曾穿得判齋錢。"]', '["九华山色真堪愛，留得高僧爾許年。","听我吟诗供我酒，不曾穿得判斋錢。"]', '诗', 'shi', '', NULL, '醉書僧壁 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7a8f62c-1ad1-455a-93a7-4d484ca722c8', '寄李隱居', '寄李隐居', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["自小棲玄到老閑，如雲如鶴住應難。","溪山不必將錢買，贏得來來去去看。"]', '["自小棲玄到老闲，如云如鹤住應难。","溪山不必將錢買，贏得来来去去看。"]', '诗', 'shi', '', NULL, '寄李隱居 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('facc9ed3-d579-4a3d-892f-31f4447dcbc7', '句', '句', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["舊衣灰絮絮，新酒竹篘篘。","只知斷送豪家酒，不解安排旅客情。"]', '["旧衣灰絮絮，新酒竹篘篘。","只知斷送豪家酒，不解安排旅客情。"]', '诗', 'shi', '', NULL, '句 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('affc4c69-a82e-4c1f-927a-84e07d4547d3', '上蜀王', '上蜀王', '3f00dfe2-e430-4e8a-9e0b-41e68de89513', '唐', '["封章才達冕旒前，黜詔俄離玉座端。","二亂豈由明主用，五危終被佞臣彈。","西巡鳳府非爲固，東播鑾輿卒未安。","諫疏至今如可在，誰能更與讀來看。"]', '["封章才達冕旒前，黜詔俄離玉座端。","二亂豈由明主用，五危終被佞臣彈。","西巡鳳府非爲固，东播鑾輿卒未安。","諫疏至今如可在，誰能更與读来看。"]', '诗', 'shi', '', NULL, '上蜀王 張道古 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4c31d1c-9ee0-4cee-991f-6cdc145a7ffd', '詠雨', '詠雨', '3f00dfe2-e430-4e8a-9e0b-41e68de89513', '唐', '["亢陽今已久，嘉雨自雲傾。","一點不斜去，極多時下成。"]', '["亢陽今已久，嘉雨自云傾。","一点不斜去，極多时下成。"]', '诗', 'shi', '', NULL, '詠雨 張道古 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2f602a5-8685-4fa8-9cc1-3643119d43ca', '楊岐山', '楊岐山', '8be7f890-fbea-42b2-b09f-f25e8234894d', '唐', '["逗竹穿花越幾村，還從舊路入雲門。","翠微不閉樓臺出，清吹頻回水石喧。","天外鶴歸松自老，巖間僧逝塔空存。","重來白首良堪喜，朝露浮生不足言。"]', '["逗竹穿花越幾村，還從旧路入云门。","翠微不閉楼台出，清吹頻回水石喧。","天外鹤归松自老，巖间僧逝塔空存。","重来白首良堪喜，朝露浮生不足言。"]', '诗', 'shi', '', NULL, '楊岐山 唐廩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3253e0e0-0ff5-4d27-87d4-0d9734eb0a73', '吹笙引', '吹笙引', '96b87115-9522-4659-92a6-83e4aec4f244', '唐', '["媧皇遺音寄玉笙，雙成傳得何淒清。","丹穴嬌雛七十隻，一時飛上秋天鳴。","水泉迸瀉急相續，一束宮商裂寒玉。","旖旎香風繞指生，千聲妙盡神仙曲。","曲終滿席悄無語，巫山冷碧愁雲雨。"]', '["媧皇遺音寄玉笙，雙成傳得何淒清。","丹穴嬌雛七十隻，一时飞上秋天鳴。","水泉迸瀉急相續，一束宮商裂寒玉。","旖旎香风繞指生，千声妙尽神仙曲。","曲終满席悄無語，巫山冷碧愁云雨。"]', '诗', 'shi', '', NULL, '吹笙引 王轂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13f924e9-4740-482d-b7b0-48bb7f3e3713', '鴻門讌', '鴻门讌', '96b87115-9522-4659-92a6-83e4aec4f244', '唐', '["寰海沸兮爭戰苦，風雲愁兮會龍虎。","四百年漢欲開基，項莊一劍何虛舞。","殊不知人心去暴秦，天意歸明主。","項王足底踏漢土，席上相看渾未悟。"]', '["寰海沸兮爭戰苦，风云愁兮會龙虎。","四百年漢欲开基，項莊一劍何虛舞。","殊不知人心去暴秦，天意归明主。","項王足底踏漢土，席上相看渾未悟。"]', '诗', 'shi', '', NULL, '鴻門讌 王轂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0f62044-8fb8-4e65-99f3-539929c4cf2d', '玉樹曲', '玉樹曲', '96b87115-9522-4659-92a6-83e4aec4f244', '唐', '["陳宮內宴明朝日，玉樹新妝逞嬌逸。","三閣霞明天上開，靈鼉振攂神仙出。","天花數朵風吹綻，對舞輕盈瑞香散。","金管紅弦旖旎隨，霓旌玉佩參差轉。","璧月夜滿樓風輕，蓮舌泠泠詞調新。","當行狎客盡持祿，直諫犯顏無一人。","歌舞未終樂未闋，晉王劍上黏腥血。","君臣猶在醉鄉中，一面已無陳日月。","聖唐御宇三百祀，濮上桑間宜禁止。","請停此曲歸正聲，願將雅樂調元氣。"]', '["陳宮內宴明朝日，玉樹新妝逞嬌逸。","三閣霞明天上开，靈鼉振攂神仙出。","天花數朵风吹綻，对舞轻盈瑞香散。","金管紅弦旖旎隨，霓旌玉佩參差轉。","璧月夜满楼风轻，蓮舌泠泠词調新。","當行狎客尽持祿，直諫犯顏無一人。","歌舞未終乐未闋，晉王劍上黏腥血。","君臣猶在醉乡中，一面已無陳日月。","聖唐御宇三百祀，濮上桑间宜禁止。","請停此曲归正声，願將雅乐調元氣。"]', '诗', 'shi', '', NULL, '玉樹曲 王轂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e83519e3-9286-4b07-a53e-e0e688ddae8b', '苦熱行', '苦熱行', '96b87115-9522-4659-92a6-83e4aec4f244', '唐', '["祝融南來鞭火龍，火旗焰焰燒天紅。","日輪當午凝不去，萬國如在洪爐中。","五嶽翠乾雲彩滅，陽侯海底愁波竭。","何當一夕金風發，爲我掃却天下熱。"]', '["祝融南来鞭火龙，火旗焰焰燒天紅。","日輪當午凝不去，万国如在洪爐中。","五嶽翠乾云彩滅，陽侯海底愁波竭。","何當一夕金风發，爲我掃却天下熱。"]', '诗', 'shi', '', NULL, '苦熱行 王轂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a65068f-7e17-437b-ab45-a584f1ec63d9', '暑日題道邊樹', '暑日題道邊樹', '96b87115-9522-4659-92a6-83e4aec4f244', '唐', '["火輪迸焰燒長空，浮埃撲面愁朦朦。","羸童走馬喘不進，忽逢碧樹含清風。","清風留我移時住，滿地濃陰嬾前去。","却歎人無及物功，不似團團道邊樹。"]', '["火輪迸焰燒长空，浮埃撲面愁朦朦。","羸童走马喘不進，忽逢碧樹含清风。","清风留我移时住，满地濃陰嬾前去。","却歎人無及物功，不似團團道邊樹。"]', '诗', 'shi', '', NULL, '暑日題道邊樹 王轂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb96023d-8cc9-42f0-8c67-dafa7fa71c28', '紅薔薇歌', '紅薔薇歌', '96b87115-9522-4659-92a6-83e4aec4f244', '唐', '["紅霞爛潑猩猩血，阿母瑤池曬仙纈。","晚日春風奪眼明，蜀機錦彩渾疑黦。","公子亭臺香觸人，百花懡㦬無精神。","苧羅西子見應妬，風光占斷年年新。"]', '["紅霞爛潑猩猩血，阿母瑤池曬仙纈。","晚日春风奪眼明，蜀機錦彩渾疑黦。","公子亭台香觸人，百花懡㦬無精神。","苧羅西子见應妬，风光占斷年年新。"]', '诗', 'shi', '', NULL, '紅薔薇歌 王轂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b2a0bd1-0834-4096-8765-37d16644a398', '刺桐花', '刺桐花', '96b87115-9522-4659-92a6-83e4aec4f244', '唐', '["南國清和煙雨辰，刺桐夾道花開新。","林梢簇簇紅霞爛，暑天別覺生精神。","穠英鬬火欺朱槿，棲鶴驚飛翅憂燼。","直疑青帝去怱怱，收拾春風渾不盡。"]', '["南国清和煙雨辰，刺桐夾道花开新。","林梢簇簇紅霞爛，暑天別覺生精神。","穠英鬬火欺朱槿，棲鹤驚飞翅憂燼。","直疑青帝去怱怱，收拾春风渾不尽。"]', '诗', 'shi', '', NULL, '刺桐花 王轂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d43d99e8-ec8c-4f4d-a9a6-e760bd688721', '贈蒼溪王明府有文在手曰長生', '贈蒼溪王明府有文在手曰长生', '96b87115-9522-4659-92a6-83e4aec4f244', '唐', '["執手長生在，人皆號地仙。","水雲真遂性，龜鶴足齊年。","但以酒養氣，何言命在天。","況無婚嫁累，應拍尚平肩。"]', '["執手长生在，人皆號地仙。","水云真遂性，龟鹤足齊年。","但以酒養氣，何言命在天。","況無婚嫁累，應拍尚平肩。"]', '诗', 'shi', '', NULL, '贈蒼溪王明府有文在手曰長生 王轂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('112125d8-08fd-471b-8111-a7c632a5dfd4', '逢道者神和子', '逢道者神和子', '96b87115-9522-4659-92a6-83e4aec4f244', '唐', '["珍重神和子，聞名五十年。","童顏終不改，綠髮尚依然。","酒裏消閑日，人間作散仙。","長生如可慕，相逐隱林泉。"]', '["珍重神和子，闻名五十年。","童顏終不改，綠髮尚依然。","酒裏消闲日，人间作散仙。","长生如可慕，相逐隐林泉。"]', '诗', 'shi', '', NULL, '逢道者神和子 王轂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12d929b9-8ee3-4755-97b3-3ca1f54177c8', '送友人歸閩', '送友人归閩', '96b87115-9522-4659-92a6-83e4aec4f244', '唐', '["東南歸思切，把酒且留連。","再會知何處，相看共黯然。","猨啼棃嶺路，月白建溪船。","莫戀家鄉住，酬身在少年。"]', '["东南归思切，把酒且留連。","再會知何处，相看共黯然。","猨啼棃嶺路，月白建溪船。","莫戀家乡住，酬身在少年。"]', '诗', 'shi', '', NULL, '送友人歸閩 王轂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b75c51e0-292a-477b-ba6c-6bd7c92c11b5', '春草碧色', '春草碧色', '96b87115-9522-4659-92a6-83e4aec4f244', '唐', '["習習東風扇，萋萋草色新。","淺深千里碧，高下一時春。","嫩葉舒煙際，微香動水濱。","金塘明夕照，輦路惹芳塵。","造化功何廣，陽和力自均。","今當發生日，瀝懇祝良辰。"]', '["習習东风扇，萋萋草色新。","淺深千里碧，高下一时春。","嫩葉舒煙際，微香动水濱。","金塘明夕照，輦路惹芳塵。","造化功何廣，陽和力自均。","今當發生日，瀝懇祝良辰。"]', '诗', 'shi', '', NULL, '春草碧色 王轂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eea023f0-0a44-4315-ab2c-ba917c449a01', '夢仙謠三首 一', '梦仙謠三首 一', '96b87115-9522-4659-92a6-83e4aec4f244', '唐', '["前程漸覺風光好，琪花片片粘瑤草。","有人遺我五色丹，一粒吞之後天老。"]', '["前程漸覺风光好，琪花片片粘瑤草。","有人遺我五色丹，一粒吞之後天老。"]', '诗', 'shi', '', NULL, '夢仙謠三首 一 王轂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e639605f-af52-43d1-8a50-76f31a762a0a', '夢仙謠三首 二', '梦仙謠三首 二', '96b87115-9522-4659-92a6-83e4aec4f244', '唐', '["青童遞酒金觴疾，列坐紅霞神氣逸。","笑說留連數日間，已是人間一千日。"]', '["青童遞酒金觴疾，列坐紅霞神氣逸。","笑说留連數日间，已是人间一千日。"]', '诗', 'shi', '', NULL, '夢仙謠三首 二 王轂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06fd3f80-6f1c-4348-8046-205d81d5dfb5', '夢仙謠三首 三', '梦仙謠三首 三', '96b87115-9522-4659-92a6-83e4aec4f244', '唐', '["瑤臺絳節遊皆遍，異果奇花香撲面。","松窗夢覺却神清，殘月林前三兩片。"]', '["瑤台絳節游皆遍，異果奇花香撲面。","松窗梦覺却神清，殘月林前三兩片。"]', '诗', 'shi', '', NULL, '夢仙謠三首 三 王轂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7efff66-3635-4900-a067-fda3f2671fbc', '後魏行', '後魏行', '96b87115-9522-4659-92a6-83e4aec4f244', '唐', '["力微皇帝謗天嗣，太武凶殘人所畏。","一朝𦍩䍽飛上天，子孫盡作河魚餌。"]', '["力微皇帝謗天嗣，太武凶殘人所畏。","一朝𦍩䍽飞上天，子孫尽作河鱼餌。"]', '诗', 'shi', '', NULL, '後魏行 王轂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d85584d8-24ed-4a25-af94-fc26bf0f4f37', '秋', '秋', '96b87115-9522-4659-92a6-83e4aec4f244', '唐', '["蟬噪古槐疏葉下，樹銜斜日映孤城。","欲知潘鬢愁多少，一夜新添白數莖。"]', '["蟬噪古槐疏葉下，樹銜斜日映孤城。","欲知潘鬢愁多少，一夜新添白數莖。"]', '诗', 'shi', '', NULL, '秋 王轂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e46c553e-4ba2-4e7f-9d42-3a27b3e99b3b', '燕', '燕', '96b87115-9522-4659-92a6-83e4aec4f244', '唐', '["海燕雙飛意若何，曲梁嘔嘎語聲多。","茅檐不必嫌卑陋，猶勝吳宮爇爾窠。"]', '["海燕雙飞意若何，曲梁嘔嘎語声多。","茅檐不必嫌卑陋，猶勝吳宮爇爾窠。"]', '诗', 'shi', '', NULL, '燕 王轂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54539b02-23db-415b-a521-890b6a28436c', '牡丹', '牡丹', '96b87115-9522-4659-92a6-83e4aec4f244', '唐', '["牡丹妖豔亂人心，一國如狂不惜金。","曷若東園桃與李，果成無語自垂陰。"]', '["牡丹妖豔亂人心，一国如狂不惜金。","曷若东园桃與李，果成無語自垂陰。"]', '诗', 'shi', '', NULL, '牡丹 王轂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52ba0fee-9b9b-4acf-8921-8d03e546d530', '古意二首 一', '古意二首 一', 'af2cf39b-0b3a-4e6d-9462-9718176e6b34', '唐', '["屈子生楚國，七雄知其材。","介潔世不容，跡合藏蒿萊。","道廢固命也，瓢飲亦賢哉。","何事葬江水，空使後人哀。"]', '["屈子生楚国，七雄知其材。","介潔世不容，跡合藏蒿萊。","道廢固命也，瓢饮亦賢哉。","何事葬江水，空使後人哀。"]', '诗', 'shi', '', NULL, '古意二首 一 孫郃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('368fd800-6c1b-466f-84c6-7dcbdc45ed05', '古意二首 二', '古意二首 二', 'af2cf39b-0b3a-4e6d-9462-9718176e6b34', '唐', '["魏禮段干木，秦王乃止戈。","小國有其人，大國奈之何。","賢哲信爲美，兵甲豈云多。","君子戰必勝，斯言聞孟軻。"]', '["魏禮段干木，秦王乃止戈。","小国有其人，大国奈之何。","賢哲信爲美，兵甲豈云多。","君子戰必勝，斯言闻孟軻。"]', '诗', 'shi', '', NULL, '古意二首 二 孫郃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f4f32d1-d4c0-46c7-8efc-929a35d61913', '哭方玄英先生', '哭方玄英先生', 'af2cf39b-0b3a-4e6d-9462-9718176e6b34', '唐', '["牛斗文星落，知是先生死。","湖上聞哭聲，門前見彈指。","官無一寸祿，名傳千萬里。","死著弊衣裳，生誰顧朱紫。","我心痛其語，淚落不能已。","猶喜韋補闕，揚名薦天子。"]', '["牛斗文星落，知是先生死。","湖上闻哭声，门前见彈指。","官無一寸祿，名傳千万里。","死著弊衣裳，生誰顧朱紫。","我心痛其語，泪落不能已。","猶喜韋補闕，揚名薦天子。"]', '诗', 'shi', '', NULL, '哭方玄英先生 孫郃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2399184-a4c5-4184-bc95-920088394852', '句', '句', 'af2cf39b-0b3a-4e6d-9462-9718176e6b34', '唐', '["仕宦類商賈，終日常東西。"]', '["仕宦類商賈，終日常东西。"]', '诗', 'shi', '', NULL, '句 孫郃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6d91294-726a-4174-a11a-90bac85303ee', '投節度邢公', '投節度邢公', '3776898b-6887-42ad-a611-012035dc42c4', '唐', '["西風昨夜墜紅蘭，一宿郵亭事萬般。","無地可耕歸不得，有恩堪報死何難。","流年怕老看將老，百計求安未得安。","一卷新書滿懷淚，頻來門館訴飢寒。"]', '["西风昨夜墜紅蘭，一宿郵亭事万般。","無地可耕归不得，有恩堪報死何难。","流年怕老看將老，百計求安未得安。","一卷新书满懷泪，頻来门館訴飢寒。"]', '诗', 'shi', '', NULL, '投節度邢公 褚載 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3ebc78c-ca91-4a5f-8935-0a45e8d242ea', '賀趙觀文重試及第', '賀趙观文重試及第', '3776898b-6887-42ad-a611-012035dc42c4', '唐', '["一枝仙桂兩回春，始覺文章可致身。","已把色絲要上第，又將彩筆冠羣倫。","龍泉再淬方知利，火浣重燒轉更新。","今日街頭看御牓，大能榮耀苦心人。"]', '["一枝仙桂兩回春，始覺文章可致身。","已把色絲要上第，又將彩笔冠羣倫。","龙泉再淬方知利，火浣重燒轉更新。","今日街头看御牓，大能榮耀苦心人。"]', '诗', 'shi', '', NULL, '賀趙觀文重試及第 褚載 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb7faa2d-b7de-4511-961f-a42aa215bfcf', '贈道士', '贈道士', '3776898b-6887-42ad-a611-012035dc42c4', '唐', '["簪星曳月下蓬壺，曾見東臯種白榆。","六甲威靈藏瑞檢，五龍雷電遶霜都。","惟教鶴探丹丘信，不使人窺太乙爐。","聞說葛陂風浪惡，許騎青鹿從行無。"]', '["簪星曳月下蓬壺，曾见东臯種白榆。","六甲威靈藏瑞檢，五龙雷電遶霜都。","惟教鹤探丹丘信，不使人窺太乙爐。","闻说葛陂风浪惡，許騎青鹿從行無。"]', '诗', 'shi', '', NULL, '贈道士 褚載 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a46dc2f4-3eec-4255-8ada-ae14950325b3', '曉發', '晓發', '3776898b-6887-42ad-a611-012035dc42c4', '唐', '["貪路貪名須早發，枕前無計暫裴回。","纔聞雞唱呼童起，已有鈴聲過驛來。","衣溼乍驚霑霧露，馬行仍未見塵埃。","朝朝陌上侵星去，待得酬身了便回。"]', '["貪路貪名須早發，枕前無計暫裴回。","纔闻雞唱呼童起，已有鈴声過驛来。","衣溼乍驚霑霧露，马行仍未见塵埃。","朝朝陌上侵星去，待得酬身了便回。"]', '诗', 'shi', '', NULL, '曉發 褚載 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea744ab7-9131-4dfa-8b20-fcf5e72569b5', '曉感', '晓感', '3776898b-6887-42ad-a611-012035dc42c4', '唐', '["曉鼓鼕鼕星漢微，佩金鳴玉鬬光輝。","出門各自爭岐路，至老何人免是非。","大道不應由曲取，浮生還要畧知機。","故園華表高高在，可得不如丁令威。"]', '["晓鼓鼕鼕星漢微，佩金鳴玉鬬光輝。","出门各自爭岐路，至老何人免是非。","大道不應由曲取，浮生還要畧知機。","故园华表高高在，可得不如丁令威。"]', '诗', 'shi', '', NULL, '曉感 褚載 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24930022-531a-4f49-807d-541aa570ee39', '南徐晚望', '南徐晚望', '3776898b-6887-42ad-a611-012035dc42c4', '唐', '["芳草鋪香晚岸晴，岸頭含醉去來行。","僧歸岳外殘鐘寺，日下江邊調角城。","入浙孤帆知楚信，過淮疎雨帶潮聲。","如今未免風塵役，寧敢怱怱便濯纓。"]', '["芳草鋪香晚岸晴，岸头含醉去来行。","僧归岳外殘鐘寺，日下江邊調角城。","入浙孤帆知楚信，過淮疎雨带潮声。","如今未免风塵役，寧敢怱怱便濯纓。"]', '诗', 'shi', '', NULL, '南徐晚望 褚載 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fcf0ee1-54c1-42d5-b431-a859180f42c9', '移石', '移石', '3776898b-6887-42ad-a611-012035dc42c4', '唐', '["磷𥒘一片溪中石，恰稱幽人彈素琴。","浪侵多年苔色在，洗來今日碏痕深。","磨看粹色何殊玉，敲有奇聲直異金。","不是不堪爲器用，都緣良匠未留心。"]', '["磷𥒘一片溪中石，恰稱幽人彈素琴。","浪侵多年苔色在，洗来今日碏痕深。","磨看粹色何殊玉，敲有奇声直異金。","不是不堪爲器用，都緣良匠未留心。"]', '诗', 'shi', '', NULL, '移石 褚載 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6061de32-6811-442a-acfc-c8105b3d35a7', '瀑布', '瀑布', '3776898b-6887-42ad-a611-012035dc42c4', '唐', '["瀉霧傾煙撼撼雷，滿山風雨助喧豗。","爭知不是青天闕，撲下銀河一半來。"]', '["瀉霧傾煙撼撼雷，满山风雨助喧豗。","爭知不是青天闕，撲下銀河一半来。"]', '诗', 'shi', '', NULL, '瀑布 褚載 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b262bd58-6dff-4a23-96a2-fd88d264edf4', '定鼎門', '定鼎门', '3776898b-6887-42ad-a611-012035dc42c4', '唐', '["郟鄏城高門倚天，九重蹤跡尚依然。","須知道德無關鎖，一閉乾坤一萬年。"]', '["郟鄏城高门倚天，九重蹤跡尚依然。","須知道德無关鎖，一閉乾坤一万年。"]', '诗', 'shi', '', NULL, '定鼎門 褚載 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc8d043a-d3f6-483f-b712-fc60887c3395', '陳倉驛', '陳倉驛', '3776898b-6887-42ad-a611-012035dc42c4', '唐', '["錦翼花冠安在哉，雄飛雌伏盡塵埃。","一雙童子應惆悵，不見真人更獵來。"]', '["錦翼花冠安在哉，雄飞雌伏尽塵埃。","一雙童子應惆悵，不见真人更獵来。"]', '诗', 'shi', '', NULL, '陳倉驛 褚載 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('979c60d9-9fd6-4db5-8b32-dd3788f983e1', '長城', '长城', '3776898b-6887-42ad-a611-012035dc42c4', '唐', '["秦築長城比鐵牢，蕃戎不敢過臨洮。","焉知萬里連雲色，不及堯階三尺高。"]', '["秦築长城比鐵牢，蕃戎不敢過臨洮。","焉知万里連云色，不及堯階三尺高。"]', '诗', 'shi', '', NULL, '長城 褚載 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d04fdbb7-ad17-4130-87f0-e813962bbc9d', '弔秦叟', '弔秦叟', '3776898b-6887-42ad-a611-012035dc42c4', '唐', '["市西樓店金千秤，渭北田園粟萬鍾。","兒被殺傷妻被虜，一身隨駕到三峰。"]', '["市西楼店金千秤，渭北田园粟万鍾。","兒被殺傷妻被虜，一身隨駕到三峰。"]', '诗', 'shi', '', NULL, '弔秦叟 褚載 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39872409-84a1-4b01-b2e7-a711652dbf21', '雲', '云', '3776898b-6887-42ad-a611-012035dc42c4', '唐', '["盡日看雲首不回，無心都大似無才。","可憐光彩一片玉，萬里晴天何處來。"]', '["尽日看云首不回，無心都大似無才。","可怜光彩一片玉，万里晴天何处来。"]', '诗', 'shi', '', NULL, '雲 褚載 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bdd95a6-98cd-45e8-8557-d3bd0458c20d', '鶴', '鹤', '3776898b-6887-42ad-a611-012035dc42c4', '唐', '["欲洗霜翎下澗邊，却嫌菱刺汚香泉。","沙鷗浦鴈應驚訝，一舉扶搖直上天。"]', '["欲洗霜翎下澗邊，却嫌菱刺汚香泉。","沙鷗浦鴈應驚訝，一舉扶搖直上天。"]', '诗', 'shi', '', NULL, '鶴 褚載 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e81299b3-371e-4708-832e-86e37d490ca6', '句', '句', '3776898b-6887-42ad-a611-012035dc42c4', '唐', '["相逢多是醉醺然，應有囊中子母錢。","有興欲沽紅麴酒，無人同上翠旌樓。","星斗離披煙靄收，玉蟾蜍耀海東頭。","鹿胎冠子水晶簪，長嘯欹眠紫桂陰。","躞蹀馬搖金絡腦，嬋娟人墜玉搔頭。","狂歌放飲渾成性，知道逍遙出俗籠。","除却洛陽才子後，更誰封恨弔懷沙。","蓮浦浪澄堪倚釣，柳堤風煖好垂鞭。","上馬等閑銷白日，出門輕薄倚黃金。","淨名方丈雖然病，曼倩年涯未有多。"]', '["相逢多是醉醺然，應有囊中子母錢。","有兴欲沽紅麴酒，無人同上翠旌楼。","星斗離披煙靄收，玉蟾蜍耀海东头。","鹿胎冠子水晶簪，长嘯欹眠紫桂陰。","躞蹀马搖金絡腦，嬋娟人墜玉搔头。","狂歌放饮渾成性，知道逍遙出俗籠。","除却洛陽才子後，更誰封恨弔懷沙。","蓮浦浪澄堪倚釣，柳堤风煖好垂鞭。","上马等闲銷白日，出门轻薄倚黄金。","淨名方丈雖然病，曼倩年涯未有多。"]', '诗', 'shi', '', NULL, '句 褚載 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de3cc60e-ea13-44f0-b7c0-725b667f622d', '代寄邊人', '代寄邊人', '3a1da7a7-f386-41fb-a96d-1bbe11ded0a7', '唐', '["君去不來久，悠悠昏又明。","片心因卜解，殘夢過橋驚。","聖澤如垂餌，沙場會息兵。","涼風當爲我，一一送砧聲。"]', '["君去不来久，悠悠昏又明。","片心因卜解，殘梦過橋驚。","聖澤如垂餌，沙場會息兵。","涼风當爲我，一一送砧声。"]', '诗', 'shi', '', NULL, '代寄邊人 鄭準 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15a1dcdf-2408-4b8c-8d2b-a49292322825', '江南清明', '江南清明', '3a1da7a7-f386-41fb-a96d-1bbe11ded0a7', '唐', '["吳山楚驛四年中，一見清明一改容。","旅恨共風連夜起，韶光隨酒著人濃。","延興門外攀花別，采石江頭帶雨逢。","無限歸心何計是，路邊戈甲正重重。"]', '["吳山楚驛四年中，一见清明一改容。","旅恨共风連夜起，韶光隨酒著人濃。","延兴门外攀花別，采石江头带雨逢。","無限归心何計是，路邊戈甲正重重。"]', '诗', 'shi', '', NULL, '江南清明 鄭準 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c91dcfa-8204-473d-8e36-e5b717c19618', '題宛陵北樓', '題宛陵北楼', '3a1da7a7-f386-41fb-a96d-1bbe11ded0a7', '唐', '["雨來風靜綠蕪蘚，凭著朱闌思浩然。","人語獨耕燒後嶺，鳥飛斜沒望中煙。","松梢半露藏雲寺，灘勢橫流出浦船。","若遣謝宣城不死，必應吟盡夕陽川。"]', '["雨来风静綠蕪蘚，凭著朱闌思浩然。","人語独耕燒後嶺，鸟飞斜沒望中煙。","松梢半露藏云寺，灘勢橫流出浦船。","若遣謝宣城不死，必應吟尽夕陽川。"]', '诗', 'shi', '', NULL, '題宛陵北樓 鄭準 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68a5b50d-5f64-4d9a-a87e-dc0e196b637f', '寄進士崔魯範', '寄進士崔魯範', '3a1da7a7-f386-41fb-a96d-1bbe11ded0a7', '唐', '["洛陽才子舊交知，別後干戈積詠思。","百戰市朝千里夢，三年風月幾篇詩。","山高鴈斷音書絕，谷背鶯寒變化遲。","會待路寧歸得去，酒樓漁浦重相期。"]', '["洛陽才子旧交知，別後干戈積詠思。","百戰市朝千里梦，三年风月幾篇诗。","山高鴈斷音书絕，谷背鶯寒变化遲。","會待路寧归得去，酒楼漁浦重相期。"]', '诗', 'shi', '', NULL, '寄進士崔魯範 鄭準 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9d8a198-a249-4b1a-9b64-6351c6cf60c9', '雲', '云', '3a1da7a7-f386-41fb-a96d-1bbe11ded0a7', '唐', '["片片飛來靜又閑，樓頭江上復山前。","飄零盡日不歸去，點破清光萬里天。"]', '["片片飞来静又闲，楼头江上复山前。","飄零尽日不归去，点破清光万里天。"]', '诗', 'shi', '', NULL, '雲 鄭準 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('daea56eb-6552-41c0-a81d-0d4caef1290d', '句', '句', '3a1da7a7-f386-41fb-a96d-1bbe11ded0a7', '唐', '["護犢橫身立，逢人揭尾跳。"]', '["護犢橫身立，逢人揭尾跳。"]', '诗', 'shi', '', NULL, '句 鄭準 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f810a9a-ddc4-4771-a288-d3d35fac18fa', '游九鯉湖', '游九鯉湖', '7e401c77-7030-451b-9695-488b497dc59a', '唐', '["汗漫乘春至，林巒霧雨生。","洞莓黏屐重，巖雪濺衣輕。","窟宅分三島，煙霞接五城。","却憐饒藥物，欲辨不知名。"]', '["汗漫乘春至，林巒霧雨生。","洞莓黏屐重，巖雪濺衣轻。","窟宅分三島，煙霞接五城。","却怜饒藥物，欲辨不知名。"]', '诗', 'shi', '', NULL, '游九鯉湖 陳乘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19796737-ec7b-4c33-8df4-a81a7ca2cc10', '章臺夜思', '章台夜思', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["清瑟怨遙夜，遶弦風雨哀。","孤燈聞楚角，殘月下章臺。","芳草已云暮，故人殊未來。","鄉書不可寄，秋雁又南迴。"]', '["清瑟怨遙夜，遶弦风雨哀。","孤灯闻楚角，殘月下章台。","芳草已云暮，故人殊未来。","乡书不可寄，秋雁又南迴。"]', '诗', 'shi', '', NULL, '章臺夜思 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1fcfa0d-04ce-41fa-8148-1a78c8620b33', '延興門外作', '延兴门外作', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["芳草五陵道，美人金犢車。","綠奔穿內水，紅落過牆花。","馬足倦遊客，鳥聲歡酒家。","王孫歸去晚，宮樹欲棲鴉。"]', '["芳草五陵道，美人金犢车。","綠奔穿內水，紅落過牆花。","马足倦游客，鸟声歡酒家。","王孫归去晚，宮樹欲棲鴉。"]', '诗', 'shi', '', NULL, '延興門外作 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0578ce96-e47d-42ed-87b7-e121be9c2c80', '劉得仁墓', '劉得仁墓', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["至公遺至藝，終抱至冤沈。","名有詩家業，身無戚里心。","桂和秋露滴，松帶夜風吟。","冥寞知春否，墳蒿日已深。"]', '["至公遺至藝，終抱至冤沈。","名有诗家業，身無戚里心。","桂和秋露滴，松带夜风吟。","冥寞知春否，墳蒿日已深。"]', '诗', 'shi', '', NULL, '劉得仁墓 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ebacbee-c8ec-4fce-ab49-b116472ece92', '下第題青龍寺僧房', '下第題青龙寺僧房', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["千蹄萬轂一枝芳，要路無媒果自傷。","題柱未期歸蜀國，曳裾何處謁吳王。","馬嘶春陌金羈鬧，鳥睡花林繡羽香。","酒薄恨濃消不得，却將惆悵問支郎。"]', '["千蹄万轂一枝芳，要路無媒果自傷。","題柱未期归蜀国，曳裾何处謁吳王。","马嘶春陌金羈鬧，鸟睡花林繡羽香。","酒薄恨濃消不得，却將惆悵问支郎。"]', '诗', 'shi', '', NULL, '下第題青龍寺僧房 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbb27644-13d7-4dc8-b7ea-1662c3ec8d7a', '虢州澗東村居作', '虢州澗东村居作', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["東南騎馬出郊坰，迴首寒煙隔郡城。","清澗漲時翹鷺喜，綠桑疎處哺牛鳴。","兒童見少生於客，奴僕驕多倨似兄。","試望家田還自適，滿畦秋水稻苗平。"]', '["东南騎马出郊坰，迴首寒煙隔郡城。","清澗漲时翹鷺喜，綠桑疎处哺牛鳴。","兒童见少生於客，奴僕驕多倨似兄。","試望家田還自適，满畦秋水稻苗平。"]', '诗', 'shi', '', NULL, '虢州澗東村居作 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c695ad47-3bc4-47d0-9d5b-e0fc683cf99a', '送日本國僧敬龍歸', '送日本国僧敬龙归', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["扶桑已在渺茫中，家在扶桑東更東。","此去與師誰共到，一船明月一帆風。"]', '["扶桑已在渺茫中，家在扶桑东更东。","此去與師誰共到，一船明月一帆风。"]', '诗', 'shi', '', NULL, '送日本國僧敬龍歸 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f16577e3-e581-4a34-9105-68bc6c616f8b', '對酒', '对酒', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["何用巖棲隱姓名，一壺春酎可忘形。","伯倫若有長生術，直到如今醉未醒。"]', '["何用巖棲隐姓名，一壺春酎可忘形。","伯倫若有长生術，直到如今醉未醒。"]', '诗', 'shi', '', NULL, '對酒 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f41e46d5-144e-435b-bbfc-b159a972d3f0', '尹喜宅', '尹喜宅', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["荒原秋殿柏蕭蕭，何代風煙占寂寥。","紫氣已隨僊仗去，白雲空向帝鄉消。","濛濛暮雨春雞唱，漠漠寒蕪雪兔跳。","欲問靈蹤無處所，十洲空闊閬山遙。"]', '["荒原秋殿柏蕭蕭，何代风煙占寂寥。","紫氣已隨僊仗去，白云空向帝乡消。","濛濛暮雨春雞唱，漠漠寒蕪雪兔跳。","欲问靈蹤無处所，十洲空闊閬山遙。"]', '诗', 'shi', '', NULL, '尹喜宅 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c78efd18-5597-4f1e-973e-718be02dbf85', '途中望雨懷歸', '途中望雨懷归', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["滿空寒雨漫霏霏，去路雲深鎖翠微。","牧豎遠當煙草立，飢禽閑傍渚田飛。","誰家樹壓紅榴折，幾處籬懸白菌肥。","對此不堪鄉外思，荷蓑遙羨釣人歸。"]', '["满空寒雨漫霏霏，去路云深鎖翠微。","牧豎远當煙草立，飢禽闲傍渚田飞。","誰家樹壓紅榴折，幾处籬懸白菌肥。","对此不堪乡外思，荷蓑遙羨釣人归。"]', '诗', 'shi', '', NULL, '途中望雨懷歸 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aacef7e5-0597-435e-9477-d5d1b5ed52ea', '古離別', '古離別', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["晴煙漠漠柳毿毿，不那離情酒半酣。","更把玉鞭雲外指，斷腸春色在江南。"]', '["晴煙漠漠柳毿毿，不那離情酒半酣。","更把玉鞭云外指，斷腸春色在江南。"]', '诗', 'shi', '', NULL, '古離別 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88e88209-9ec7-4c53-a45d-bc1c71c41ad9', '柳谷道中作却寄', '柳谷道中作却寄', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["馬前紅葉正紛紛，馬上離情斷殺魂。","曉發獨辭殘月店，暮程遙宿隔雲村。","心如岳色留秦地，夢逐河聲出禹門。","莫怪苦吟鞭拂地，有誰傾蓋待王孫。"]', '["马前紅葉正紛紛，马上離情斷殺魂。","晓發独辞殘月店，暮程遙宿隔云村。","心如岳色留秦地，梦逐河声出禹门。","莫怪苦吟鞭拂地，有誰傾蓋待王孫。"]', '诗', 'shi', '', NULL, '柳谷道中作却寄 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97dc6198-117c-4477-bfc2-cbd459beea85', '灞陵道中作', '灞陵道中作', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["春橋南望水溶溶，一桁晴山倒碧峰。","秦苑落花零露濕，灞陵新酒撥醅濃。","青龍夭矯盤雙闕，丹鳳䙰褷隔九重。","萬古行人離別地，不堪吟罷夕陽鐘。"]', '["春橋南望水溶溶，一桁晴山倒碧峰。","秦苑落花零露濕，灞陵新酒撥醅濃。","青龙夭矯盤雙闕，丹鳳䙰褷隔九重。","万古行人離別地，不堪吟罷夕陽鐘。"]', '诗', 'shi', '', NULL, '灞陵道中作 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee87bdd8-28b3-4493-9bc3-01fe63bba60a', '秋日早行', '秋日早行', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["上馬蕭蕭襟袖涼，路穿禾黍繞宮牆。","半山殘月露華冷，一岸野風蓮萼香。","煙外驛樓紅隱隱，渚邊雲樹暗蒼蒼。","行人自是心如火，兔走烏飛不覺長。"]', '["上马蕭蕭襟袖涼，路穿禾黍繞宮牆。","半山殘月露华冷，一岸野风蓮萼香。","煙外驛楼紅隐隐，渚邊云樹暗蒼蒼。","行人自是心如火，兔走烏飞不覺长。"]', '诗', 'shi', '', NULL, '秋日早行 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c4b5ce2-82b8-4acc-954d-6d1ed661a01d', '歎落花', '歎落花', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["一夜霏微露濕煙，曉來和淚喪嬋娟。","不隨殘雪埋芳草，盡逐香風上舞筵。","西子去時遺笑靨，謝娥行處落金鈿。","飄紅墮白堪惆悵，少別穠華又隔年。"]', '["一夜霏微露濕煙，晓来和泪喪嬋娟。","不隨殘雪埋芳草，尽逐香风上舞筵。","西子去时遺笑靨，謝娥行处落金鈿。","飄紅墮白堪惆悵，少別穠华又隔年。"]', '诗', 'shi', '', NULL, '歎落花 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4571e043-116b-49c1-afd2-a5c6dd75bc8e', '宮怨', '宮怨', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["一辭同輦閉昭陽，耿耿寒宵禁漏長。","釵上翠禽應不返，鏡中紅豔豈重芳。","螢低夜色棲瑤草，水咽秋聲傍粉牆。","展轉令人思蜀賦，解將惆悵感君王。"]', '["一辞同輦閉昭陽，耿耿寒宵禁漏长。","釵上翠禽應不返，镜中紅豔豈重芳。","螢低夜色棲瑤草，水咽秋声傍粉牆。","展轉令人思蜀賦，解將惆悵感君王。"]', '诗', 'shi', '', NULL, '宮怨 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd4ebf0e-e152-452f-be15-f74881482926', '關河道中', '关河道中', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["槐陌蟬聲柳市風，驛樓高倚夕陽東。","往來千里路長在，聚散十年人不同。","但見時光流似箭，豈知天道曲如弓。","平生志業匡堯舜，又擬滄浪學釣翁。"]', '["槐陌蟬声柳市风，驛楼高倚夕陽东。","往来千里路长在，聚散十年人不同。","但见时光流似箭，豈知天道曲如弓。","平生志業匡堯舜，又擬滄浪学釣翁。"]', '诗', 'shi', '', NULL, '關河道中 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d7ee7bd-5036-4918-8b16-f0d9bb13a390', '題盤豆驛水館後軒', '題盤豆驛水館後軒', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["極目晴川展畫屏，地從桃塞接蒲城。","灘頭鷺占清波立，原上人侵落照耕。","去鴈數行天際沒，孤雲一點淨中生。","馮軒盡日不迴首，楚水吳山無限情。"]', '["極目晴川展畫屏，地從桃塞接蒲城。","灘头鷺占清波立，原上人侵落照耕。","去鴈數行天際沒，孤云一点淨中生。","馮軒尽日不迴首，楚水吳山無限情。"]', '诗', 'shi', '', NULL, '題盤豆驛水館後軒 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ff493ba-d9f5-46d8-8178-b4c96945dd50', '梁氏水齋', '梁氏水斋', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["獨醉任騰騰，琴棊亦自能。","卷簾山對客，開戶犬迎僧。","看蟻移苔穴，聞蛙落石層。","夜窗風雨急，松外一菴燈。"]', '["独醉任腾腾，琴棊亦自能。","卷簾山对客，开戶犬迎僧。","看蟻移苔穴，闻蛙落石層。","夜窗风雨急，松外一菴灯。"]', '诗', 'shi', '', NULL, '梁氏水齋 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28a42cb7-3941-46f8-98cc-f850fc9a2695', '曲池作', '曲池作', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["細雨曲池濱，青袍草色新。","詠詩行信馬，載酒喜逢人。","性爲無機率，家因守道貧。","若無詩自遣，誰奈寂寥春。"]', '["細雨曲池濱，青袍草色新。","詠诗行信马，載酒喜逢人。","性爲無機率，家因守道貧。","若無诗自遣，誰奈寂寥春。"]', '诗', 'shi', '', NULL, '曲池作 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b73ea2d1-d49b-4741-96ac-683ee5d89cc0', '嘉會里閑居', '嘉會里闲居', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["豈知城闕內，有地出紅塵。","草占一方綠，樹藏千古春。","馬嘶遊寺客，犬吠探花人。","寂寂無鐘鼓，槐行接紫宸。"]', '["豈知城闕內，有地出紅塵。","草占一方綠，樹藏千古春。","马嘶游寺客，犬吠探花人。","寂寂無鐘鼓，槐行接紫宸。"]', '诗', 'shi', '', NULL, '嘉會里閑居 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2007c906-bd55-4a7b-a62f-fa9601a8fdd6', '夏夜', '夏夜', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["傍水遷書榻，開襟納夜涼。","星繁愁晝熱，露重覺荷香。","蛙吹鳴還息，蛛羅滅又光。","正吟秋興賦，桐景下西牆。"]', '["傍水遷书榻，开襟納夜涼。","星繁愁晝熱，露重覺荷香。","蛙吹鳴還息，蛛羅滅又光。","正吟秋兴賦，桐景下西牆。"]', '诗', 'shi', '', NULL, '夏夜 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d61453ff-8d17-4621-9105-efaccfe4140f', '早發', '早發', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["早霧濃於雨，田深黍稻低。","出門雞未唱，過客馬頻嘶。","樹色遙藏店，泉聲暗傍畦。","獨吟三十里，城月尚如珪。"]', '["早霧濃於雨，田深黍稻低。","出门雞未唱，過客马頻嘶。","樹色遙藏店，泉声暗傍畦。","独吟三十里，城月尚如珪。"]', '诗', 'shi', '', NULL, '早發 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b94137b-109a-4e54-b5e6-016650363115', '寓言', '寓言', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["黃金日日銷還鑄，僊桂年年折又生。","兔走烏飛如未息，路塵終見泰山平。"]', '["黄金日日銷還鑄，僊桂年年折又生。","兔走烏飞如未息，路塵終见泰山平。"]', '诗', 'shi', '', NULL, '寓言 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7128e591-fe45-4c8a-a62a-1d5bd70c34e4', '對雪獻薛常侍', '对雪獻薛常侍', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["璚林瑤樹忽珊珊，急帶西風下晚天。","皓鶴䙰褷飛不辨，玉山重疊凍相連。","松裝粉穗臨窗亞，水結冰錐簇溜懸。","門外寒光利如劒，莫推紅袖訴金船。"]', '["璚林瑤樹忽珊珊，急带西风下晚天。","皓鹤䙰褷飞不辨，玉山重叠凍相連。","松裝粉穗臨窗亞，水結冰錐簇溜懸。","门外寒光利如劒，莫推紅袖訴金船。"]', '诗', 'shi', '', NULL, '對雪獻薛常侍 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fd2ae64-6557-4c30-8710-97197adf4396', '題裴端公郊居', '題裴端公郊居', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["暫隨紅斾佐藩方，高跡終期臥故鄉。","已近水聲開澗戶，更侵山色架書堂。","蒲生岸脚青刀利，柳拂波心綠帶長。","莫奪野人樵牧興，白雲不識繡衣郎。"]', '["暫隨紅斾佐藩方，高跡終期臥故乡。","已近水声开澗戶，更侵山色架书堂。","蒲生岸脚青刀利，柳拂波心綠带长。","莫奪野人樵牧兴，白云不識繡衣郎。"]', '诗', 'shi', '', NULL, '題裴端公郊居 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('341cc81b-916f-4758-af25-5f3210ea07c0', '登咸陽縣樓望雨', '登咸陽縣楼望雨', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["亂雲如獸出山前，細雨和風滿渭川。","盡日空濛無所見，鴈行斜去字聯聯。"]', '["亂云如獸出山前，細雨和风满渭川。","尽日空濛無所见，鴈行斜去字聯聯。"]', '诗', 'shi', '', NULL, '登咸陽縣樓望雨 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae555063-274e-40e3-bd1c-8236d997be67', '貴公子', '貴公子', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["大道青樓御苑東，玉欄仙杏壓枝紅。","金鈴犬吠梧桐月，朱鬣馬嘶楊柳風。","流水帶花穿巷陌，夕陽和樹入簾櫳。","瑤池宴罷歸來醉，笑說君王在月宮。"]', '["大道青楼御苑东，玉欄仙杏壓枝紅。","金鈴犬吠梧桐月，朱鬣马嘶楊柳风。","流水带花穿巷陌，夕陽和樹入簾櫳。","瑤池宴罷归来醉，笑说君王在月宮。"]', '诗', 'shi', '', NULL, '貴公子 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e23452a2-d247-4ae7-8e77-9df47613815c', '聽趙秀才彈琴', '听趙秀才彈琴', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["滿匣冰泉咽又鳴，玉音閑澹入神清。","巫山夜雨弦中起，湘水清波指下生。","蜂簇野花吟細韻，蟬移高柳迸殘聲。","不須更奏幽蘭曲，卓氏門前月正明。"]', '["满匣冰泉咽又鳴，玉音闲澹入神清。","巫山夜雨弦中起，湘水清波指下生。","蜂簇野花吟細韻，蟬移高柳迸殘声。","不須更奏幽蘭曲，卓氏门前月正明。"]', '诗', 'shi', '', NULL, '聽趙秀才彈琴 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30dd45f4-f14e-4ee2-b3d6-5a744bf6bfb3', '觀獵', '观獵', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["苑牆東畔欲斜暉，傍苑穿花兔正肥。","公子喜逢朝罷日，將軍誇換戰時衣。","鶻翻錦翅雲中落，犬帶金鈴草上飛。","直待四郊高鳥盡，掉鞍齊向國門歸。"]', '["苑牆东畔欲斜暉，傍苑穿花兔正肥。","公子喜逢朝罷日，將軍誇換戰时衣。","鶻翻錦翅云中落，犬带金鈴草上飞。","直待四郊高鸟尽，掉鞍齊向国门归。"]', '诗', 'shi', '', NULL, '觀獵 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa88d19a-2195-4674-9fe0-b4211a37fc59', '三堂東湖作', '三堂东湖作', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["滿塘秋水碧泓澄，十畝菱花晚鏡清。","景動新橋橫蝃蝀，岸鋪芳草睡鵁鶄。","蟾投夜魄當湖落，嶽倒秋蓮入浪生。","何處最添詩客興，黃昏煙雨亂蛙聲。"]', '["满塘秋水碧泓澄，十畝菱花晚镜清。","景动新橋橫蝃蝀，岸鋪芳草睡鵁鶄。","蟾投夜魄當湖落，嶽倒秋蓮入浪生。","何处最添诗客兴，黄昏煙雨亂蛙声。"]', '诗', 'shi', '', NULL, '三堂東湖作 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8f7fe0f-18e9-4a98-ab4b-246b74da1a48', '放榜日作', '放榜日作', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["一聲天鼓闢金扉，三十仙材上翠微。","葛水霧中龍乍變，緱山煙外鶴初飛。","鄒陽暖豔催花發，太皞春光簇馬歸。","迴首便辭塵土世，彩雲新換六銖衣。"]', '["一声天鼓闢金扉，三十仙材上翠微。","葛水霧中龙乍变，緱山煙外鹤初飞。","鄒陽暖豔催花發，太皞春光簇马归。","迴首便辞塵土世，彩云新換六銖衣。"]', '诗', 'shi', '', NULL, '放榜日作 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc3cf179-d61d-4306-bac2-8ff84da1e618', '寄薛先輩', '寄薛先輩', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["懸知迴日綵衣榮，仙籍高標第一名。","瑤樹帶風侵物冷，玉山和雨射人清。","龍翻瀚海波濤壯，鶴出金籠燕雀驚。","不說文章與門地，自然毛骨是公卿。"]', '["懸知迴日綵衣榮，仙籍高標第一名。","瑤樹带风侵物冷，玉山和雨射人清。","龙翻瀚海波濤壯，鹤出金籠燕雀驚。","不说文章與门地，自然毛骨是公卿。"]', '诗', 'shi', '', NULL, '寄薛先輩 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c84f1b9-e458-402b-9db5-5e31ba932e14', '訪含弘山僧不遇留題精舍', '訪含弘山僧不遇留題精舍', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["滿院桐花鳥雀喧，寂寥芳草茂芊芊。","吾師正遇歸山日，閑客空題到寺年。","池竹閉門教鶴守，琴書開篋任僧傳。","人間不自尋行跡，一片孤雲在碧天。"]', '["满院桐花鸟雀喧，寂寥芳草茂芊芊。","吾師正遇归山日，闲客空題到寺年。","池竹閉门教鹤守，琴书开篋任僧傳。","人间不自尋行跡，一片孤云在碧天。"]', '诗', 'shi', '', NULL, '訪含弘山僧不遇留題精舍 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('282d9d1f-119e-48fc-bd7b-bd0fb9be355b', '寄從兄遵', '寄從兄遵', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["江上秋風正釣鱸，九重天子夢翹車。","不將高臥邀劉主，自吐清談護漢儲。","滄海十年龍景斷，碧雲千里雁行疎。","相逢莫話歸山計，明日東封待直廬。"]', '["江上秋风正釣鱸，九重天子梦翹车。","不將高臥邀劉主，自吐清談護漢儲。","滄海十年龙景斷，碧云千里雁行疎。","相逢莫話归山計，明日东封待直廬。"]', '诗', 'shi', '', NULL, '寄從兄遵 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78bc34ed-50c2-4a21-b469-fc03fd08d186', '漁塘十六韻', '漁塘十六韻', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["洛水分餘脈，穿巖出石稜。","碧經嵐氣重，清帶露華澄。","瑩澈通三島，巖梧積萬層。","巢由應共到，劉阮想同登。","壁峻苔如畫，山昏霧似蒸。","撼松衣有雪，題石硯生冰。","路熟雲中客，名留域外僧。","飢猿尋落橡，鬬鼠墮高藤。","嶮樹臨溪亞，殘莎帶岸崩。","持竿聊藉草，待月好垂罾。","對景思任父，開圖想不興。","晚風輕浪疊，暮雨濕煙凝。","似泛靈槎出，如迎羽客昇。","仙源終不測，勝概自相仍。","欲別誠堪戀，長歸又未能。","他時操史筆，爲爾著良稱。"]', '["洛水分餘脈，穿巖出石稜。","碧經嵐氣重，清带露华澄。","瑩澈通三島，巖梧積万層。","巢由應共到，劉阮想同登。","壁峻苔如畫，山昏霧似蒸。","撼松衣有雪，題石硯生冰。","路熟云中客，名留域外僧。","飢猿尋落橡，鬬鼠墮高藤。","嶮樹臨溪亞，殘莎带岸崩。","持竿聊藉草，待月好垂罾。","对景思任父，开圖想不兴。","晚风轻浪叠，暮雨濕煙凝。","似泛靈槎出，如迎羽客昇。","仙源終不測，勝概自相仍。","欲別誠堪戀，长归又未能。","他时操史笔，爲爾著良稱。"]', '诗', 'shi', '', NULL, '漁塘十六韻 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04a0b9d9-04e7-423f-ac07-52a3714aaaee', '冬日長安感志寄獻虢州崔郎中二十韻', '冬日长安感志寄獻虢州崔郎中二十韻', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["帝里無成久滯淹，別家三度見新蟾。","郄詵丹桂無人指，阮籍青襟有淚霑。","溪上却思雲滿屋，鏡中惟怕雪生髯。","病如原憲誰能療，蹇似劉楨豈用占。","霧雨十年同隱遁，風雷何日振沈潛。","吁嗟每被更聲引，歌詠還因酒思添。","客舍正甘愁寂寂，郡樓遙想醉懨懨。","已聞鈴閣懸新詔，即向綸闈副具瞻。","濟物便同川上檝，慰心還似邑中黔。","觀星始覺中郎貴，問俗方知太守廉。","宅後綠波棲畫鷁，馬前紅袖簇丹襜。","閑招好客斟香蟻，悶對瓊花詠散鹽。","積凍慢封寒霤細，暮雲高拔遠峰尖。","訟堂無事冰生印，水榭高吟月透簾。","松下圍棋期褚胤，筆頭飛箭薦陶謙。","未知匣劒何時躍，但恐鉛刀不再銛。","雖有遠心長擁篲，恥將新劒學編苫。","纔驚素節移銅律，又見玄冥變玉籤。","百口似萍依廣岸，一身如燕戀高簷。","如今正困風波力，更向人中問宋纖。"]', '["帝里無成久滯淹，別家三度见新蟾。","郄詵丹桂無人指，阮籍青襟有泪霑。","溪上却思云满屋，镜中惟怕雪生髯。","病如原憲誰能療，蹇似劉楨豈用占。","霧雨十年同隐遁，风雷何日振沈潛。","吁嗟每被更声引，歌詠還因酒思添。","客舍正甘愁寂寂，郡楼遙想醉懨懨。","已闻鈴閣懸新詔，即向綸闈副具瞻。","濟物便同川上檝，慰心還似邑中黔。","观星始覺中郎貴，问俗方知太守廉。","宅後綠波棲畫鷁，马前紅袖簇丹襜。","闲招好客斟香蟻，悶对瓊花詠散鹽。","積凍慢封寒霤細，暮云高拔远峰尖。","訟堂無事冰生印，水榭高吟月透簾。","松下圍棋期褚胤，笔头飞箭薦陶謙。","未知匣劒何时躍，但恐鉛刀不再銛。","雖有远心长擁篲，恥將新劒学編苫。","纔驚素節移銅律，又见玄冥变玉籤。","百口似萍依廣岸，一身如燕戀高簷。","如今正困风波力，更向人中问宋纖。"]', '诗', 'shi', '', NULL, '冬日長安感志寄獻虢州崔郎中二十韻 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfe2a0ac-2b27-4b06-9d04-479d73445559', '和薛先輩見寄初秋寓懷即事之作二十韻', '和薛先輩见寄初秋寓懷即事之作二十韻', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["玉律初移候，清風乍遠襟。","一聲蟬到耳，千炬火然心。","嶽靜雲堆翠，樓高日半沈。","引愁憎暮角，驚夢怯殘碪。","露白凝湘簟，風篁韻蜀琴。","鳥喧從果爛，堦淨任苔侵。","柿葉添紅景，槐柯減綠陰。","採珠逢寶窟，閱石見瑤林。","魯殿鏗寒玉，苔山激碎金。","郄堂流桂景，陳巷集車音。","名自張華顯，詞因葛亮吟。","水深龍易失，天遠鶴難尋。","鑒貌寧慙樂，論才豈謝任。","義心孤劒直，學海怒濤深。","既覩文兼質，翻疑古在今。","慙聞紆綠綬，即候挂朝簪。","晚樹連秋塢，斜陽映暮岑。","夜蟲方唧唧，疲馬正駸駸。","託跡同吳燕，依仁似越禽。","會隨仙羽化，香蟻且同斟。"]', '["玉律初移候，清风乍远襟。","一声蟬到耳，千炬火然心。","嶽静云堆翠，楼高日半沈。","引愁憎暮角，驚梦怯殘碪。","露白凝湘簟，风篁韻蜀琴。","鸟喧從果爛，堦淨任苔侵。","柿葉添紅景，槐柯減綠陰。","採珠逢寶窟，閱石见瑤林。","魯殿鏗寒玉，苔山激碎金。","郄堂流桂景，陳巷集车音。","名自張华显，词因葛亮吟。","水深龙易失，天远鹤难尋。","鑒貌寧慙乐，論才豈謝任。","義心孤劒直，学海怒濤深。","既覩文兼質，翻疑古在今。","慙闻紆綠綬，即候挂朝簪。","晚樹連秋塢，斜陽映暮岑。","夜蟲方唧唧，疲马正駸駸。","託跡同吳燕，依仁似越禽。","會隨仙羽化，香蟻且同斟。"]', '诗', 'shi', '', NULL, '和薛先輩見寄初秋寓懷即事之作二十韻 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0168e1a6-e2bb-4df0-8b06-76d3855eb1c6', '同舊韻', '同旧韻', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["大火收殘暑，清光漸惹襟。","謝莊千里思，張翰五湖心。","暮角迎風急，孤鐘向暝沈。","露滋三徑草，日動四鄰碪。","簟委班姬扇，蟬悲蔡琰琴。","方愁丹桂遠，已怯二毛侵。","甃石迴泉脈，移棊就竹陰。","觸絲蛛墮網，避隼鳥投林。","貌愧潘郎璧，文慙呂相金。","但埋酆獄氣，未發爨桐音。","靜笑劉琨舞，閑思阮籍吟。","野花和雨斸，怪石入雲尋。","跡竟終非切，幽閑且自任。","趨時慙藝薄，託質仰恩深。","美價方稀古，清名已絕今。","既聞留縞帶，詎肯擲蓍簪。","遲客虛高閣，迎僧出亂岑。","壯心徒戚戚，逸足自駸駸。","安羨倉中鼠，危同幕上禽。","期君調鼎鼐，他日俟羊斟。"]', '["大火收殘暑，清光漸惹襟。","謝莊千里思，張翰五湖心。","暮角迎风急，孤鐘向暝沈。","露滋三徑草，日动四鄰碪。","簟委班姬扇，蟬悲蔡琰琴。","方愁丹桂远，已怯二毛侵。","甃石迴泉脈，移棊就竹陰。","觸絲蛛墮網，避隼鸟投林。","貌愧潘郎璧，文慙呂相金。","但埋酆獄氣，未發爨桐音。","静笑劉琨舞，闲思阮籍吟。","野花和雨斸，怪石入云尋。","跡竟終非切，幽闲且自任。","趨时慙藝薄，託質仰恩深。","美價方稀古，清名已絕今。","既闻留縞带，詎肯擲蓍簪。","遲客虛高閣，迎僧出亂岑。","壯心徒戚戚，逸足自駸駸。","安羨倉中鼠，危同幕上禽。","期君調鼎鼐，他日俟羊斟。"]', '诗', 'shi', '', NULL, '同舊韻 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45a866f5-3aeb-447c-8677-6bb09127a78e', '三用韻', '三用韻', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["素律初迴馭，商飆暗觸襟。","乍傷詩客思，還動旅人心。","蟬噪因風斷，鱗遊見鷺沈。","笛聲隨晚吹，松韻激遙砧。","地覆青袍草，窗橫綠綺琴。","煙霄難自致，歲月易相侵。","澗柳橫孤彴，巖藤架密陰。","瀟湘期釣侶，鄠杜別家林。","遺愧虞卿璧，言依季布金。","錚鏦聞郢唱，次第發巴音。","螢影衝簾落，蟲聲擁砌吟。","樓高思共釣，寺遠想同尋。","入夜愁難遣，逢秋恨莫任。","蝸遊苔徑滑，鶴步翠塘深。","莫問榮兼辱，寧論古與今。","固窮憐甕牖，感舊惜蒿簪。","晚日舒霞綺，遙天倚黛岑。","鴛鸞方翽翽，驊驥整駸駸。","未化投陂竹，空思出谷禽。","感多聊自遣，桑落且閑斟。"]', '["素律初迴馭，商飆暗觸襟。","乍傷诗客思，還动旅人心。","蟬噪因风斷，鱗游见鷺沈。","笛声隨晚吹，松韻激遙砧。","地覆青袍草，窗橫綠綺琴。","煙霄难自致，歲月易相侵。","澗柳橫孤彴，巖藤架密陰。","瀟湘期釣侶，鄠杜別家林。","遺愧虞卿璧，言依季布金。","錚鏦闻郢唱，次第發巴音。","螢影衝簾落，蟲声擁砌吟。","楼高思共釣，寺远想同尋。","入夜愁难遣，逢秋恨莫任。","蝸游苔徑滑，鹤步翠塘深。","莫问榮兼辱，寧論古與今。","固窮怜甕牖，感旧惜蒿簪。","晚日舒霞綺，遙天倚黛岑。","鴛鸾方翽翽，驊驥整駸駸。","未化投陂竹，空思出谷禽。","感多聊自遣，桑落且闲斟。"]', '诗', 'shi', '', NULL, '三用韻 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aba16b50-122a-429e-8a0f-798c833ac89a', '驚秋', '驚秋', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["不向煙波狎釣舟，強親文墨事儒丘。","長安十二槐花陌，曾負秋風多少秋。"]', '["不向煙波狎釣舟，強親文墨事儒丘。","长安十二槐花陌，曾負秋风多少秋。"]', '诗', 'shi', '', NULL, '驚秋 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e71164ff-fe3e-4e76-b72a-1a73a3b68d6d', '登漢高廟閑眺', '登漢高廟闲眺', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["獨尋仙境上高原，雲雨深藏古帝壇。","天畔晚峰青簇簇，檻前春樹碧團團。","參差郭外樓臺小，斷續風中鼓角殘。","一帶遠光何處水，釣舟閑繫夕陽灘。"]', '["独尋仙境上高原，云雨深藏古帝壇。","天畔晚峰青簇簇，檻前春樹碧團團。","參差郭外楼台小，斷續风中鼓角殘。","一带远光何处水，釣舟闲繫夕陽灘。"]', '诗', 'shi', '', NULL, '登漢高廟閑眺 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('391c1a2e-26b6-436c-b381-0fd5b91459ac', '耒陽縣浮山神廟', '耒陽縣浮山神廟', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["一郡皆傳此廟靈，廟前松桂古今青。","山曾堯代浮洪水，地有唐臣奠綠醽。","遶坐香風吹寶蓋，傍簷煙雨濕巖扃。","爲霖自可成農歲，何用興師遠伐邢。"]', '["一郡皆傳此廟靈，廟前松桂古今青。","山曾堯代浮洪水，地有唐臣奠綠醽。","遶坐香风吹寶蓋，傍簷煙雨濕巖扃。","爲霖自可成農歲，何用兴師远伐邢。"]', '诗', 'shi', '', NULL, '耒陽縣浮山神廟 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76129a35-83f4-480b-882c-8c7494ff8418', '愁', '愁', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["避愁愁又至，愁至事難忘。","夜坐心中火，朝爲鬢上霜。","不經公子夢，偏入旅人腸。","借問高軒客，何鄉是醉鄉。"]', '["避愁愁又至，愁至事难忘。","夜坐心中火，朝爲鬢上霜。","不經公子梦，偏入旅人腸。","借问高軒客，何乡是醉乡。"]', '诗', 'shi', '', NULL, '愁 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7b0f701-dd12-444a-b384-36e8a3df0827', '村居書事', '村居书事', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["年年耕與釣，鷗鳥已相依。","砌長蒼苔厚，藤抽紫蔓肥。","風鶯移樹囀，雨燕入樓飛。","不覺春光暮，遶籬紅杏稀。"]', '["年年耕與釣，鷗鸟已相依。","砌长蒼苔厚，藤抽紫蔓肥。","风鶯移樹囀，雨燕入楼飞。","不覺春光暮，遶籬紅杏稀。"]', '诗', 'shi', '', NULL, '村居書事 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b75ba2fa-a99c-4aa1-ade3-6767de63a059', '三堂早春', '三堂早春', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["獨倚危樓四望遙，杏花春陌馬聲驕。","池邊冰刃暖初落，山上雪稜寒未銷。","溪送綠波穿郡宅，日移紅影度村橋。","主人年少多情味，笑換金龜解珥貂。"]', '["独倚危楼四望遙，杏花春陌马声驕。","池邊冰刃暖初落，山上雪稜寒未銷。","溪送綠波穿郡宅，日移紅影度村橋。","主人年少多情味，笑換金龟解珥貂。"]', '诗', 'shi', '', NULL, '三堂早春 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14d03922-3b13-455f-a125-c85be1edc20d', '雨霽晚眺', '雨霽晚眺', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["入谷路縈紆，巖巔日欲晡。","嶺雲寒埽蓋，溪雪凍黏鬚。","臥草跧如兔，聽冰怯似狐。","仍聞關外火，昨夜徹皇都。"]', '["入谷路縈紆，巖巔日欲晡。","嶺云寒埽蓋，溪雪凍黏鬚。","臥草跧如兔，听冰怯似狐。","仍闻关外火，昨夜徹皇都。"]', '诗', 'shi', '', NULL, '雨霽晚眺 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cba0871-ada5-4c97-a42e-5fc4814cbac3', '立春日作', '立春日作', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["九重天子去蒙塵，御柳無情依舊春。","今日不關妃妾事，始知辜負馬嵬人。"]', '["九重天子去蒙塵，御柳無情依旧春。","今日不关妃妾事，始知辜負马嵬人。"]', '诗', 'shi', '', NULL, '立春日作 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('652b31c5-7308-4f3c-83b1-911884c9cf37', '贈雲陽裴明府', '贈云陽裴明府', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["南北三年一解攜，海爲深谷岸爲蹊。","已聞陳勝心降漢，誰爲田橫國號齊。","暴客至今猶戰鶴，故人何處尚驅雞。","歸來能作煙波伴，我有魚舟在五溪。"]', '["南北三年一解携，海爲深谷岸爲蹊。","已闻陳勝心降漢，誰爲田橫国號齊。","暴客至今猶戰鹤，故人何处尚驱雞。","归来能作煙波伴，我有鱼舟在五溪。"]', '诗', 'shi', '', NULL, '贈雲陽裴明府 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5a14bc1-6d6f-4446-a552-ac36f35ea608', '賊中與蕭韋二秀才同臥重疾二君尋愈余獨加焉恍惚之中因有題', '賊中與蕭韋二秀才同臥重疾二君尋愈余独加焉恍惚之中因有題', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["與君同臥疾，獨我漸彌留。","弟妹不知處，兵戈殊未休。","胸中疑晉豎，耳下鬬殷牛。","縱有秦醫在，懷鄉亦淚流。"]', '["與君同臥疾，独我漸彌留。","弟妹不知处，兵戈殊未休。","胸中疑晉豎，耳下鬬殷牛。","縱有秦醫在，懷乡亦泪流。"]', '诗', 'shi', '', NULL, '賊中與蕭韋二秀才同臥重疾二君尋愈余獨加焉恍惚之中因有題 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a596faf4-a76a-4708-955f-cde90820f40a', '重圍中逢蕭校書', '重圍中逢蕭校书', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["相逢俱此地，此地是何鄉。","側目不成語，撫心空自傷。","劒高無鳥度，樹暗有兵藏。","底事征西將，年年戍洛陽。"]', '["相逢俱此地，此地是何乡。","側目不成語，撫心空自傷。","劒高無鸟度，樹暗有兵藏。","底事征西將，年年戍洛陽。"]', '诗', 'shi', '', NULL, '重圍中逢蕭校書 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e224462a-8d3d-46ce-9da8-b5cf2a41be56', '咸通', '咸通', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["咸通時代物情奢，歡殺金張許史家。","破產競留天上樂，鑄山爭買洞中花。","諸郎宴罷銀燈合，仙子遊迴璧月斜。","人意似知今日事，急催弦管送年華。"]', '["咸通时代物情奢，歡殺金張許史家。","破產競留天上乐，鑄山爭買洞中花。","諸郎宴罷銀灯合，仙子游迴璧月斜。","人意似知今日事，急催弦管送年华。"]', '诗', 'shi', '', NULL, '咸通 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25156cd0-3e55-4f5e-95f3-dc50702805cb', '白櫻桃', '白櫻桃', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["王母堦前種幾株，水精簾外看如無。","只應漢武金盤上，瀉得珊珊白露珠。"]', '["王母堦前種幾株，水精簾外看如無。","只應漢武金盤上，瀉得珊珊白露珠。"]', '诗', 'shi', '', NULL, '白櫻桃 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e5c0f56-def6-4fe7-8fb6-daec2302dc76', '夜景', '夜景', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["滿庭松桂雨餘天，宋玉秋聲韻蜀弦。","烏兔不知多事世，星辰長似太平年。","誰家一笛吹殘暑，何處雙砧擣暮煙。","欲把傷心問明月，素娥無語淚娟娟。"]', '["满庭松桂雨餘天，宋玉秋声韻蜀弦。","烏兔不知多事世，星辰长似太平年。","誰家一笛吹殘暑，何处雙砧擣暮煙。","欲把傷心问明月，素娥無語泪娟娟。"]', '诗', 'shi', '', NULL, '夜景 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4be1c589-2594-48bc-b8b7-0891ec06c553', '宿山家', '宿山家', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["山行侵夜到，雲竇一星燈。","草動蛇尋穴，枝搖鼠上藤。","背風開藥竈，向月展漁罾。","明日前溪路，煙蘿更幾層。"]', '["山行侵夜到，云竇一星灯。","草动蛇尋穴，枝搖鼠上藤。","背风开藥竈，向月展漁罾。","明日前溪路，煙蘿更幾層。"]', '诗', 'shi', '', NULL, '宿山家 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3551d6a5-61cf-41f3-8c28-586d1972ba8d', '長年', '长年', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["長年方悟少年非，人道新詩勝舊詩。","十畝野塘留客釣，一軒春雨對僧棊。","花間醉任黃鶯語，亭上吟從白鷺窺。","大盜不將爐冶去，有心重築太平基。"]', '["长年方悟少年非，人道新诗勝旧诗。","十畝野塘留客釣，一軒春雨对僧棊。","花间醉任黄鶯語，亭上吟從白鷺窺。","大盜不將爐冶去，有心重築太平基。"]', '诗', 'shi', '', NULL, '長年 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c27b7db3-d609-470f-848f-75bbb62805c4', '辛丑年', '辛丑年', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["九衢漂杵已成川，塞上黃雲戰馬閑。","但有羸兵填渭水，更無奇士出商山。","田園已沒紅塵裏，弟妹相逢白刃間。","西望翠華殊未返，淚痕空濕劒文斑。"]', '["九衢漂杵已成川，塞上黄云戰马闲。","但有羸兵填渭水，更無奇士出商山。","田园已沒紅塵裏，弟妹相逢白刃间。","西望翠华殊未返，泪痕空濕劒文斑。"]', '诗', 'shi', '', NULL, '辛丑年 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95982a81-b8b2-4910-bc0d-779e2d6b625b', '思歸', '思归', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["暖絲無力自悠揚，牽引東風斷客腸。","外地見花終寂寞，異鄉聞樂更淒涼。","紅垂野岸櫻還熟，綠染迴汀草又芳。","舊里若爲歸去好，子期凋謝呂安亡。"]', '["暖絲無力自悠揚，牽引东风斷客腸。","外地见花終寂寞，異乡闻乐更淒涼。","紅垂野岸櫻還熟，綠染迴汀草又芳。","旧里若爲归去好，子期凋謝呂安亡。"]', '诗', 'shi', '', NULL, '思歸 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0ffaa79-aabd-4959-8b6c-06cde607b6e0', '憶昔', '憶昔', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["昔年曾向五陵遊，子夜歌清月滿樓。","銀燭樹前長似晝，露桃華裏不知秋。","西園公子名無忌，南國佳人號莫愁。","今日亂離俱是夢，夕陽唯見水東流。"]', '["昔年曾向五陵游，子夜歌清月满楼。","銀燭樹前长似晝，露桃华裏不知秋。","西园公子名無忌，南国佳人號莫愁。","今日亂離俱是梦，夕陽唯见水东流。"]', '诗', 'shi', '', NULL, '憶昔 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb03ae35-3159-48f5-aaf4-babb55c56861', '合歡蓮花', '合歡蓮花', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["虞舜南巡去不歸，二妃相誓死江湄。","空留萬古香魂在，結作雙葩合一枝。"]', '["虞舜南巡去不归，二妃相誓死江湄。","空留万古香魂在，結作雙葩合一枝。"]', '诗', 'shi', '', NULL, '合歡蓮花 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f16392ac-04ba-4b7f-9028-a6df9c92f891', '覽蕭必先卷', '覽蕭必先卷', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["滿軸編新句，翛然大雅風。","名因五字得，命合一言通。","景盡才難盡，吟終意未終。","似逢曹與謝，煙雨思何窮。"]', '["满軸編新句，翛然大雅风。","名因五字得，命合一言通。","景尽才难尽，吟終意未終。","似逢曹與謝，煙雨思何窮。"]', '诗', 'shi', '', NULL, '覽蕭必先卷 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('912d1762-4c68-4d11-8ac7-06847e82585e', '和人歲宴旅舍見寄', '和人歲宴旅舍见寄', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["積雪滿前除，寒光夜皎如。","老憂新歲近，貧覺故交疎。","意合論文後，心降得句初。","莫言常鬱鬱，天道有盈虛。"]', '["積雪满前除，寒光夜皎如。","老憂新歲近，貧覺故交疎。","意合論文後，心降得句初。","莫言常鬱鬱，天道有盈虛。"]', '诗', 'shi', '', NULL, '和人歲宴旅舍見寄 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99ef9f58-02b0-4d36-9b48-5ca9877be158', '宿泊孟津寄三堂友人', '宿泊孟津寄三堂友人', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["解纜西征未有期，槐花又逼桂花時。","鴻臚陌上歸耕晚，金馬門前獻賦遲。","只恐愁苗生兩鬢，不堪離恨入雙眉。","分明昨夜南池夢，還把漁竿詠楚詞。"]', '["解纜西征未有期，槐花又逼桂花时。","鴻臚陌上归耕晚，金马门前獻賦遲。","只恐愁苗生兩鬢，不堪離恨入雙眉。","分明昨夜南池梦，還把漁竿詠楚词。"]', '诗', 'shi', '', NULL, '宿泊孟津寄三堂友人 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('917ca818-9789-4ac6-a44a-0713ad93ac62', '對酒賦友人', '对酒賦友人', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["多病仍多感，君心自我心。","浮生都是夢，浩歎不如吟。","白雪篇篇麗，清酤盞盞深。","亂離俱老大，強醉莫霑襟。"]', '["多病仍多感，君心自我心。","浮生都是梦，浩歎不如吟。","白雪篇篇丽，清酤盞盞深。","亂離俱老大，強醉莫霑襟。"]', '诗', 'shi', '', NULL, '對酒賦友人 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2086b2a0-555b-41a2-9827-ed1242d3415b', '天井關', '天井关', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["太行山上雲深處，誰向雲中築女牆。","短綆詎能垂玉甃，繚垣何用學金湯。","斸開嵐翠爲高壘，截斷雲霞作巨防。","守吏不教飛鳥過，赤眉何路到吾鄉。"]', '["太行山上云深处，誰向云中築女牆。","短綆詎能垂玉甃，繚垣何用学金湯。","斸开嵐翠爲高壘，截斷云霞作巨防。","守吏不教飞鸟過，赤眉何路到吾乡。"]', '诗', 'shi', '', NULL, '天井關 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aad6243a-b71a-41ad-927f-8ad6dd8d85fb', '贈邊將', '贈邊將', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["昔因征遠向金微，馬出榆關一鳥飛。","萬里只攜孤劒去，十年空逐塞鴻歸。","手招都護新降虜，身著文皇舊賜衣。","只待煙塵報天子，滿頭霜雪爲兵機。"]', '["昔因征远向金微，马出榆关一鸟飞。","万里只携孤劒去，十年空逐塞鴻归。","手招都護新降虜，身著文皇旧賜衣。","只待煙塵報天子，满头霜雪爲兵機。"]', '诗', 'shi', '', NULL, '贈邊將 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aeacc177-24c9-4559-b644-79ef2433536d', '春日', '春日', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["忽覺東風景漸遲，野梅山杏暗芳菲。","落星樓上吹殘角，偃月營中挂夕暉。","旅夢亂隨蝴蝶散，離魂漸逐杜鵑飛。","紅塵遮斷長安陌，芳草王孫暮不歸。"]', '["忽覺东风景漸遲，野梅山杏暗芳菲。","落星楼上吹殘角，偃月營中挂夕暉。","旅梦亂隨蝴蝶散，離魂漸逐杜鵑飞。","紅塵遮斷长安陌，芳草王孫暮不归。"]', '诗', 'shi', '', NULL, '春日 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0174e7f2-c0a8-4511-a9f9-464d09d60811', '早秋夜作', '早秋夜作', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["翠簟初清暑半銷，[撇]簾松韻送輕飆。","莎庭露永琴書潤，山郭月明砧杵遙。","傍砌綠苔鳴蟋蟀，遶簷紅樹織蠨蛸。","不須更作悲秋賦，王粲辭家鬢已凋。"]', '["翠簟初清暑半銷，[撇]簾松韻送轻飆。","莎庭露永琴书潤，山郭月明砧杵遙。","傍砌綠苔鳴蟋蟀，遶簷紅樹织蠨蛸。","不須更作悲秋賦，王粲辞家鬢已凋。"]', '诗', 'shi', '', NULL, '早秋夜作 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ecfb3a4-3770-4fec-aef5-2e0913f2f802', '寄江南逐客', '寄江南逐客', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["二年音信阻湘潭，花下相思酒半酣。","記得竹齋風雨夜，對牀孤枕話江南。"]', '["二年音信阻湘潭，花下相思酒半酣。","記得竹斋风雨夜，对牀孤枕話江南。"]', '诗', 'shi', '', NULL, '寄江南逐客 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92f860a9-4e7a-41bf-95b4-a9e4540fe816', '冬夜', '冬夜', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["睡覺寒爐酒半消，客情鄉夢兩遙遙。","無人爲我磨心劍，割斷愁腸一寸苗。"]', '["睡覺寒爐酒半消，客情乡梦兩遙遙。","無人爲我磨心劍，割斷愁腸一寸苗。"]', '诗', 'shi', '', NULL, '冬夜 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1a219a0-4303-47bd-8f7d-5ad817a2fd9d', '又聞湖南荆渚相次陷沒', '又闻湖南荆渚相次陷沒', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["幾時聞唱凱旋歌，處處屯兵未倒戈。","天子只憑紅斾壯，將軍空恃紫髯多。","屍填漢水連荆阜，血染湘雲接楚波。","莫問流離南越事，戰餘空有舊山河。"]', '["幾时闻唱凱旋歌，处处屯兵未倒戈。","天子只憑紅斾壯，將軍空恃紫髯多。","屍填漢水連荆阜，血染湘云接楚波。","莫问流離南越事，戰餘空有旧山河。"]', '诗', 'shi', '', NULL, '又聞湖南荆渚相次陷沒 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83f0e706-661d-4ef6-9a53-1944d56c1ae6', '家叔南遊却歸因獻賀', '家叔南游却归因獻賀', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["繚繞江南一歲歸，歸來行色滿戎衣。","長聞鳳詔徵兵急，何事龍韜獻捷稀。","旅夢遠依湘水闊，離魂空伴越禽飛。","遙知倚棹思家處，澤國煙深暮雨微。"]', '["繚繞江南一歲归，归来行色满戎衣。","长闻鳳詔徵兵急，何事龙韜獻捷稀。","旅梦远依湘水闊，離魂空伴越禽飞。","遙知倚棹思家处，澤国煙深暮雨微。"]', '诗', 'shi', '', NULL, '家叔南遊却歸因獻賀 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8614c7b-43e8-47f9-a77a-990a0e59ddd1', '楚行吟', '楚行吟', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["章華臺下草如煙，故郢城頭月似弦。","惆悵楚宮雲雨後，露啼花笑一年年。"]', '["章华台下草如煙，故郢城头月似弦。","惆悵楚宮云雨後，露啼花笑一年年。"]', '诗', 'shi', '', NULL, '楚行吟 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0aa6770d-4589-4db9-8b7e-68d4c8db9a39', '洛陽吟', '洛陽吟', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["萬戶千門夕照邊，開元時節舊風煙。","宮官試馬遊三市，舞女乘舟上九天。","胡騎北來空進主，漢皇西去竟昇僊。","如今父老偏垂淚，不見承平四十年。"]', '["万戶千门夕照邊，开元时節旧风煙。","宮官試马游三市，舞女乘舟上九天。","胡騎北来空進主，漢皇西去竟昇僊。","如今父老偏垂泪，不见承平四十年。"]', '诗', 'shi', '', NULL, '洛陽吟 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d95f013-cbb9-4bac-badc-a91b41151f59', '過舊宅', '過旧宅', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["華軒不見馬蕭蕭，廷尉門人久寂寥。","朱檻翠樓爲卜肆，玉欄僊杏作春樵。","堦前雨落鴛鴦瓦，竹裏苔封螮蝀橋。","莫問此中銷歇寺，娟娟紅淚滴芭蕉。"]', '["华軒不见马蕭蕭，廷尉门人久寂寥。","朱檻翠楼爲卜肆，玉欄僊杏作春樵。","堦前雨落鴛鴦瓦，竹裏苔封螮蝀橋。","莫问此中銷歇寺，娟娟紅泪滴芭蕉。"]', '诗', 'shi', '', NULL, '過舊宅 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f90f64be-4e9c-4d00-8278-d0e5a18cfb57', '喻東軍', '喻东軍', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["四年龍馭守峨嵋，鐵馬西來步步遲。","五運未教移漢鼎，六韜何必待秦師。","幾時鸞鳳歸丹闕，到處烏鳶從白旗。","獨把一樽和淚酒，隔雲遙奠武侯祠。"]', '["四年龙馭守峨嵋，鐵马西来步步遲。","五運未教移漢鼎，六韜何必待秦師。","幾时鸾鳳归丹闕，到处烏鳶從白旗。","独把一樽和泪酒，隔云遙奠武侯祠。"]', '诗', 'shi', '', NULL, '喻東軍 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('071805e2-1158-426d-991a-084bd39e197e', '清河縣樓作', '清河縣楼作', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["有客微吟獨凭樓，碧雲紅樹不勝愁。","盤鵰迥印天心沒，遠水斜牽日脚流。","千里戰塵連上苑，九江歸路隔東周。"]', '["有客微吟独凭楼，碧云紅樹不勝愁。","盤鵰迥印天心沒，远水斜牽日脚流。","千里戰塵連上苑，九江归路隔东周。"]', '诗', 'shi', '', NULL, '清河縣樓作 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82256c70-e7f2-43d6-93a8-46295905cb9f', '北原閑眺', '北原闲眺', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["春城迴首樹重重，立馬平原夕照中。","五鳳灰殘金翠滅，六龍遊去市朝空。","千年王氣浮清洛，萬古坤靈鎮碧嵩。","欲問向來陵谷事，野桃無語淚花紅。"]', '["春城迴首樹重重，立马平原夕照中。","五鳳灰殘金翠滅，六龙游去市朝空。","千年王氣浮清洛，万古坤靈鎮碧嵩。","欲问向来陵谷事，野桃無語泪花紅。"]', '诗', 'shi', '', NULL, '北原閑眺 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89c64a8a-8774-4ed9-9309-9253685d861c', '贈戍兵', '贈戍兵', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["漢皇無事暫遊汾，底事狐狸嘯作羣。","夜指碧天占晉分，曉磨孤劒望秦雲。","紅旌不卷風長急，畫角閑吹日又曛。","止竟有征須有戰，洛陽何用久屯軍。"]', '["漢皇無事暫游汾，底事狐狸嘯作羣。","夜指碧天占晉分，晓磨孤劒望秦云。","紅旌不卷风长急，畫角闲吹日又曛。","止竟有征須有戰，洛陽何用久屯軍。"]', '诗', 'shi', '', NULL, '贈戍兵 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23e623c7-9060-426d-b4d1-1ea9898d8903', '覩軍迴戈', '覩軍迴戈', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["關中羣盜已心離，關外猶聞羽檄飛。","御苑綠莎嘶戰馬，禁城寒月搗征衣。","漫教韓信兵塗地，不及劉琨嘯解圍。","昨日屯軍還夜遁，滿車空載洛神歸。"]', '["关中羣盜已心離，关外猶闻羽檄飞。","御苑綠莎嘶戰马，禁城寒月捣征衣。","漫教韓信兵塗地，不及劉琨嘯解圍。","昨日屯軍還夜遁，满车空載洛神归。"]', '诗', 'shi', '', NULL, '覩軍迴戈 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7068942-fab8-4511-8a9a-b83a1f290cb2', '中渡晚眺', '中渡晚眺', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["魏王堤畔草如煙，有客傷時獨扣舷。","妖氣欲昏唐社稷，夕陽空照漢山川。","千重碧樹籠春苑，萬縷紅霞襯碧天。","家寄杜陵歸不得，一迴回首一潸然。"]', '["魏王堤畔草如煙，有客傷时独扣舷。","妖氣欲昏唐社稷，夕陽空照漢山川。","千重碧樹籠春苑，万縷紅霞襯碧天。","家寄杜陵归不得，一迴回首一潸然。"]', '诗', 'shi', '', NULL, '中渡晚眺 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8ebd494-0f38-4fa3-b10b-c9f6382b8ab2', '河內別村業閑題', '河內別村業闲題', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["阮氏清風竹巷深，滿溪松竹似山陰。","門當谷路多樵客，地帶河聲足水禽。","閑伴爾曹雖適意，靜思吾道好霑襟。","鄰翁莫問傷時事，一曲高歌夕照沈。"]', '["阮氏清风竹巷深，满溪松竹似山陰。","门當谷路多樵客，地带河声足水禽。","闲伴爾曹雖適意，静思吾道好霑襟。","鄰翁莫问傷时事，一曲高歌夕照沈。"]', '诗', 'shi', '', NULL, '河內別村業閑題 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21aec4c7-4f49-49d2-83ac-5ff575f7e03a', '聞官軍繼至未覩凱旋', '闻官軍繼至未覩凱旋', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["嫖姚何日破重圍，秋草深來戰馬肥。","已有孔明傳將略，更聞王導得神機。","陣前鼙鼓晴應響，城上烏鳶飽不飛。","何事小臣偏注目，帝鄉遙羨白雲歸。"]', '["嫖姚何日破重圍，秋草深来戰马肥。","已有孔明傳將略，更闻王導得神機。","陣前鼙鼓晴應响，城上烏鳶飽不飞。","何事小臣偏注目，帝乡遙羨白云归。"]', '诗', 'shi', '', NULL, '聞官軍繼至未覩凱旋 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e55bbc83-e8c8-4f70-bb26-0b157899fe56', '和集賢侯學士分司丁侍御秋日雨霽之作', '和集賢侯学士分司丁侍御秋日雨霽之作', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["洛岸秋晴夕照長，鳳樓龍闕倚清光。","玉泉山淨雲初散，金谷樹多風正涼。","席上客知蓬島路，坐中寒有柏臺霜。","多慙十載遊梁士，却伴賓鴻入帝鄉。"]', '["洛岸秋晴夕照长，鳳楼龙闕倚清光。","玉泉山淨云初散，金谷樹多风正涼。","席上客知蓬島路，坐中寒有柏台霜。","多慙十載游梁士，却伴賓鴻入帝乡。"]', '诗', 'shi', '', NULL, '和集賢侯學士分司丁侍御秋日雨霽之作 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f70fedff-3edb-49ed-bb93-1c21fbf4d652', '題安定張使君', '題安定張使君', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["器度風標合出塵，桂宮何負一枝新。","成丹始見金無滓，衝斗方知劒有神。","憤氣不銷頭上雪，政聲空布海邊春。","中興若繼開元事，堪向龍池作近臣。"]', '["器度风標合出塵，桂宮何負一枝新。","成丹始见金無滓，衝斗方知劒有神。","憤氣不銷头上雪，政声空布海邊春。","中兴若繼开元事，堪向龙池作近臣。"]', '诗', 'shi', '', NULL, '題安定張使君 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a599e4b8-aea5-40ff-8395-0179ba2601d2', '潁陽縣', '潁陽縣', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["琴堂連少室，故事即僊蹤。","樹老風聲壯，山高臘候濃。","雪多庭有鹿，縣僻寺無鐘。","何處留詩客，茆簷倚後峰。"]', '["琴堂連少室，故事即僊蹤。","樹老风声壯，山高臘候濃。","雪多庭有鹿，縣僻寺無鐘。","何处留诗客，茆簷倚後峰。"]', '诗', 'shi', '', NULL, '潁陽縣 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8eb29d89-650a-490c-9052-d6164cb3c507', '寄園林主人', '寄园林主人', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["主人常不在，春物爲誰開。","桃豔紅將落，梨華雪又摧。","曉鶯閑自囀，遊客暮空回。","尚有餘芳在，猶堪載酒來。"]', '["主人常不在，春物爲誰开。","桃豔紅將落，梨华雪又摧。","晓鶯闲自囀，游客暮空回。","尚有餘芳在，猶堪載酒来。"]', '诗', 'shi', '', NULL, '寄園林主人 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74b53b6c-d8bb-4e6d-95de-a38ba7d230fb', '洛北村居', '洛北村居', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["十畝松篁百畝田，歸來方屬大兵年。","巖邊石室低臨水，雲外嵐峰半入天。","鳥勢去投金谷樹，鐘聲遙出上陽煙。","無人說得中興事，獨倚斜暉憶仲宣。"]', '["十畝松篁百畝田，归来方屬大兵年。","巖邊石室低臨水，云外嵐峰半入天。","鸟勢去投金谷樹，鐘声遙出上陽煙。","無人说得中兴事，独倚斜暉憶仲宣。"]', '诗', 'shi', '', NULL, '洛北村居 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3108e645-afe2-4f20-b8a8-cc280496b99c', '對梨花贈皇甫秀才', '对梨花贈皇甫秀才', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["林上梨花雪壓枝，獨攀瓊豔不勝悲。","依前此地逢君處，還是去年今日時。","且戀殘陽留綺席，莫推紅袖訴金巵。","騰騰戰鼓正多事，須信明朝難重持。"]', '["林上梨花雪壓枝，独攀瓊豔不勝悲。","依前此地逢君处，還是去年今日时。","且戀殘陽留綺席，莫推紅袖訴金巵。","腾腾戰鼓正多事，須信明朝难重持。"]', '诗', 'shi', '', NULL, '對梨花贈皇甫秀才 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83f75585-6e87-48f3-abea-6c8f4f313da6', '立春', '立春', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["青帝東來日馭遲，煖煙輕逐曉風吹。","罽袍公子樽前覺，錦帳佳人夢裏知。","雪圃乍開紅菜甲，綵幡新翦綠[楊]絲。","殷勤爲作宜春曲，題向花牋帖繡楣。"]', '["青帝东来日馭遲，煖煙轻逐晓风吹。","罽袍公子樽前覺，錦帳佳人梦裏知。","雪圃乍开紅菜甲，綵幡新翦綠[楊]絲。","殷勤爲作宜春曲，題向花牋帖繡楣。"]', '诗', 'shi', '', NULL, '立春 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c3d57ea-fd1b-477b-ad38-4dc5ccdee98c', '村笛', '村笛', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["簫韶九奏韻淒鏘，曲度雖高調不傷。","却見孤村明月夜，一聲牛笛斷人腸。"]', '["簫韶九奏韻淒鏘，曲度雖高調不傷。","却见孤村明月夜，一声牛笛斷人腸。"]', '诗', 'shi', '', NULL, '村笛 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf739c7c-1914-4edf-8884-a1fb81489574', '題李斯傳', '題李斯傳', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["蜀魄湘魂萬古悲，未悲秦相死秦時。","臨刑莫恨倉中鼠，上蔡東門去自遲。"]', '["蜀魄湘魂万古悲，未悲秦相死秦时。","臨刑莫恨倉中鼠，上蔡东门去自遲。"]', '诗', 'shi', '', NULL, '題李斯傳 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb4cccdd-19eb-4bc6-9af1-17c9c17c1054', '贈薛秀才', '贈薛秀才', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["相辭因避世，相見尚兵戈。","亂後故人少，別來新話多。","但聞哀痛詔，未覩凱旋歌。","欲結巖棲伴，何山好薜蘿。"]', '["相辞因避世，相见尚兵戈。","亂後故人少，別来新話多。","但闻哀痛詔，未覩凱旋歌。","欲結巖棲伴，何山好薜蘿。"]', '诗', 'shi', '', NULL, '贈薛秀才 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85bc0ae4-09e9-45a1-b774-8eac0761761a', '和元秀才別業書事', '和元秀才別業书事', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["僻居春事好，水曲亂花陰。","浪過河移岸，雛成鳥別林。","綠錢榆貫重，紅障杏籬深。","莫飲宜城酒，愁多醉易沈。"]', '["僻居春事好，水曲亂花陰。","浪過河移岸，雛成鸟別林。","綠錢榆貫重，紅障杏籬深。","莫饮宜城酒，愁多醉易沈。"]', '诗', 'shi', '', NULL, '和元秀才別業書事 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b63da6b7-c344-4eb8-8a7e-2d84182bbbc0', '紀村事', '紀村事', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["綠蔓映雙扉，循牆一徑微。","雨多庭果爛，稻熟渚禽肥。","釀酒迎新社，遙砧送暮暉。"]', '["綠蔓映雙扉，循牆一徑微。","雨多庭果爛，稻熟渚禽肥。","釀酒迎新社，遙砧送暮暉。"]', '诗', 'shi', '', NULL, '紀村事 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29c71fda-7e84-40ef-bacc-f6a56d3611b9', '題許僊師院', '題許僊師院', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["地古多喬木，遊人到且吟。","院開金鏁澀，門映綠篁深。","山色不離眼，鶴聲長在琴。","往來誰與熟，乳鹿住前林。"]', '["地古多喬木，游人到且吟。","院开金鏁澀，门映綠篁深。","山色不離眼，鹤声长在琴。","往来誰與熟，乳鹿住前林。"]', '诗', 'shi', '', NULL, '題許僊師院 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68713f88-a17f-44b6-851f-6509891c9d07', '離筵訴酒', '離筵訴酒', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["感君情重惜分離，送我殷勤酒滿巵。","不是不能判酩酊，却憂前路酒醒時。"]', '["感君情重惜分離，送我殷勤酒满巵。","不是不能判酩酊，却憂前路酒醒时。"]', '诗', 'shi', '', NULL, '離筵訴酒 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fc9d183-2cba-4dc9-9f02-432eac20fb45', '不寐', '不寐', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["不寐天將曉，心勞轉似灰。","蚊吟頻到耳，鼠鬬競緣臺。","戶闇知蟾落，林喧覺雨來。","馬嘶朝客過，知是禁門開。"]', '["不寐天將晓，心勞轉似灰。","蚊吟頻到耳，鼠鬬競緣台。","戶闇知蟾落，林喧覺雨来。","马嘶朝客過，知是禁门开。"]', '诗', 'shi', '', NULL, '不寐 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('488af836-e0b1-4870-9395-8b8e9807c835', '贈武處士', '贈武处士', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["一身唯一室，高靜若僧家。","掃地留疎影，穿池浸落霞。","綠蘿臨水合，白道向村斜。","賣藥歸來醉，吟詩倚釣查。"]', '["一身唯一室，高静若僧家。","掃地留疎影，穿池浸落霞。","綠蘿臨水合，白道向村斜。","賣藥归来醉，吟诗倚釣查。"]', '诗', 'shi', '', NULL, '贈武處士 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('124efbed-003b-49c7-bd49-f261c2783f81', '題吉澗盧拾遺莊', '題吉澗盧拾遺莊', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["主人西遊去不歸，滿溪春雨長春薇。","怪來馬上詩情好，印破青山白鷺飛。"]', '["主人西游去不归，满溪春雨长春薇。","怪来马上诗情好，印破青山白鷺飞。"]', '诗', 'shi', '', NULL, '題吉澗盧拾遺莊 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a15d8a30-1ee0-4feb-a36a-e6a09ea1039c', '題潁源廟', '題潁源廟', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["曾是巢由棲隱地，百川唯說潁源清。","微波乍向雲根吐，去浪遙衝雪嶂橫。","萬木倚簷疎幹直，羣峰當戶曉嵐晴。","臨川試問堯年事，猶被封人勸濯纓。"]', '["曾是巢由棲隐地，百川唯说潁源清。","微波乍向云根吐，去浪遙衝雪嶂橫。","万木倚簷疎幹直，羣峰當戶晓嵐晴。","臨川試问堯年事，猶被封人勸濯纓。"]', '诗', 'shi', '', NULL, '題潁源廟 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c16e0e4-700b-41c7-b153-706c566af80f', '東遊遠歸', '东游远归', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["扣角干名計已疎，劒歌休恨食無魚。","辭家柳絮三春半，臨路槐花七月初。","江上欲尋漁父醉，日邊時得故人書。","青雲不識楊生面，天子何由問子虛。"]', '["扣角干名計已疎，劒歌休恨食無鱼。","辞家柳絮三春半，臨路槐花七月初。","江上欲尋漁父醉，日邊时得故人书。","青云不識楊生面，天子何由问子虛。"]', '诗', 'shi', '', NULL, '東遊遠歸 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d507ed1-cbb0-44d3-86fa-948205151dc0', '新正日商南道中作寄李明府', '新正日商南道中作寄李明府', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["相看又見歲華新，依舊楊朱拭淚巾。","踏雪偶因尋戴客，論文還比聚星人。","嵩山不改千年色，洛邑長生一路塵。","今日與君同避世，却憐無事是家貧。"]', '["相看又见歲华新，依旧楊朱拭泪巾。","踏雪偶因尋戴客，論文還比聚星人。","嵩山不改千年色，洛邑长生一路塵。","今日與君同避世，却怜無事是家貧。"]', '诗', 'shi', '', NULL, '新正日商南道中作寄李明府 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbeb3486-d194-411a-a183-2aa49cae2cbd', '春暮', '春暮', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["一春春事好，病酒起常遲。","流水綠縈砌，落花紅墮枝。","樓高喧乳燕，樹密鬬雛鸝。","不學山公醉，將何自解頤。"]', '["一春春事好，病酒起常遲。","流水綠縈砌，落花紅墮枝。","楼高喧乳燕，樹密鬬雛鸝。","不学山公醉，將何自解頤。"]', '诗', 'shi', '', NULL, '春暮 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ce677d6-4097-45c0-84d0-cdd4e32f323f', '哭麻處士', '哭麻处士', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["却到歌吟地，閑門草色中。","百年流水盡，萬事落花空。","繐帳扃秋月，詩樓鏁夜蟲。","少微何處墮，留恨白楊風。"]', '["却到歌吟地，闲门草色中。","百年流水尽，万事落花空。","繐帳扃秋月，诗楼鏁夜蟲。","少微何处墮，留恨白楊风。"]', '诗', 'shi', '', NULL, '哭麻處士 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50656f17-11ea-4510-93cf-2f71d066b5da', '春早', '春早', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["聞鶯纔覺曉，閉戶已知晴。","一帶窗間月，斜穿枕上生。"]', '["闻鶯纔覺晓，閉戶已知晴。","一带窗间月，斜穿枕上生。"]', '诗', 'shi', '', NULL, '春早 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51e98317-94df-4341-b8d6-e8b6d7fd5830', '和友人', '和友人', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["閉門同隱士，不出動經時。","靜閱王維畫，閑翻褚胤棋。","落泉當戶急，殘月下窗遲。","却想從來意，譙周亦自嗤。"]', '["閉门同隐士，不出动經时。","静閱王維畫，闲翻褚胤棋。","落泉當戶急，殘月下窗遲。","却想從来意，譙周亦自嗤。"]', '诗', 'shi', '', NULL, '和友人 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68acb362-79d9-4e09-83b4-dd485b591c0f', '春愁', '春愁', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["寓思本多傷，逢春恨更長。","露霑湘竹淚，花墮越梅妝。","睡怯交加夢，閑傾瀲灩觴。","後庭人不到，斜月上松篁。"]', '["寓思本多傷，逢春恨更长。","露霑湘竹泪，花墮越梅妝。","睡怯交加梦，闲傾瀲灩觴。","後庭人不到，斜月上松篁。"]', '诗', 'shi', '', NULL, '春愁 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45698e41-5984-476a-9915-01a2387c6e55', '晚春', '晚春', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["花開疑乍富，花落似初貧。","萬物不如酒，四時唯愛春。","峨峨秦氏髻，皎皎洛川神。","風月應相笑，年年醉病身。"]', '["花开疑乍富，花落似初貧。","万物不如酒，四时唯愛春。","峨峨秦氏髻，皎皎洛川神。","风月應相笑，年年醉病身。"]', '诗', 'shi', '', NULL, '晚春 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa07a00e-a7a7-41fe-9d91-eb4883746c43', '題許渾詩卷', '題許渾诗卷', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["江南才子許渾詩，字字清新句句奇。","十斛明珠量不盡，惠[休]虛作碧雲詞。"]', '["江南才子許渾诗，字字清新句句奇。","十斛明珠量不尽，惠[休]虛作碧云词。"]', '诗', 'shi', '', NULL, '題許渾詩卷 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df6c6cc5-3c70-48b0-a60f-821b4d2a963a', '贈禮佛名者', '贈禮佛名者', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["何用辛勤禮佛名，我從無得到真庭。","尋思六祖傳心印，可是從來讀藏經。"]', '["何用辛勤禮佛名，我從無得到真庭。","尋思六祖傳心印，可是從来读藏經。"]', '诗', 'shi', '', NULL, '贈禮佛名者 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40518eb8-efa9-46df-98cc-bade54126f8a', '殘花', '殘花', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["和煙和露雪離披，金蘂紅鬚尚滿枝。","十日笙歌一宵夢，苧蘿因雨失西施。"]', '["和煙和露雪離披，金蘂紅鬚尚满枝。","十日笙歌一宵梦，苧蘿因雨失西施。"]', '诗', 'shi', '', NULL, '殘花 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbeae8b0-813d-498b-b372-b461ccba5a82', '上元縣', '上元縣', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["南朝三十六英雄，角逐興亡盡此中。","有國有家皆是夢，爲龍爲虎亦成空。","殘花舊宅悲江令，落日青山弔謝公。","止竟霸圖何物在，石麟無主臥秋風。"]', '["南朝三十六英雄，角逐兴亡尽此中。","有国有家皆是梦，爲龙爲虎亦成空。","殘花旧宅悲江令，落日青山弔謝公。","止竟霸圖何物在，石麟無主臥秋风。"]', '诗', 'shi', '', NULL, '上元縣 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34cc969e-c5b0-41a2-b965-d551a20e4a01', '江上逢史館李學士', '江上逢史館李学士', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["前年分袂陝城西，醉凭征軒日欲低。","去浪指期魚必變，出門回首馬空嘶。","關河自此爲征壘，城闕於今陷戰鼙。","誰謂世途陵是谷，燕來還識舊巢泥。"]', '["前年分袂陝城西，醉凭征軒日欲低。","去浪指期鱼必变，出门回首马空嘶。","关河自此爲征壘，城闕於今陷戰鼙。","誰謂世途陵是谷，燕来還識旧巢泥。"]', '诗', 'shi', '', NULL, '江上逢史館李學士 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c5b328d-2ab8-4f4d-a0c2-627b6cb0c92b', '金陵圖', '金陵圖', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["誰謂傷心畫不成，畫人心逐世人情。","君看六幅南朝事，老木寒雲滿故城。"]', '["誰謂傷心畫不成，畫人心逐世人情。","君看六幅南朝事，老木寒云满故城。"]', '诗', 'shi', '', NULL, '金陵圖 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('509ddbcb-a98e-4028-abf4-77890de85337', '謁蔣帝廟', '謁蔣帝廟', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["建業城邊蔣帝祠，素髯清骨舊風姿。","江聲似激秦軍破，山勢如匡晉祚危。","殘雪嶺頭明組練，晚霞簷外簇旌旗。","金陵客路方流落，空祝回鑾奠酒巵。"]', '["建業城邊蔣帝祠，素髯清骨旧风姿。","江声似激秦軍破，山勢如匡晉祚危。","殘雪嶺头明組練，晚霞簷外簇旌旗。","金陵客路方流落，空祝回鑾奠酒巵。"]', '诗', 'shi', '', NULL, '謁蔣帝廟 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34288a72-3109-4681-a1e3-629f08270d10', '聞再幸梁洋', '闻再幸梁洋', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["纔喜中原息戰鼙，又聞天子幸巴西。","延燒魏闕非關燕，大狩陳倉不爲雞。","興慶玉龍寒自躍，昭陵石馬夜空嘶。","遙思萬里行宮夢，太白山前月欲低。"]', '["纔喜中原息戰鼙，又闻天子幸巴西。","延燒魏闕非关燕，大狩陳倉不爲雞。","兴慶玉龙寒自躍，昭陵石马夜空嘶。","遙思万里行宮梦，太白山前月欲低。"]', '诗', 'shi', '', NULL, '聞再幸梁洋 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c9858ae-ae66-45fc-8486-4f7835697252', '王道者', '王道者', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["五雲遙指海中央，金鼎曾傳肘後方。","三島路岐空有月，十洲花木不知霜。","因攜竹杖聞龍氣，爲使僊童帶橘香。","應笑我曹身是夢，白頭猶自學詩狂。"]', '["五云遙指海中央，金鼎曾傳肘後方。","三島路岐空有月，十洲花木不知霜。","因携竹杖闻龙氣，爲使僊童带橘香。","應笑我曹身是梦，白头猶自学诗狂。"]', '诗', 'shi', '', NULL, '王道者 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63205984-9e74-47a9-80a4-8cb18b081faa', '陪金陵府相中堂夜宴', '陪金陵府相中堂夜宴', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["滿耳笙歌滿眼花，滿樓珠翠勝吳娃。","因知海上神仙窟，只似人間富貴家。","繡戶夜攢紅燭市，舞衣晴曳碧天霞。","却愁宴罷青蛾散，楊子江頭月半斜。"]', '["满耳笙歌满眼花，满楼珠翠勝吳娃。","因知海上神仙窟，只似人间富貴家。","繡戶夜攢紅燭市，舞衣晴曳碧天霞。","却愁宴罷青蛾散，楊子江头月半斜。"]', '诗', 'shi', '', NULL, '陪金陵府相中堂夜宴 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f157030d-da53-478c-886e-f082276da6f0', '和侯秀才同友生泛舟溪中相招之作', '和侯秀才同友生泛舟溪中相招之作', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["嵇阮相將棹酒船，晚風侵浪水侵舷。","輕如控鯉初離岸，遠似乘槎欲上天。","雨外鳥歸吳苑樹，鏡中人入洞庭煙。","憑君不用回舟疾，今夜西江月正圓。"]', '["嵇阮相將棹酒船，晚风侵浪水侵舷。","轻如控鯉初離岸，远似乘槎欲上天。","雨外鸟归吳苑樹，镜中人入洞庭煙。","憑君不用回舟疾，今夜西江月正圓。"]', '诗', 'shi', '', NULL, '和侯秀才同友生泛舟溪中相招之作 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32d5b341-d935-4587-8d6f-f6176ee93c07', '贈野童', '贈野童', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["羨爾無知野性真，亂搔蓬髮笑看人。","閑衝暮雨騎牛去，肯問中興社稷臣。"]', '["羨爾無知野性真，亂搔蓬髮笑看人。","闲衝暮雨騎牛去，肯问中兴社稷臣。"]', '诗', 'shi', '', NULL, '贈野童 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('441d3c48-0cb8-48e9-a8af-96c7b568e5f9', '代書寄馬', '代书寄马', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["驅馳曾在五侯家，見說初生自渥洼。","鬃白似披梁苑雪，頸肥如撲杏園花。","休嫌綠綬嘶貧舍，好著紅纓入使衙。","穩上雲衢千萬里，年年長踏魏堤沙。"]', '["驱驰曾在五侯家，见说初生自渥洼。","鬃白似披梁苑雪，頸肥如撲杏园花。","休嫌綠綬嘶貧舍，好著紅纓入使衙。","穩上云衢千万里，年年长踏魏堤沙。"]', '诗', 'shi', '', NULL, '代書寄馬 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0203630-bc4e-4e25-8dcf-41d0c48abb0b', '題淮陰侯廟', '題淮陰侯廟', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["滿把椒漿奠楚祠，碧幢黃鉞舊英威。","能扶漢代成王業，忍見唐民陷戰機。","雲夢去時高鳥盡，淮陰歸日故人稀。","如何不借平齊策，空看長星落賊圍。"]', '["满把椒漿奠楚祠，碧幢黄鉞旧英威。","能扶漢代成王業，忍见唐民陷戰機。","云梦去时高鸟尽，淮陰归日故人稀。","如何不借平齊策，空看长星落賊圍。"]', '诗', 'shi', '', NULL, '題淮陰侯廟 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69e3b34d-3c25-41c7-9fb0-ced2dc16aaeb', '送崔郎中往使西川行在', '送崔郎中往使西川行在', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["拜書辭玉帳，萬里劒關長。","新馬杏花色，綠袍春草香。","一身朝玉陛，幾日過銅梁。","莫戀爐邊醉，僊宮待侍郎。"]', '["拜书辞玉帳，万里劒关长。","新马杏花色，綠袍春草香。","一身朝玉陛，幾日過銅梁。","莫戀爐邊醉，僊宮待侍郎。"]', '诗', 'shi', '', NULL, '送崔郎中往使西川行在 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e5e123f-cf58-4c07-b540-b9858810eba3', '潤州顯濟閣曉望', '潤州显濟閣晓望', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["清曉水如鏡，隔江人似鷗。","遠煙藏海島，初日照揚州。","地壯孫權氣，雲凝庾信愁。","一篷何處客，吟凭釣魚舟。"]', '["清晓水如镜，隔江人似鷗。","远煙藏海島，初日照揚州。","地壯孫權氣，云凝庾信愁。","一篷何处客，吟凭釣鱼舟。"]', '诗', 'shi', '', NULL, '潤州顯濟閣曉望 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e78bbe6f-e671-496a-a78a-b590a8103635', '觀淛西府相畋遊', '观淛西府相畋游', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["十里旌旗十萬兵，等閑遊獵出軍城。","紫袍日照金鵝鬬，紅斾風吹畫虎獰。","帶箭彩禽雲外落，避鵰寒兔月中驚。","歸來一路笙歌滿，更有僊娥載酒迎。"]', '["十里旌旗十万兵，等闲游獵出軍城。","紫袍日照金鵝鬬，紅斾风吹畫虎獰。","带箭彩禽云外落，避鵰寒兔月中驚。","归来一路笙歌满，更有僊娥載酒迎。"]', '诗', 'shi', '', NULL, '觀淛西府相畋遊 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84eefb8c-8cb7-4c6f-9966-89515e871a8e', '官莊', '官莊', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["誰氏園林一簇煙，路人遙指盡長歎。","桑田稻澤今無主，新犯香醪沒入官。"]', '["誰氏园林一簇煙，路人遙指尽长歎。","桑田稻澤今無主，新犯香醪沒入官。"]', '诗', 'shi', '', NULL, '官莊 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50e96b09-fbdc-477f-aae6-f476cc67e742', '解維', '解維', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["又解征帆落照中，暮程還過秣陵東。","二年辛苦煙波裏，贏得風姿似釣翁。"]', '["又解征帆落照中，暮程還過秣陵东。","二年辛苦煙波裏，贏得风姿似釣翁。"]', '诗', 'shi', '', NULL, '解維 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f3ab383-a699-4921-b2c1-3b72a1bd8b99', '雨霽池上作呈侯學士', '雨霽池上作呈侯学士', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["鹿巾藜杖葛衣輕，雨歇池邊晚吹清。","正是如今江上好，白鱗紅稻紫蓴羹。"]', '["鹿巾藜杖葛衣轻，雨歇池邊晚吹清。","正是如今江上好，白鱗紅稻紫蓴羹。"]', '诗', 'shi', '', NULL, '雨霽池上作呈侯學士 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e26cdf0-1ef0-42c8-85ff-ed746dd74a2a', '寓言', '寓言', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["爲儒逢世亂，吾道欲何之。","學劒已應晚，歸山今又遲。","故人三載別，明月兩鄉悲。","惆悵滄江上，星星鬢有絲。"]', '["爲儒逢世亂，吾道欲何之。","学劒已應晚，归山今又遲。","故人三載別，明月兩乡悲。","惆悵滄江上，星星鬢有絲。"]', '诗', 'shi', '', NULL, '寓言 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d36578a1-9756-4a64-89ab-da9292cd7fe6', '哭同舍崔員外', '哭同舍崔員外', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["却到同遊地，三年一電光。","池塘春草在，風燭故人亡。","祭罷泉聲急，齋餘磬韻長。","碧天應有恨，斜日弔松篁。"]', '["却到同游地，三年一電光。","池塘春草在，风燭故人亡。","祭罷泉声急，斋餘磬韻长。","碧天應有恨，斜日弔松篁。"]', '诗', 'shi', '', NULL, '哭同舍崔員外 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e238f69a-5bed-4119-9935-bb921ed0cb04', '題姑蘇凌處士莊', '題姑蘇凌处士莊', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["一簇林亭返照間，門當官道不曾關。","花深遠岸黃鶯鬧，雨急春塘白鷺閑。","載酒客尋吳苑寺，倚樓僧看洞庭山。","怪來話得僊中事，新有人從物外還。"]', '["一簇林亭返照间，门當官道不曾关。","花深远岸黄鶯鬧，雨急春塘白鷺闲。","載酒客尋吳苑寺，倚楼僧看洞庭山。","怪来話得僊中事，新有人從物外還。"]', '诗', 'shi', '', NULL, '題姑蘇凌處士莊 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b80de46-ce5f-4800-9ff7-5434b0044b30', '過當塗縣', '過當塗縣', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["客過當塗縣，停車訪舊遊。","謝公山有墅，李白酒無樓。","采石花空發，烏江水自流。","夕陽誰共感，寒鷺立汀洲。"]', '["客過當塗縣，停车訪旧游。","謝公山有墅，李白酒無楼。","采石花空發，烏江水自流。","夕陽誰共感，寒鷺立汀洲。"]', '诗', 'shi', '', NULL, '過當塗縣 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('736031d7-69fe-4119-99b0-01e916bfe262', '江亭酒醒却寄維揚餞客', '江亭酒醒却寄維揚餞客', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["別筵人散酒初醒，江步黃昏雨雪零。","滿坐綺羅皆不見，覺來紅樹背銀屏。"]', '["別筵人散酒初醒，江步黄昏雨雪零。","满坐綺羅皆不见，覺来紅樹背銀屏。"]', '诗', 'shi', '', NULL, '江亭酒醒却寄維揚餞客 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9154fc22-5e19-45b7-a506-435298bb26fc', '臺城', '台城', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["江雨霏霏江草齊，六朝如夢鳥空啼。","無情最是臺城柳，依舊煙籠十里堤。"]', '["江雨霏霏江草齊，六朝如梦鸟空啼。","無情最是台城柳，依旧煙籠十里堤。"]', '诗', 'shi', '', NULL, '臺城 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9401dc5-56b9-4866-be35-679626c5f64a', '贈漁翁', '贈漁翁', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["草衣荷笠鬢如霜，自說家編楚水陽。","滿岸秋風吹枳橘，遶陂煙雨種菰蔣。","蘆刀夜鱠紅鱗膩，水甑朝蒸紫芋香。","曾向五湖期范蠡，爾來空闊久相忘。"]', '["草衣荷笠鬢如霜，自说家編楚水陽。","满岸秋风吹枳橘，遶陂煙雨種菰蔣。","蘆刀夜鱠紅鱗膩，水甑朝蒸紫芋香。","曾向五湖期范蠡，爾来空闊久相忘。"]', '诗', 'shi', '', NULL, '贈漁翁 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37257869-211d-4819-9f27-57a061366ae7', '過揚州', '過揚州', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["當年人未識兵戈，處處青樓夜夜歌。","花發洞中春日永，月明衣上好風多。","淮王去後無雞犬，煬帝歸來葬綺羅。","二十四橋空寂寂，綠楊摧折舊官河。"]', '["當年人未識兵戈，处处青楼夜夜歌。","花發洞中春日永，月明衣上好风多。","淮王去後無雞犬，煬帝归来葬綺羅。","二十四橋空寂寂，綠楊摧折旧官河。"]', '诗', 'shi', '', NULL, '過揚州 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2facde8-bd8f-4709-b90b-5c2f42fe614f', '寄右省李起居', '寄右省李起居', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["已向鴛行接雁行，便應雙拜紫薇郎。","纔聞闕下徵書急，已覺回朝草詔忙。","白馬似憐朱紱貴，綵衣遙惹御爐香。","多慙十載遊梁客，未換青襟侍素王。"]', '["已向鴛行接雁行，便應雙拜紫薇郎。","纔闻闕下徵书急，已覺回朝草詔忙。","白马似怜朱紱貴，綵衣遙惹御爐香。","多慙十載游梁客，未換青襟侍素王。"]', '诗', 'shi', '', NULL, '寄右省李起居 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a53a7f3b-2737-4143-9983-a116018e19d6', '鑷白', '鑷白', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["白髮太無情，朝朝鑷又生。","始因絲一縷，漸至雪千莖。","不避佳人笑，唯慙稚子驚。","新年過半百，猶歎未休兵。"]', '["白髮太無情，朝朝鑷又生。","始因絲一縷，漸至雪千莖。","不避佳人笑，唯慙稚子驚。","新年過半百，猶歎未休兵。"]', '诗', 'shi', '', NULL, '鑷白 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3db3890-d9ce-40fd-bd8f-a92800a1482b', '漳亭驛小櫻桃', '漳亭驛小櫻桃', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["當年此樹正花開，五馬僊郎載酒來。","李白已亡工部死，何人堪伴玉山頹。"]', '["當年此樹正花开，五马僊郎載酒来。","李白已亡工部死，何人堪伴玉山頹。"]', '诗', 'shi', '', NULL, '漳亭驛小櫻桃 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb8de1ea-1be9-40ee-b6d7-5274ed082893', '酬吳秀才霅川相送', '酬吳秀才霅川相送', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["一葉南浮去似飛，楚鄉雲水本無依。","離心不忍聞春鳥，病眼何堪送落暉。","摻袂客從花下散，棹舟人向鏡中歸。","夫君別我應惆悵，十五年來識素衣。"]', '["一葉南浮去似飞，楚乡云水本無依。","離心不忍闻春鸟，病眼何堪送落暉。","摻袂客從花下散，棹舟人向镜中归。","夫君別我應惆悵，十五年来識素衣。"]', '诗', 'shi', '', NULL, '酬吳秀才霅川相送 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1bc6416-c647-4a40-82be-70902023b227', '對雨獨酌', '对雨独酌', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["榴花新釀綠於苔，對雨閑傾滿滿杯。","荷鍤醉翁真達者，臥雲逋客竟悠哉。","能詩豈是經時策，愛酒原非命世才。","門外綠蘿連洞口，馬嘶應是步兵來。"]', '["榴花新釀綠於苔，对雨闲傾满满杯。","荷鍤醉翁真達者，臥云逋客竟悠哉。","能诗豈是經时策，愛酒原非命世才。","门外綠蘿連洞口，马嘶應是步兵来。"]', '诗', 'shi', '', NULL, '對雨獨酌 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2006807-1328-464b-8195-7b34ce3dfe8c', '夏初與侯補闕江南有約同泛淮汴西赴行朝莊自九驛路先至甬橋補闕由淮楚續至泗上寢病旬日遽聞捐館回首悲慟因成長句四韻弔之', '夏初與侯補闕江南有約同泛淮汴西赴行朝莊自九驛路先至甬橋補闕由淮楚續至泗上寢病旬日遽闻捐館回首悲慟因成长句四韻弔之', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["本約同來謁帝閽，忽隨川浪去東奔。","九重聖主方虛席，千里高堂尚倚門。","世德只應榮伯仲，詩名終自付兒孫。","遙憐月落清淮上，寂寞何人弔旅魂。"]', '["本約同来謁帝閽，忽隨川浪去东奔。","九重聖主方虛席，千里高堂尚倚门。","世德只應榮伯仲，诗名終自付兒孫。","遙怜月落清淮上，寂寞何人弔旅魂。"]', '诗', 'shi', '', NULL, '夏初與侯補闕江南有約同泛淮汴西赴行朝莊自九驛路先至甬橋補闕由淮楚續至泗上寢病旬日遽聞捐館回首悲慟因成長句四韻弔之 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e8b9741-b085-4046-9286-818a528371ec', '汴堤行', '汴堤行', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["欲上隋堤舉步遲，隔雲烽燧呌非時。","纔聞破虜將休馬，又道征遼再出師。","朝見西來爲過客，暮看東去作浮屍。","綠楊千里無飛鳥，日落空投舊店基。"]', '["欲上隋堤舉步遲，隔云烽燧呌非时。","纔闻破虜將休马，又道征遼再出師。","朝见西来爲過客，暮看东去作浮屍。","綠楊千里無飞鸟，日落空投旧店基。"]', '诗', 'shi', '', NULL, '汴堤行 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cd47bbd-87f3-423a-a8df-50ba844166cb', '旅次甬西見兒童以竹槍紙旗戲爲陣列主人叟曰斯子也三世沒於陣思所襲祖父讐余因感之', '旅次甬西见兒童以竹槍紙旗戲爲陣列主人叟曰斯子也三世沒於陣思所襲祖父讐余因感之', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["已聞三世沒軍營，又見兒孫學戰爭。","見爾此言堪慟哭，遣予何日望時平。"]', '["已闻三世沒軍營，又见兒孫学戰爭。","见爾此言堪慟哭，遣予何日望时平。"]', '诗', 'shi', '', NULL, '旅次甬西見兒童以竹槍紙旗戲爲陣列主人叟曰斯子也三世沒於陣思所襲祖父讐余因感之 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9172174c-11ee-4dd7-b73b-96f114c72870', '自孟津舟西上雨中作', '自孟津舟西上雨中作', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["秋煙漠漠與濛濛，不卷征帆任晚風。","百口寄安滄海上，一身逃難綠林中。","來時楚岸楊花白，去日隋堤蓼穗紅。","却到故園翻似客，歸心迢遞秣陵東。"]', '["秋煙漠漠與濛濛，不卷征帆任晚风。","百口寄安滄海上，一身逃难綠林中。","来时楚岸楊花白，去日隋堤蓼穗紅。","却到故园翻似客，归心迢遞秣陵东。"]', '诗', 'shi', '', NULL, '自孟津舟西上雨中作 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86697e59-7a96-46aa-86fa-b1e259e98c88', '含山店夢覺作', '含山店梦覺作', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["曾爲流離慣別家，等閑揮袂客天涯。","燈前一覺江南夢，惆悵起來山月斜。"]', '["曾爲流離慣別家，等闲揮袂客天涯。","灯前一覺江南梦，惆悵起来山月斜。"]', '诗', 'shi', '', NULL, '含山店夢覺作 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb8be5a9-e284-4791-ac39-c41b3f0bc06e', '題貂黃嶺官軍', '題貂黄嶺官軍', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["散騎蕭蕭下太行，遠從吳會去陳倉。","斜風細雨江亭上，盡日凭欄憶楚鄉。"]', '["散騎蕭蕭下太行，远從吳會去陳倉。","斜风細雨江亭上，尽日凭欄憶楚乡。"]', '诗', 'shi', '', NULL, '題貂黃嶺官軍 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28a57ab5-4742-43d1-af23-35493b920a27', '過內黃縣', '過內黄縣', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["相州吹角欲斜陽，匹馬搖鞭宿內黃。","僻縣不容投刺客，野陂時遇射鵰郎。","雲中粉堞新城壘，店後荒郊舊戰場。","猶指去程千萬里，秣陵煙樹在何鄉。"]', '["相州吹角欲斜陽，匹马搖鞭宿內黄。","僻縣不容投刺客，野陂时遇射鵰郎。","云中粉堞新城壘，店後荒郊旧戰場。","猶指去程千万里，秣陵煙樹在何乡。"]', '诗', 'shi', '', NULL, '過內黃縣 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dda99784-2b0e-42be-a063-68dfb28e3a93', '雜感', '杂感', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["莫悲建業荆榛滿，昔日繁華是帝京。","莫愛廣陵臺榭好，也曾蕪沒作荒城。","魚龍爵馬皆如夢，風月煙花豈有情。","行客不勞頻悵望，古來朝市歎衰榮。"]', '["莫悲建業荆榛满，昔日繁华是帝京。","莫愛廣陵台榭好，也曾蕪沒作荒城。","鱼龙爵马皆如梦，风月煙花豈有情。","行客不勞頻悵望，古来朝市歎衰榮。"]', '诗', 'shi', '', NULL, '雜感 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e5a8134-8f64-4ed8-8eb0-f2a5eedfa83c', '垣縣山中尋李書記山居不遇留題河次店', '垣縣山中尋李书記山居不遇留題河次店', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["白雲紅樹𡵻㟍東，名鳥羣飛古畫中。","僊吏不知何處隱，山南山北雨濛濛。"]', '["白云紅樹𡵻㟍东，名鸟羣飞古畫中。","僊吏不知何处隐，山南山北雨濛濛。"]', '诗', 'shi', '', NULL, '垣縣山中尋李書記山居不遇留題河次店 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b023413-2be6-45e9-9c37-8ee395d805f8', '送人遊幷汾', '送人游幷汾', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["風雨蕭蕭欲暮秋，獨攜孤劒塞垣遊。","如今虜騎方南牧，莫過陰關第一州。"]', '["风雨蕭蕭欲暮秋，独携孤劒塞垣游。","如今虜騎方南牧，莫過陰关第一州。"]', '诗', 'shi', '', NULL, '送人遊幷汾 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43851f4d-e2cd-4226-b7f3-fb7637e43805', '李氏小池亭十二韻', '李氏小池亭十二韻', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["積石亂巉巉，庭莎綠不芟。","小橋低跨水，危檻半依巖。","花落魚爭唼，櫻紅鳥競鵮。","引泉疏地脈，掃絮積山嵌。","古柳紅綃織，新篁紫綺緘。","養猿秋嘯月，放鶴夜棲杉。","枕簟谿雲膩，池塘海雨鹹。","語窗雞逞辨，舐鼎犬偏饞。","踏蘚青粘屐，攀蘿綠映衫。","訪僧舟北渡，貰酒日西銜。","遲客登高閣，題詩遶翠嵒。","家藏何所寶，清韻滿琅函。"]', '["積石亂巉巉，庭莎綠不芟。","小橋低跨水，危檻半依巖。","花落鱼爭唼，櫻紅鸟競鵮。","引泉疏地脈，掃絮積山嵌。","古柳紅綃织，新篁紫綺緘。","養猿秋嘯月，放鹤夜棲杉。","枕簟谿云膩，池塘海雨鹹。","語窗雞逞辨，舐鼎犬偏饞。","踏蘚青粘屐，攀蘿綠映衫。","訪僧舟北渡，貰酒日西銜。","遲客登高閣，題诗遶翠嵒。","家藏何所寶，清韻满琅函。"]', '诗', 'shi', '', NULL, '李氏小池亭十二韻 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a40ecbf-4cfe-4f59-9402-3b372312722e', '遣興', '遣兴', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["如幻如泡世，多愁多病身。","亂來知酒聖，貧去覺錢神。","異國清明節，空江寂寞春。","聲聲林上鳥，喚我北歸秦。"]', '["如幻如泡世，多愁多病身。","亂来知酒聖，貧去覺錢神。","異国清明節，空江寂寞春。","声声林上鸟，喚我北归秦。"]', '诗', 'shi', '', NULL, '遣興 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cfd98a7-5abc-4ffe-9626-03fc1445b98e', '婺州和陸諫議將赴闕懷陽羨山居', '婺州和陸諫議將赴闕懷陽羨山居', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["望闕路仍遠，子牟魂欲飛。","道開燒藥鼎，僧寄臥雲衣。","故國饒芳草，他山挂夕暉。","東陽雖勝地，王粲奈思歸。"]', '["望闕路仍远，子牟魂欲飞。","道开燒藥鼎，僧寄臥云衣。","故国饒芳草，他山挂夕暉。","东陽雖勝地，王粲奈思归。"]', '诗', 'shi', '', NULL, '婺州和陸諫議將赴闕懷陽羨山居 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05e3b507-d722-46ae-a723-a60fd1776422', '江上題所居', '江上題所居', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["故人相別盡朝天，苦竹江頭獨閉關。","落日亂蟬蕭帝寺，碧雲歸鳥謝家山。","青州從事來偏熟，泉布先生老漸慳。","不是對花長酩酊，永嘉時代不如閑。"]', '["故人相別尽朝天，苦竹江头独閉关。","落日亂蟬蕭帝寺，碧云归鸟謝家山。","青州從事来偏熟，泉布先生老漸慳。","不是对花长酩酊，永嘉时代不如闲。"]', '诗', 'shi', '', NULL, '江上題所居 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfa4a789-a8cc-400c-a03b-cdea2490bb7a', '婺州屏居蒙右省王拾遺車枉降訪病中延候不得因成寄謝', '婺州屏居蒙右省王拾遺车枉降訪病中延候不得因成寄謝', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["三年流落臥漳濱，王粲思家拭淚頻。","畫角莫吹殘月夜，病心方憶故園春。","自爲江上樵蘇客，不識天邊侍從臣。","怪得白鷗驚去盡，綠蘿門外有朱輪。"]', '["三年流落臥漳濱，王粲思家拭泪頻。","畫角莫吹殘月夜，病心方憶故园春。","自爲江上樵蘇客，不識天邊侍從臣。","怪得白鷗驚去尽，綠蘿门外有朱輪。"]', '诗', 'shi', '', NULL, '婺州屏居蒙右省王拾遺車枉降訪病中延候不得因成寄謝 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd042987-5f1a-4f3e-8401-97e8d1224cd0', '將卜蘭芷村居留別郡中在仕', '將卜蘭芷村居留別郡中在仕', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["蘭芷江頭寄斷蓬，移家空載一颿風。","伯倫嗜酒還因亂，平子歸田不爲窮。","避世漂零人境外，結茅依約畫屏中。","從今隱去應難覓，深入蘆花作釣翁。"]', '["蘭芷江头寄斷蓬，移家空載一颿风。","伯倫嗜酒還因亂，平子归田不爲窮。","避世漂零人境外，結茅依約畫屏中。","從今隐去應难覓，深入蘆花作釣翁。"]', '诗', 'shi', '', NULL, '將卜蘭芷村居留別郡中在仕 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87bc2877-47be-4f3a-9c53-225244438b55', '和陸諫議避地寄東陽進退未決見寄', '和陸諫議避地寄东陽進退未決见寄', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["未歸天路紫雲深，暫駐東陽歲月侵。","入洛聲華當世重，閔周章句滿朝吟。","開爐夜看黃芽鼎，臥甕閑欹白玉簪。","讀易草玄人不會，憂君心是致君心。"]', '["未归天路紫云深，暫駐东陽歲月侵。","入洛声华當世重，閔周章句满朝吟。","开爐夜看黄芽鼎，臥甕闲欹白玉簪。","读易草玄人不會，憂君心是致君心。"]', '诗', 'shi', '', NULL, '和陸諫議避地寄東陽進退未決見寄 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b44839fc-4498-453a-80f6-77603cb86c2f', '山墅閑題', '山墅闲題', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["邐迤前岡壓後岡，一川桑柘好殘陽。","主人饋餉炊紅黍，鄰父攜竿釣紫魴。","靜極却嫌流水鬧，閑多翻笑野雲忙。","有名不那無名客，獨閉衡門避建康。"]', '["邐迤前岡壓後岡，一川桑柘好殘陽。","主人饋餉炊紅黍，鄰父携竿釣紫魴。","静極却嫌流水鬧，闲多翻笑野云忙。","有名不那無名客，独閉衡门避建康。"]', '诗', 'shi', '', NULL, '山墅閑題 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('758f43ff-6f51-43ee-b08a-1729a6347023', '江上逢故人', '江上逢故人', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["前年送我曲江西，紅杏園中醉似泥。","今日逢君越溪上，杜鵑花發鷓鴣啼。","來時舊里人誰在，別後滄波路幾迷。","江畔玉樓多美酒，仲宣懷土莫淒淒。"]', '["前年送我曲江西，紅杏园中醉似泥。","今日逢君越溪上，杜鵑花發鷓鴣啼。","来时旧里人誰在，別後滄波路幾迷。","江畔玉楼多美酒，仲宣懷土莫淒淒。"]', '诗', 'shi', '', NULL, '江上逢故人 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2abf89ce-edda-4fd6-b35e-1fcdb37814ab', '旅中感遇寄呈李秘書昆仲', '旅中感遇寄呈李秘书昆仲', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["南望愁雲鏁翠微，謝家樓閣雨霏霏。","劉楨病後新詩少，阮籍貧來好客稀。","猶喜故人天外至，許將孤劒日邊歸。","懷鄉不怕嚴陵笑，只待秋風別釣磯。"]', '["南望愁云鏁翠微，謝家楼閣雨霏霏。","劉楨病後新诗少，阮籍貧来好客稀。","猶喜故人天外至，許將孤劒日邊归。","懷乡不怕嚴陵笑，只待秋风別釣磯。"]', '诗', 'shi', '', NULL, '旅中感遇寄呈李秘書昆仲 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67af398a-45dd-4b2f-98f9-06919708d697', '送范評事入關', '送范評事入关', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["寂寥門戶寡相親，日日頻來只有君。","正喜琴尊長作伴，忽攜書劒遠辭羣。","傷心柳色離亭見，聒耳蟬聲故國聞。","爲報明年杏園客，與留絕豔待終軍。"]', '["寂寥门戶寡相親，日日頻来只有君。","正喜琴尊长作伴，忽携书劒远辞羣。","傷心柳色離亭见，聒耳蟬声故国闻。","爲報明年杏园客，與留絕豔待終軍。"]', '诗', 'shi', '', NULL, '送范評事入關 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95d6d7ab-b5f6-4383-b1f0-791437da27f8', '東陽酒家贈別二絕句 一', '东陽酒家贈別二絕句 一', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["送君同上酒家樓，酩酊翻成一笑休。","正是落花饒悵望，醉鄉前路莫回頭。"]', '["送君同上酒家楼，酩酊翻成一笑休。","正是落花饒悵望，醉乡前路莫回头。"]', '诗', 'shi', '', NULL, '東陽酒家贈別二絕句 一 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b036282-bbe4-43d9-9208-f52b29f000b3', '東陽酒家贈別二絕句 二', '东陽酒家贈別二絕句 二', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["天涯方歎異鄉身，又向天涯別故人。","明日五更孤店月，醉醒何處淚霑巾。"]', '["天涯方歎異乡身，又向天涯別故人。","明日五更孤店月，醉醒何处泪霑巾。"]', '诗', 'shi', '', NULL, '東陽酒家贈別二絕句 二 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6835208d-fa29-42aa-a166-f058dc9dec01', '江上村居', '江上村居', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["本無踪跡戀柴扃，世亂須教識道情。","顚倒夢魂愁裏得，撅奇詩句望中生。","花緣豔絕栽難好，山爲看多詠不成。","聞道漢軍新破虜，使來仍說近離京。"]', '["本無踪跡戀柴扃，世亂須教識道情。","顚倒梦魂愁裏得，撅奇诗句望中生。","花緣豔絕栽难好，山爲看多詠不成。","闻道漢軍新破虜，使来仍说近離京。"]', '诗', 'shi', '', NULL, '江上村居 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e893616-4568-4b65-b18f-949f4864935f', '江外思鄉', '江外思乡', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["年年春日異鄉悲，杜曲黃鶯可得知。","更被夕陽江岸上，斷腸煙柳一絲絲。"]', '["年年春日異乡悲，杜曲黄鶯可得知。","更被夕陽江岸上，斷腸煙柳一絲絲。"]', '诗', 'shi', '', NULL, '江外思鄉 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f58a6146-593f-4be1-aaf8-98493527d576', '和鄭拾遺秋日感事一百韻', '和鄭拾遺秋日感事一百韻', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["禍亂天心厭，流離客思傷。","有家拋上國，無罪謫遐方。","負笈將辭越，揚帆欲泛湘。","避時難駐足，感事易回腸。","雅道何銷德，妖星忽耀芒。","中原初縱燎，下國竟探湯。","盜據三秦地，兵纏八水鄉。","戰塵輕犯闕，羽斾遠巡梁。","自此修文代，俄成講武場。","熊羆驅涿鹿，犀象走昆陽。","御馬迷新棧，宮娥改舊妝。","五丁功再覩，八難事難忘。","鳳引金根疾，兵環玉弩彊。","建牙雖可恃，摩壘詎能防。","霍廟神遐遠，圯橋路杳茫。","出師威似虎，禦敵狠如羊。","眉畫猶思赤，巾裁未厭黃。","晨趨鳴鐵騎，夜舞挹瓊觴。","僭侈彤襜亂，諠呼繡𩭪攘。","但聞爭曳組，詎見學垂韁。","鵲印提新篆，龍泉奪曉霜。","軍威徒逗撓，我武自維揚。","負扆勞天眷，凝旒念國章。","繡旗張畫獸，寶馬躍紅鴦。","但欲除妖氣，寧思蔽耿光。","曉煙生帝里，夜火入春坊。","鳥怪巢宮樹，狐驕上苑牆。","設危終在德，視履豈無祥。","氣激雷霆怒，神驅岳瀆忙。","功高分虎節，位下耻龍驤。","遍命登壇將，巡封異姓王。","志求扶墜典，力未振頹綱。","漢路閑鵰鶚，雲衢駐驌驦。","寶裝軍器麗，麝裛戰袍香。","日覩兵書捷，時聞虜騎亡。","人心驚獬豸，雀意伺螳螂。","上略咸推妙，前鋒詎可當。","紆金光照耀，執玉意藏昂。","覆餗非無謂，奢華事每詳。","四民皆組綬，九土墮耕桑。","飛騎黃金勒，香車翠鈿裝。","八珍羅膳府，五采鬬筐牀。","宴集喧華第，歌鐘簇畫梁。","永期傳子姓，寧誤犯天狼。","未覩君除側，徒思玉在傍。","竄身奚可保，易地喜相將。","國運方夷險，天心詎測量。","九流雖暫蔽，三柄豈相妨。","小孽乖躔次，中興繫昊蒼。","法堯功已普，罪己德非涼。","帝念惟思理，臣心豈自遑。","詔催青瑣客，時待紫微郎。","定難輸宸算，勝災減御粱。","皇恩思蕩蕩，睿澤轉洋洋。","偃臥雖非晚，艱難亦備嘗。","舜庭招諫鼓，漢殿上書囊。","儉德遵三尺，清朝俟一匡。","世隨漁父醉，身效接輿狂。","竄逐同天寶，遭罹異建康。","道孤悲海澨，家遠隔天潢。","卒歲貧無褐，經秋病泛漳。","似魚甘去乙，比蟹未成筐。","守道慙無補，趨時愧不臧。","殷牛常在耳，晉豎欲潛肓。","忸恨山思板，懷歸海欲航。","角吹魂悄悄，笛引淚浪浪。","亂覺乾坤窄，貧知日月長。","勢將隨鶴列，忽喜遇鴛行。","已報新回駕，仍聞近納隍。","文風銷劒楯，禮物換旂裳。","紫闥重開序，青衿再設庠。","黑頭期命爵，頳尾尚憂魴。","吳坂嘶騏驥，岐山集鳳皇。","詞源波浩浩，諫署玉鏘鏘。","飼雀曾傳慶，烹蛇詎有殃。","[弢]弓揮勁鏃，匣劒淬神鋩。","諤諤寧慙直，堂堂不謝張。","曉風趨建禮，夜月直文昌。","去國時雖久，安邦志不常。","良金鑪自躍，美玉櫝難藏。","北望心如斾，西歸律變商。","跡隨江燕去，心逐塞鴻翔。","晚翠籠桑塢，斜暉挂竹堂。","路愁千里月，田愛萬斯箱。","伴釣歌前浦，隨樵上遠岡。","鷺眠依晚嶼，鳥浴上枯楊。","驚夢緣欹枕，多吟爲倚廊。","訪僧紅葉寺，題句白雲房。","颿外青楓老，尊前紫菊芳。","夜燈銀耿耿，曉露玉瀼瀼。","異國慙傾蓋，歸塗俟併糧。","身雖留震澤，心已過雷塘。","執友知誰在，家山各已荒。","海邊登桂檝，煙外泛雲檣。","巢樹禽思越，嘶風馬戀羌。","寒聲愁聽杵，空館厭聞螿。","望闕飛華蓋，趨朝振玉璫。","米慙無薏苡，麵喜有桄榔。","話別心重結，傷時淚一滂。","佇歸蓬島後，綸詔潤青緗。"]', '["禍亂天心厭，流離客思傷。","有家拋上国，無罪謫遐方。","負笈將辞越，揚帆欲泛湘。","避时难駐足，感事易回腸。","雅道何銷德，妖星忽耀芒。","中原初縱燎，下国竟探湯。","盜據三秦地，兵纏八水乡。","戰塵轻犯闕，羽斾远巡梁。","自此修文代，俄成講武場。","熊羆驱涿鹿，犀象走昆陽。","御马迷新棧，宮娥改旧妝。","五丁功再覩，八难事难忘。","鳳引金根疾，兵环玉弩彊。","建牙雖可恃，摩壘詎能防。","霍廟神遐远，圯橋路杳茫。","出師威似虎，禦敵狠如羊。","眉畫猶思赤，巾裁未厭黄。","晨趨鳴鐵騎，夜舞挹瓊觴。","僭侈彤襜亂，諠呼繡𩭪攘。","但闻爭曳組，詎见学垂韁。","鵲印提新篆，龙泉奪晓霜。","軍威徒逗撓，我武自維揚。","負扆勞天眷，凝旒念国章。","繡旗張畫獸，寶马躍紅鴦。","但欲除妖氣，寧思蔽耿光。","晓煙生帝里，夜火入春坊。","鸟怪巢宮樹，狐驕上苑牆。","設危終在德，視履豈無祥。","氣激雷霆怒，神驱岳瀆忙。","功高分虎節，位下耻龙驤。","遍命登壇將，巡封異姓王。","志求扶墜典，力未振頹綱。","漢路闲鵰鶚，云衢駐驌驦。","寶裝軍器丽，麝裛戰袍香。","日覩兵书捷，时闻虜騎亡。","人心驚獬豸，雀意伺螳螂。","上略咸推妙，前鋒詎可當。","紆金光照耀，執玉意藏昂。","覆餗非無謂，奢华事每詳。","四民皆組綬，九土墮耕桑。","飞騎黄金勒，香车翠鈿裝。","八珍羅膳府，五采鬬筐牀。","宴集喧华第，歌鐘簇畫梁。","永期傳子姓，寧誤犯天狼。","未覩君除側，徒思玉在傍。","竄身奚可保，易地喜相將。","国運方夷險，天心詎測量。","九流雖暫蔽，三柄豈相妨。","小孽乖躔次，中兴繫昊蒼。","法堯功已普，罪己德非涼。","帝念惟思理，臣心豈自遑。","詔催青瑣客，时待紫微郎。","定难輸宸算，勝災減御粱。","皇恩思蕩蕩，睿澤轉洋洋。","偃臥雖非晚，艱难亦備嘗。","舜庭招諫鼓，漢殿上书囊。","儉德遵三尺，清朝俟一匡。","世隨漁父醉，身效接輿狂。","竄逐同天寶，遭罹異建康。","道孤悲海澨，家远隔天潢。","卒歲貧無褐，經秋病泛漳。","似鱼甘去乙，比蟹未成筐。","守道慙無補，趨时愧不臧。","殷牛常在耳，晉豎欲潛肓。","忸恨山思板，懷归海欲航。","角吹魂悄悄，笛引泪浪浪。","亂覺乾坤窄，貧知日月长。","勢將隨鹤列，忽喜遇鴛行。","已報新回駕，仍闻近納隍。","文风銷劒楯，禮物換旂裳。","紫闥重开序，青衿再設庠。","黑头期命爵，頳尾尚憂魴。","吳坂嘶騏驥，岐山集鳳皇。","词源波浩浩，諫署玉鏘鏘。","飼雀曾傳慶，烹蛇詎有殃。","[弢]弓揮勁鏃，匣劒淬神鋩。","諤諤寧慙直，堂堂不謝張。","晓风趨建禮，夜月直文昌。","去国时雖久，安邦志不常。","良金鑪自躍，美玉櫝难藏。","北望心如斾，西归律变商。","跡隨江燕去，心逐塞鴻翔。","晚翠籠桑塢，斜暉挂竹堂。","路愁千里月，田愛万斯箱。","伴釣歌前浦，隨樵上远岡。","鷺眠依晚嶼，鸟浴上枯楊。","驚梦緣欹枕，多吟爲倚廊。","訪僧紅葉寺，題句白云房。","颿外青楓老，尊前紫菊芳。","夜灯銀耿耿，晓露玉瀼瀼。","異国慙傾蓋，归塗俟併糧。","身雖留震澤，心已過雷塘。","執友知誰在，家山各已荒。","海邊登桂檝，煙外泛云檣。","巢樹禽思越，嘶风马戀羌。","寒声愁听杵，空館厭闻螿。","望闕飞华蓋，趨朝振玉璫。","米慙無薏苡，麵喜有桄榔。","話別心重結，傷时泪一滂。","佇归蓬島後，綸詔潤青緗。"]', '诗', 'shi', '', NULL, '和鄭拾遺秋日感事一百韻 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0998eaa1-544c-448c-9d3e-d7f4ecd17795', '夢入關', '梦入关', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["夢中乘傳過關亭，南望蓮峰簇簇青。","馬上正吟歸去好，覺來江月滿前庭。"]', '["梦中乘傳過关亭，南望蓮峰簇簇青。","马上正吟归去好，覺来江月满前庭。"]', '诗', 'shi', '', NULL, '夢入關 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76bb0a0b-55af-4272-a266-a56f8ec9832e', '送人歸上國', '送人归上国', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["送君江上日西斜，泣向江邊滿樹花。","若見青雲舊相識，爲言流落在天涯。"]', '["送君江上日西斜，泣向江邊满樹花。","若见青云旧相識，爲言流落在天涯。"]', '诗', 'shi', '', NULL, '送人歸上國 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f7b07e0-a8bc-4f69-87bf-606faf0fd049', '聞春鳥', '闻春鸟', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["雲晴春鳥滿江村，還似長安舊日聞。","紅杏花前應笑我，我今顦顇亦羞君。"]', '["云晴春鸟满江村，還似长安旧日闻。","紅杏花前應笑我，我今顦顇亦羞君。"]', '诗', 'shi', '', NULL, '聞春鳥 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7e085f0-2a77-4931-9522-1e42c4f78743', '櫻桃樹', '櫻桃樹', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["記得初生雪滿枝，和蜂和蝶帶花移。","而今花落遊蜂去，空作主人惆悵詩。"]', '["記得初生雪满枝，和蜂和蝶带花移。","而今花落游蜂去，空作主人惆悵诗。"]', '诗', 'shi', '', NULL, '櫻桃樹 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b166d63-2fbc-4b40-8d6f-e09210b8b3bb', '獨鶴', '独鹤', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["夕陽灘上立裴回，紅蓼風前雪翅開。","應爲不知棲宿處，幾回飛去又飛來。"]', '["夕陽灘上立裴回，紅蓼风前雪翅开。","應爲不知棲宿处，幾回飞去又飞来。"]', '诗', 'shi', '', NULL, '獨鶴 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6db22a7-5f21-4230-81b0-11879d7800c0', '新栽竹', '新栽竹', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["寂寞堦前見此君，遶欄吟罷却沾巾。","異鄉流落誰相識，唯有叢篁似主人。"]', '["寂寞堦前见此君，遶欄吟罷却沾巾。","異乡流落誰相識，唯有叢篁似主人。"]', '诗', 'shi', '', NULL, '新栽竹 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d1baf09-b73e-44f0-9aa1-7930ed9ab662', '稻田', '稻田', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["綠波春浪滿前陂，極目連雲䆉稏肥。","更被鷺鷀千點雪，破煙來入畫屏飛。"]', '["綠波春浪满前陂，極目連云䆉稏肥。","更被鷺鷀千点雪，破煙来入畫屏飞。"]', '诗', 'shi', '', NULL, '稻田 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37080749-b509-4d10-806e-6c44a8a92156', '稻田', '稻田', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["浪波春稻滿前坡，極目連雲𥝧稏肥。","更被鷺鷥千㸃白，披烟來入畫屏飛。"]', '["浪波春稻满前坡，極目連云𥝧稏肥。","更被鷺鷥千㸃白，披烟来入畫屏飞。"]', '诗', 'shi', '', NULL, '稻田 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b491a2b9-392b-4444-bc77-e398aa84a9d0', '庭前菊', '庭前菊', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["爲憶長安爛熳開，我今移爾滿庭栽。","紅蘭莫笑青青色，曾向龍山泛酒來。"]', '["爲憶长安爛熳开，我今移爾满庭栽。","紅蘭莫笑青青色，曾向龙山泛酒来。"]', '诗', 'shi', '', NULL, '庭前菊 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9590d9ae-a6c8-40d4-ae4a-58c0c67f7cce', '燕來', '燕来', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["去歲辭巢別近鄰，今來空訝草堂新。","花開對語應相問，不是村中舊主人。"]', '["去歲辞巢別近鄰，今来空訝草堂新。","花开对語應相问，不是村中旧主人。"]', '诗', 'shi', '', NULL, '燕來 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a4678f1-255a-43f4-bc96-92d6afd83034', '倚柴關', '倚柴关', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["杖策無言獨倚關，如癡如醉又如閑。","孤吟盡日何人會，依約前山似故山。"]', '["杖策無言独倚关，如癡如醉又如闲。","孤吟尽日何人會，依約前山似故山。"]', '诗', 'shi', '', NULL, '倚柴關 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1ff4374-9f50-403f-a9f9-8d74adb604ad', '題七步廊', '題七步廊', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["席門無計那殘陽，更接簷前七步廊。","不羨東都丞相宅，每行吟得好篇章。"]', '["席门無計那殘陽，更接簷前七步廊。","不羨东都丞相宅，每行吟得好篇章。"]', '诗', 'shi', '', NULL, '題七步廊 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('990ed4ff-5bd3-47c5-90de-1a4b07d6132b', '語松竹', '語松竹', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["庭前芳草綠於袍，堂上詩人欲二毛。","多病不禁秋寂寞，雨松風竹莫騷騷。"]', '["庭前芳草綠於袍，堂上诗人欲二毛。","多病不禁秋寂寞，雨松风竹莫騷騷。"]', '诗', 'shi', '', NULL, '語松竹 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf5704d0-bf00-47c9-9492-b7a8ab1217d8', '不出院楚公', '不出院楚公', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["一自蟬關閉，心猿日漸馴。","不知城郭路，稀識市朝人。","履帶堦前雪，衣無寺外塵。","却嫌山翠好，詩客往來頻。"]', '["一自蟬关閉，心猿日漸馴。","不知城郭路，稀識市朝人。","履带堦前雪，衣無寺外塵。","却嫌山翠好，诗客往来頻。"]', '诗', 'shi', '', NULL, '不出院楚公 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d26c4553-22c8-4621-b8ae-2147970b4f7e', '江邊吟', '江邊吟', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["江邊烽燧幾時休，江上行人雪滿頭。","誰信亂離花不見，只應惆悵水東流。","陶潛政事千杯酒，張翰生涯一葉舟。","若有片颿歸去好，可堪重倚仲宣樓。"]', '["江邊烽燧幾时休，江上行人雪满头。","誰信亂離花不见，只應惆悵水东流。","陶潛政事千杯酒，張翰生涯一葉舟。","若有片颿归去好，可堪重倚仲宣楼。"]', '诗', 'shi', '', NULL, '江邊吟 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8620f21-a69f-4121-81f2-1d7809a2d15e', '江南送李明府入關', '江南送李明府入关', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["雨花煙柳傍江邨，流落天涯酒一罇。","分首不辭多下淚，回頭唯恐更消魂。","我爲孟館三千客，君繼寧王五代孫。","正是中興磐石重，莫將顦顇入都門。"]', '["雨花煙柳傍江邨，流落天涯酒一罇。","分首不辞多下泪，回头唯恐更消魂。","我爲孟館三千客，君繼寧王五代孫。","正是中兴磐石重，莫將顦顇入都门。"]', '诗', 'shi', '', NULL, '江南送李明府入關 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3aa7334-1431-4eb5-a820-bb73dd42c3f7', '送福州王先輩南歸', '送福州王先輩南归', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["豫章城下偶相逢，自說今方遇至公。","八韻賦吟梁苑雪，六銖衣惹杏園風。","名標玉籍僊壇上，家寄閩山畫障中。","明日一杯何處別，綠楊煙岸雨濛濛。"]', '["豫章城下偶相逢，自说今方遇至公。","八韻賦吟梁苑雪，六銖衣惹杏园风。","名標玉籍僊壇上，家寄閩山畫障中。","明日一杯何处別，綠楊煙岸雨濛濛。"]', '诗', 'shi', '', NULL, '送福州王先輩南歸 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83dd52f0-e87f-4b5a-8432-a3c775baac9e', '夜雪泛舟遊南溪', '夜雪泛舟游南溪', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["大江西面小溪斜，入竹穿松似若耶。","兩岸嚴風吹玉樹，一灘明月曬銀砂。","因尋野渡逢漁舍，更泊前灣上酒家。","去去不知歸路遠，棹聲煙裏獨嘔啞。"]', '["大江西面小溪斜，入竹穿松似若耶。","兩岸嚴风吹玉樹，一灘明月曬銀砂。","因尋野渡逢漁舍，更泊前灣上酒家。","去去不知归路远，棹声煙裏独嘔啞。"]', '诗', 'shi', '', NULL, '夜雪泛舟遊南溪 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b7b7881-792e-4873-8486-510cf4532343', '江行西望', '江行西望', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["西望長安白日遙，半年無事駐蘭橈。","欲將張翰秋江雨，畫作屏風寄鮑昭。"]', '["西望长安白日遙，半年無事駐蘭橈。","欲將張翰秋江雨，畫作屏风寄鲍昭。"]', '诗', 'shi', '', NULL, '江行西望 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06cfe600-30db-4c82-a20a-16a298187714', '銅儀', '銅儀', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["銅儀一夜變葭灰，暖律還吹嶺上梅。","已喜漢官今再覩，更驚堯曆又重開。","窗中遠岫青如黛，門外長江綠似苔。","誰念閉關張仲蔚，滿庭春雨長蒿萊。"]', '["銅儀一夜变葭灰，暖律還吹嶺上梅。","已喜漢官今再覩，更驚堯曆又重开。","窗中远岫青如黛，门外长江綠似苔。","誰念閉关張仲蔚，满庭春雨长蒿萊。"]', '诗', 'shi', '', NULL, '銅儀 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae620e35-8907-46cf-aeea-cd8dd79b7042', '含香', '含香', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["含香高步已難陪，鶴到清霄勢未回。","遇物旋添芳草句，逢春寧滯碧雲才。","微紅幾處花心吐，嫩綠誰家柳眼開。","却去金鑾爲近侍，便辭鷗鳥不歸來。"]', '["含香高步已难陪，鹤到清霄勢未回。","遇物旋添芳草句，逢春寧滯碧云才。","微紅幾处花心吐，嫩綠誰家柳眼开。","却去金鑾爲近侍，便辞鷗鸟不归来。"]', '诗', 'shi', '', NULL, '含香 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afd85777-84a9-4fb2-a14f-f3c46e3c55fd', '春雲', '春云', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["春雲春水兩溶溶，倚郭樓臺晚翠濃。","山好只因人化石，地靈曾有劒爲龍。","官辭鳳闕頻經歲，家住峨嵋第幾峰。","王粲不知多少恨，夕陽吟斷一聲鐘。"]', '["春云春水兩溶溶，倚郭楼台晚翠濃。","山好只因人化石，地靈曾有劒爲龙。","官辞鳳闕頻經歲，家住峨嵋第幾峰。","王粲不知多少恨，夕陽吟斷一声鐘。"]', '诗', 'shi', '', NULL, '春雲 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4fd8930-b645-4cdc-a563-5eb869ca221e', '雲散', '云散', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["雲散天邊落照和，關關春樹鳥聲多。","劉伶避世唯沈醉，甯戚傷時亦浩歌。","已恨歲華添皎鏡，更悲人事逐頹波。","青雲自有鵷鴻待，莫說他山好薜蘿。"]', '["云散天邊落照和，关关春樹鸟声多。","劉伶避世唯沈醉，甯戚傷时亦浩歌。","已恨歲华添皎镜，更悲人事逐頹波。","青云自有鵷鴻待，莫说他山好薜蘿。"]', '诗', 'shi', '', NULL, '雲散 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc2d6b98-8553-44f4-a398-78af5dd9fab9', '袁州作', '袁州作', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["家家生計只琴書，一郡清風似魯儒。","山色東南連紫府，水聲西北屬洪都。","煙霞盡入新詩卷，郭邑閑開古畫圖。","正是江村春酒熟，更聞春鳥勸提壺。"]', '["家家生計只琴书，一郡清风似魯儒。","山色东南連紫府，水声西北屬洪都。","煙霞尽入新诗卷，郭邑闲开古畫圖。","正是江村春酒熟，更闻春鸟勸提壺。"]', '诗', 'shi', '', NULL, '袁州作 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1dabfd08-ff4b-4a8f-a56c-ade43678d853', '題袁州謝秀才所居', '題袁州謝秀才所居', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["主人年少已能詩，更有松軒挂夕暉。","芳草似袍連徑合，白雲如鳥傍簷飛。","但將竹葉消春恨，莫遣楊花上客衣。","若有前山好煙雨，與君吟到暝鐘歸。"]', '["主人年少已能诗，更有松軒挂夕暉。","芳草似袍連徑合，白云如鸟傍簷飞。","但將竹葉消春恨，莫遣楊花上客衣。","若有前山好煙雨，與君吟到暝鐘归。"]', '诗', 'shi', '', NULL, '題袁州謝秀才所居 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a939686e-42be-4670-95f4-2d498a171e4e', '謁巫山廟', '謁巫山廟', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["亂猿啼處訪高唐，路入煙霞草木香。","山色未能忘宋玉，水聲猶似哭襄王。","朝朝暮暮陽臺下，爲雨爲雲楚國亡。","惆悵廟前無限柳，春來空鬬畫眉長。"]', '["亂猿啼处訪高唐，路入煙霞草木香。","山色未能忘宋玉，水声猶似哭襄王。","朝朝暮暮陽台下，爲雨爲云楚国亡。","惆悵廟前無限柳，春来空鬬畫眉长。"]', '诗', 'shi', '', NULL, '謁巫山廟 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('921c572e-10bd-45e0-8e17-7813a1d951ef', '鷓鴣', '鷓鴣', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["南禽無侶似相依，錦翅雙雙傍馬飛。","孤竹廟前啼暮雨，汨羅祠畔弔殘暉。","秦人只解歌爲曲，越女空能畫作衣。","懊惱澤家非有恨，年年長憶鳳城歸。"]', '["南禽無侶似相依，錦翅雙雙傍马飞。","孤竹廟前啼暮雨，汨羅祠畔弔殘暉。","秦人只解歌爲曲，越女空能畫作衣。","懊惱澤家非有恨，年年长憶鳳城归。"]', '诗', 'shi', '', NULL, '鷓鴣 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cde536cb-cf79-4543-997c-768acd86d327', '宿蓬船', '宿蓬船', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["夜來江雨宿蓬船，臥聽淋鈴不忍眠。","却憶紫微情調逸，阻風中酒過年年。"]', '["夜来江雨宿蓬船，臥听淋鈴不忍眠。","却憶紫微情調逸，阻风中酒過年年。"]', '诗', 'shi', '', NULL, '宿蓬船 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccea0a0b-28d2-4a3e-8ce5-d8e4ae6f0cf2', '送李秀才歸荆溪', '送李秀才归荆溪', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["八月中秋月正圓，送君吟上木蘭船。","人言格調勝玄度，我愛篇章敵浪僊。","晚渡去時衝細雨，夜灘何處宿寒烟。","楚王宮去陽臺近，莫倚風流滯少年。"]', '["八月中秋月正圓，送君吟上木蘭船。","人言格調勝玄度，我愛篇章敵浪僊。","晚渡去时衝細雨，夜灘何处宿寒烟。","楚王宮去陽台近，莫倚风流滯少年。"]', '诗', 'shi', '', NULL, '送李秀才歸荆溪 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('484132fe-901a-4d9b-959b-36ef00b1dbb1', '洪州送西明寺省上人遊福建', '洪州送西明寺省上人游福建', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["記得初騎竹馬年，送師來往御溝邊。","荆榛已失當時路，槐柳全無舊日煙。","遠自嵇山遊楚澤，又從廬岳去閩川。","新春闕下應相見，紅杏花中覓酒僊。"]', '["記得初騎竹马年，送師来往御溝邊。","荆榛已失當时路，槐柳全無旧日煙。","远自嵇山游楚澤，又從廬岳去閩川。","新春闕下應相见，紅杏花中覓酒僊。"]', '诗', 'shi', '', NULL, '洪州送西明寺省上人遊福建 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b41b9303-9afe-4bb9-8366-35aee44831ce', '建昌渡暝吟', '建昌渡暝吟', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["月照臨官渡，鄉情獨浩然。","鳥棲彭蠡樹，月上建昌船。","市散漁翁醉，樓深賈客眠。","隔江何處笛，吹斷綠楊煙。"]', '["月照臨官渡，乡情独浩然。","鸟棲彭蠡樹，月上建昌船。","市散漁翁醉，楼深賈客眠。","隔江何处笛，吹斷綠楊煙。"]', '诗', 'shi', '', NULL, '建昌渡暝吟 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d917a353-bf00-4ca1-bee4-f92974ac02c4', '歲除對王秀才作', '歲除对王秀才作', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["我惜今宵促，君愁玉漏頻。","豈知新歲酒，猶作異鄉身。","雪向寅前凍，花從子後春。","到明追此會，俱是隔年人。"]', '["我惜今宵促，君愁玉漏頻。","豈知新歲酒，猶作異乡身。","雪向寅前凍，花從子後春。","到明追此會，俱是隔年人。"]', '诗', 'shi', '', NULL, '歲除對王秀才作 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('397e7de1-fc07-419c-9941-9cedfc1d2d8f', '酒渴愛江清', '酒渴愛江清', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["酒渴何方療，江波一掬清。","瀉甌如練色，漱齒作泉聲。","味帶他山雪，光含白露精。","只應千古後，長稱伯倫情。"]', '["酒渴何方療，江波一掬清。","瀉甌如練色，漱齒作泉声。","味带他山雪，光含白露精。","只應千古後，长稱伯倫情。"]', '诗', 'shi', '', NULL, '酒渴愛江清 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74065f92-6ff4-49db-b03d-c139668fc171', '和李秀才郊墅早春吟興十韻', '和李秀才郊墅早春吟兴十韻', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["暖律變寒光，東君景漸長。","我悲遊海嶠，君說住柴桑。","雪色隨高嶽，冰聲陷古塘。","草根微吐翠，梅朵半含霜。","酒市多逋客，漁家足夜航。","匡廬雲傍屋，彭蠡浪衝牀。","綠擺楊枝嫩，紅挑菜甲香。","鳳皇城已盡，鸚鵡賦應狂。","佇見龍辭沼，寧憂雁失行。","不應雙劒氣，長在斗牛傍。"]', '["暖律变寒光，东君景漸长。","我悲游海嶠，君说住柴桑。","雪色隨高嶽，冰声陷古塘。","草根微吐翠，梅朵半含霜。","酒市多逋客，漁家足夜航。","匡廬云傍屋，彭蠡浪衝牀。","綠擺楊枝嫩，紅挑菜甲香。","鳳皇城已尽，鸚鵡賦應狂。","佇见龙辞沼，寧憂雁失行。","不應雙劒氣，长在斗牛傍。"]', '诗', 'shi', '', NULL, '和李秀才郊墅早春吟興十韻 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8627206a-8e17-462d-8bc4-06e716ddb304', '泛鄱陽湖', '泛鄱陽湖', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["四顧無邊鳥不飛，大波驚隔楚山微。","紛紛雨外靈均過，瑟瑟雲中帝子歸。","迸鯉似梭投遠浪，小舟如葉傍斜暉。","鴟夷去後何人到，愛者雖多見者稀。"]', '["四顧無邊鸟不飞，大波驚隔楚山微。","紛紛雨外靈均過，瑟瑟云中帝子归。","迸鯉似梭投远浪，小舟如葉傍斜暉。","鴟夷去後何人到，愛者雖多见者稀。"]', '诗', 'shi', '', NULL, '泛鄱陽湖 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9738a1c6-a764-4e9e-8161-43f6f265dea4', '黃藤山下聞猿', '黄藤山下闻猿', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["黃藤山下駐歸程，一夜號猿弔旅情。","入耳便能生百恨，斷腸何必待三聲。","穿雲宿處人難見，望月啼時兔正明。","好笑五陵年少客，壯心無事也沾纓。"]', '["黄藤山下駐归程，一夜號猿弔旅情。","入耳便能生百恨，斷腸何必待三声。","穿云宿处人难见，望月啼时兔正明。","好笑五陵年少客，壯心無事也沾纓。"]', '诗', 'shi', '', NULL, '黃藤山下聞猿 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87776b10-6055-479e-8f55-79aaf37282af', '章江作', '章江作', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["杜陵歸客正裴回，玉笛誰家呌落梅。","之子棹從天外去，故人書自日邊來。","楊花慢惹霏霏雨，竹葉閑傾滿滿杯。","欲問維揚舊風月，一江紅樹亂猿哀。"]', '["杜陵归客正裴回，玉笛誰家呌落梅。","之子棹從天外去，故人书自日邊来。","楊花慢惹霏霏雨，竹葉闲傾满满杯。","欲问維揚旧风月，一江紅樹亂猿哀。"]', '诗', 'shi', '', NULL, '章江作 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e9bd994-9f57-4add-a7dc-0066cce3e269', '南遊富陽江中作', '南游富陽江中作', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["南去又南去，此行非自期。","一帆雲作伴，千里月相隨。","浪跡花應笑，衰容鏡每知。","鄉園不可問，禾黍正離離。"]', '["南去又南去，此行非自期。","一帆云作伴，千里月相隨。","浪跡花應笑，衰容镜每知。","乡园不可问，禾黍正離離。"]', '诗', 'shi', '', NULL, '南遊富陽江中作 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('127ef46b-ca56-49cb-ba92-11f1417659b3', '饒州餘干縣琵琶洲有故韓賓客宣城裴尚書脩行李侍郎舊居遺址猶存客有過之感舊因以和吟', '饒州餘干縣琵琶洲有故韓賓客宣城裴尚书脩行李侍郎旧居遺址猶存客有過之感旧因以和吟', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["琵琶洲近斗牛星，鸞鳳曾於此放情。","已覺地靈因昴降，更聞川媚有珠生。","一灘紅樹留佳氣，萬古清弦續政聲。","戟戶盡移天上去，里人空說舊簪纓。"]', '["琵琶洲近斗牛星，鸾鳳曾於此放情。","已覺地靈因昴降，更闻川媚有珠生。","一灘紅樹留佳氣，万古清弦續政声。","戟戶尽移天上去，里人空说旧簪纓。"]', '诗', 'shi', '', NULL, '饒州餘干縣琵琶洲有故韓賓客宣城裴尚書脩行李侍郎舊居遺址猶存客有過之感舊因以和吟 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e65753e0-40ab-44a8-9f0d-bae8017c60ac', '九江逢盧員外', '九江逢盧員外', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["前年風月宿琴堂，大媚僊山近帝鄉。","別後幾沾新雨露，亂來猶記舊篇章。","陶潛豈是銅符吏，田鳳終爲錦帳郎。","莫怪相逢倍惆悵，九江煙月似瀟湘。"]', '["前年风月宿琴堂，大媚僊山近帝乡。","別後幾沾新雨露，亂来猶記旧篇章。","陶潛豈是銅符吏，田鳳終爲錦帳郎。","莫怪相逢倍惆悵，九江煙月似瀟湘。"]', '诗', 'shi', '', NULL, '九江逢盧員外 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e548022e-08e1-4baf-b6b2-458c030db8c7', '南昌晚眺', '南昌晚眺', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["南昌城郭枕江煙，章水悠悠浪拍天。","芳草綠遮僊尉宅，落霞紅襯賈人船。","霏霏閣上千山雨，嘒嘒雲中萬樹蟬。","怪得地多章句客，庾家樓在斗牛邊。"]', '["南昌城郭枕江煙，章水悠悠浪拍天。","芳草綠遮僊尉宅，落霞紅襯賈人船。","霏霏閣上千山雨，嘒嘒云中万樹蟬。","怪得地多章句客，庾家楼在斗牛邊。"]', '诗', 'shi', '', NULL, '南昌晚眺 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0d09a6a-e710-4c48-a016-d85adedb53a5', '衢州江上別李秀才', '衢州江上別李秀才', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["千山紅樹萬山雲，把酒相看日又曛。","一曲離歌兩行淚，更知何地再逢君。"]', '["千山紅樹万山云，把酒相看日又曛。","一曲離歌兩行泪，更知何地再逢君。"]', '诗', 'shi', '', NULL, '衢州江上別李秀才 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12fa19e6-3d98-41ae-85be-0f313c243a0d', '湘中作', '湘中作', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["千重煙樹萬重波，因便何妨弔汨羅。","楚地不知秦地亂，南人空怪北人多。","臣心未肯教遷鼎，天道還應欲止戈。","否去泰來終可待，夜寒休唱飯牛歌。"]', '["千重煙樹万重波，因便何妨弔汨羅。","楚地不知秦地亂，南人空怪北人多。","臣心未肯教遷鼎，天道還應欲止戈。","否去泰来終可待，夜寒休唱飯牛歌。"]', '诗', 'shi', '', NULL, '湘中作 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c50ece82-7746-463e-abf4-5eb6ce3e6afd', '桐廬縣作', '桐廬縣作', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["錢塘江盡到桐廬，水碧山青畫不如。","白羽鳥飛嚴子瀨，綠蓑人釣季鷹魚。","潭心倒影時開合，谷口閑雲自卷舒。","此境只應詞客愛，投文空弔木玄虛。"]', '["錢塘江尽到桐廬，水碧山青畫不如。","白羽鸟飞嚴子瀨，綠蓑人釣季鷹鱼。","潭心倒影时开合，谷口闲云自卷舒。","此境只應词客愛，投文空弔木玄虛。"]', '诗', 'shi', '', NULL, '桐廬縣作 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57929676-0aff-416d-898a-c92712486519', '東陽贈別', '东陽贈別', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["繡袍公子出旌旗，送我搖鞭入翠微。","大抵行人難訴酒，就中辭客易沾衣。","去時此地題橋去，歸日何年佩印歸。","無限別情言不得，回看溪柳恨依依。"]', '["繡袍公子出旌旗，送我搖鞭入翠微。","大抵行人难訴酒，就中辞客易沾衣。","去时此地題橋去，归日何年佩印归。","無限別情言不得，回看溪柳恨依依。"]', '诗', 'shi', '', NULL, '東陽贈別 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0f77079-cfbb-45d8-b5d9-57d54a8a8ce6', '寄湖州舍弟', '寄湖州舍弟', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["半年江上愴離襟，把得新詩喜又吟。","多病似逢秦氏藥，久貧如得顧家金。","雲煙但有穿楊志，塵土多無作吏心。","何況別來詞轉麗，不愁明代少知音。"]', '["半年江上愴離襟，把得新诗喜又吟。","多病似逢秦氏藥，久貧如得顧家金。","云煙但有穿楊志，塵土多無作吏心。","何況別来词轉丽，不愁明代少知音。"]', '诗', 'shi', '', NULL, '寄湖州舍弟 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b6c1ef7-6dd8-4470-aa2d-c9d2d425ca47', '信州西三十里山名僊人城下有月巖山其狀秀拔中有山門如滿月之狀余因行役過其下聊賦是詩', '信州西三十里山名僊人城下有月巖山其狀秀拔中有山门如满月之狀余因行役過其下聊賦是诗', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["驅車過閩越，路出饒陽西。","僊山翠如畫，簇簇生虹蜺。","羣峰若侍從，衆阜如嬰提。","巖巒互吞吐，嶺岫相追攜。","中有月輪滿，皎潔如圓珪。","玉皇恣遊覽，到此神應迷。","常娥曳霞帔，引我同攀躋。","騰騰上天半，玉鏡懸飛梯。","瑤池何悄悄，鸞鶴煙中棲。","回頭望塵世，露下寒淒淒。"]', '["驱车過閩越，路出饒陽西。","僊山翠如畫，簇簇生虹蜺。","羣峰若侍從，衆阜如嬰提。","巖巒互吞吐，嶺岫相追携。","中有月輪满，皎潔如圓珪。","玉皇恣游覽，到此神應迷。","常娥曳霞帔，引我同攀躋。","腾腾上天半，玉镜懸飞梯。","瑤池何悄悄，鸾鹤煙中棲。","回头望塵世，露下寒淒淒。"]', '诗', 'shi', '', NULL, '信州西三十里山名僊人城下有月巖山其狀秀拔中有山門如滿月之狀余因行役過其下聊賦是詩 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0ac7bd1-f833-450c-ad85-d718116734c6', '婺州水館重陽日作', '婺州水館重陽日作', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["異國逢佳節，憑高獨苦吟。","一杯今日醉，萬里故園心。","水館紅蘭合，山城紫菊深。","白衣雖不至，鷗鳥自相尋。"]', '["異国逢佳節，憑高独苦吟。","一杯今日醉，万里故园心。","水館紅蘭合，山城紫菊深。","白衣雖不至，鷗鸟自相尋。"]', '诗', 'shi', '', NULL, '婺州水館重陽日作 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d8c2404-0f3d-43d4-b9bc-255a39c1c1e1', '避地越中作', '避地越中作', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["避世移家遠，天涯歲已周。","豈知今夜月，還是去年愁。","露果珠沈水，風螢燭上樓。","傷心潘騎省，華髮不禁秋。"]', '["避世移家远，天涯歲已周。","豈知今夜月，還是去年愁。","露果珠沈水，风螢燭上楼。","傷心潘騎省，华髮不禁秋。"]', '诗', 'shi', '', NULL, '避地越中作 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8cee61b-ae15-4dd6-ace1-4b406efb5bef', '撫州江口雨中作', '撫州江口雨中作', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["江上閑衝細雨行，滿衣風灑綠荷聲。","金騮掉尾橫鞭望，猶指廬陵半日程。"]', '["江上闲衝細雨行，满衣风灑綠荷声。","金騮掉尾橫鞭望，猶指廬陵半日程。"]', '诗', 'shi', '', NULL, '撫州江口雨中作 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('064394d6-3293-411e-8fd7-4b3088063efd', '信州溪岸夜吟作', '信州溪岸夜吟作', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["夜倚臨溪店，懷鄉獨苦吟。","月當山頂出，星倚水湄沈。","霧氣漁燈冷，鐘聲谷寺深。","一城人悄悄，琪樹宿僊禽。"]', '["夜倚臨溪店，懷乡独苦吟。","月當山頂出，星倚水湄沈。","霧氣漁灯冷，鐘声谷寺深。","一城人悄悄，琪樹宿僊禽。"]', '诗', 'shi', '', NULL, '信州溪岸夜吟作 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5bd3317-d0ec-4d23-9020-b0274d508296', '訪潯陽友人不遇', '訪潯陽友人不遇', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["不見安期悔上樓，寂寥人對鷺鷥愁。","蘆花雨急江煙暝，何處潺潺獨棹舟。"]', '["不见安期悔上楼，寂寥人对鷺鷥愁。","蘆花雨急江煙暝，何处潺潺独棹舟。"]', '诗', 'shi', '', NULL, '訪潯陽友人不遇 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('886b1d8d-dbb7-4371-b57d-352dd24fec1c', '東林寺再遇僧益大德', '东林寺再遇僧益大德', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["見師初事懿皇朝，三殿歸來白馬驕。","上講每教傾國聽，承恩偏得內官饒。","當時可愛人如畫，今日相逢鬢已凋。","若向君門逢舊友，爲傳音信到雲霄。"]', '["见師初事懿皇朝，三殿归来白马驕。","上講每教傾国听，承恩偏得內官饒。","當时可愛人如畫，今日相逢鬢已凋。","若向君门逢旧友，爲傳音信到云霄。"]', '诗', 'shi', '', NULL, '東林寺再遇僧益大德 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ded1e6c4-1a76-4625-963a-0748e5197fd3', '西塞山下作', '西塞山下作', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["西塞山前水似藍，亂雲如絮滿澄潭。","孤峰漸映湓城北，片月斜生夢澤南。","爨動曉煙烹紫蕨，露和香蔕摘黃柑。","他年却棹扁舟去，終傍蘆花結一菴。"]', '["西塞山前水似藍，亂云如絮满澄潭。","孤峰漸映湓城北，片月斜生梦澤南。","爨动晓煙烹紫蕨，露和香蔕摘黄柑。","他年却棹扁舟去，終傍蘆花結一菴。"]', '诗', 'shi', '', NULL, '西塞山下作 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e14f1b6-a358-4c9d-86a0-bf0f7cb5e64e', '齊安郡', '齊安郡', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["彌棹齊安郡，孤城百戰殘。","傍村林有虎，帶郭縣無官。","暮角梅花怨，清江桂影寒。","黍離緣底事，撩我起長歎。"]', '["彌棹齊安郡，孤城百戰殘。","傍村林有虎，带郭縣無官。","暮角梅花怨，清江桂影寒。","黍離緣底事，撩我起长歎。"]', '诗', 'shi', '', NULL, '齊安郡 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82509d1a-e202-4331-a178-d05b325ec4a0', '夏口行寄婺州諸弟', '夏口行寄婺州諸弟', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["回頭煙樹各天涯，婺女星邊遠寄家。","盡眼楚波連夢澤，滿衣春雪落江花。","雙雙得伴爭如雁，一一歸巢却羨鵶。","誰道我隨張博望，悠悠空外泛僊槎。"]', '["回头煙樹各天涯，婺女星邊远寄家。","尽眼楚波連梦澤，满衣春雪落江花。","雙雙得伴爭如雁，一一归巢却羨鵶。","誰道我隨張博望，悠悠空外泛僊槎。"]', '诗', 'shi', '', NULL, '夏口行寄婺州諸弟 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11113074-30b2-4fa3-84ba-efcd8c8fd92a', '南省伴直', '南省伴直', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["文昌二十四僊曹，盡倚紅簷種露桃。","一洞煙霞人迹少，六行槐柳鳥聲高。","星分夜彩寒侵帳，蘭惹春香綠映袍。","何事愛留詩客宿，滿庭風雨竹蕭騷。"]', '["文昌二十四僊曹，尽倚紅簷種露桃。","一洞煙霞人迹少，六行槐柳鸟声高。","星分夜彩寒侵帳，蘭惹春香綠映袍。","何事愛留诗客宿，满庭风雨竹蕭騷。"]', '诗', 'shi', '', NULL, '南省伴直 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e713c00b-1987-46ab-9352-6e7495e2d0e1', '鄠杜舊居二首 一', '鄠杜旧居二首 一', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["却到山陽事事非，谷雲谿鳥尚相依。","阮咸貧去田園盡，向秀歸來父老稀。","秋雨幾家紅稻熟，野塘何處錦鱗肥？","年年爲獻東堂策，長是蘆花別釣磯。"]', '["却到山陽事事非，谷云谿鸟尚相依。","阮咸貧去田园尽，向秀归来父老稀。","秋雨幾家紅稻熟，野塘何处錦鱗肥？","年年爲獻东堂策，长是蘆花別釣磯。"]', '诗', 'shi', '', NULL, '鄠杜舊居二首 一 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5da86153-6ca9-4766-9b43-e281669e6e60', '鄠杜舊居二首 二', '鄠杜旧居二首 二', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["一徑尋村渡碧溪，稻花香澤水千畦。","雲中寺遠磬難識，竹裏巢深鳥易迷。","紫菊亂開連井合，紅榴初綻拂簷低。","歸來滿把如澠酒，何用傷時歎鳳兮。"]', '["一徑尋村渡碧溪，稻花香澤水千畦。","云中寺远磬难識，竹裏巢深鸟易迷。","紫菊亂开連井合，紅榴初綻拂簷低。","归来满把如澠酒，何用傷时歎鳳兮。"]', '诗', 'shi', '', NULL, '鄠杜舊居二首 二 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('327cbf28-1b90-494c-92cd-99b9a50f25f6', '寄江南諸弟', '寄江南諸弟', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["萬里逢歸雁，鄉書忍淚封。","吾身不自保，爾道各何從。","性拙唯多蹇，家貧半爲慵。","祗思溪影上，臥看玉華峰。"]', '["万里逢归雁，乡书忍泪封。","吾身不自保，爾道各何從。","性拙唯多蹇，家貧半爲慵。","祗思溪影上，臥看玉华峰。"]', '诗', 'shi', '', NULL, '寄江南諸弟 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e510e2a2-f4c3-4954-bcd4-4bd09e9b7b0e', '投寄舊知', '投寄旧知', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["却將顦顇入都門，自喜青霄足故人。","萬里有家留百越，十年無路到三秦。","摧殘不是當時貌，流落空餘舊日貧。","多謝青雲好知己，莫教歸去重沾巾。"]', '["却將顦顇入都门，自喜青霄足故人。","万里有家留百越，十年無路到三秦。","摧殘不是當时貌，流落空餘旧日貧。","多謝青云好知己，莫教归去重沾巾。"]', '诗', 'shi', '', NULL, '投寄舊知 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('528b3005-3a06-4b52-861c-e6e573615e5a', '癸丑年下第獻新先輩', '癸丑年下第獻新先輩', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["五更殘月省牆邊，絳斾蜺旌卓曉煙。","千炬火中鶯出谷，一聲鐘後鶴沖天。","皆乘駿馬先歸去，獨被羸童笑晚眠。","對酒暫時情豁爾，見花依舊涕潸然。","未酬闞澤傭書債，猶欠君平賣卜錢。","何事欲休休不得，來年公道似今年。"]', '["五更殘月省牆邊，絳斾蜺旌卓晓煙。","千炬火中鶯出谷，一声鐘後鹤沖天。","皆乘駿马先归去，独被羸童笑晚眠。","对酒暫时情豁爾，见花依旧涕潸然。","未酬闞澤傭书債，猶欠君平賣卜錢。","何事欲休休不得，来年公道似今年。"]', '诗', 'shi', '', NULL, '癸丑年下第獻新先輩 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c13e0174-866c-443e-b891-c15311f2d06f', '題汧陽縣馬跑泉李學士別業', '題汧陽縣马跑泉李学士別業', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["水滿寒塘菊滿籬，籬邊無限彩禽飛。","西園夜雨紅櫻熟，南畝清風白稻肥。","草色自留閑客住，泉聲如待主人歸。","九霄岐路忙於火，肯戀斜陽守釣磯。"]', '["水满寒塘菊满籬，籬邊無限彩禽飞。","西园夜雨紅櫻熟，南畝清风白稻肥。","草色自留闲客住，泉声如待主人归。","九霄岐路忙於火，肯戀斜陽守釣磯。"]', '诗', 'shi', '', NULL, '題汧陽縣馬跑泉李學士別業 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('918eefe5-fd66-441d-ac06-01ad799fb485', '絳州過夏留獻鄭尚書', '絳州過夏留獻鄭尚书', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["朝朝沈醉引金船，不覺西風滿樹蟬。","光景暗消銀燭下，夢魂長寄玉輪邊。","因循每被時流誚，奮發須由國士憐。","明月客腸何處斷，綠槐風裏獨揚鞭。"]', '["朝朝沈醉引金船，不覺西风满樹蟬。","光景暗消銀燭下，梦魂长寄玉輪邊。","因循每被时流誚，奮發須由国士怜。","明月客腸何处斷，綠槐风裏独揚鞭。"]', '诗', 'shi', '', NULL, '絳州過夏留獻鄭尚書 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9148b00d-5d70-4ecb-8547-0c67ad92d70a', '綏州作', '綏州作', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["雕陰無樹水難流，雉堞連雲古帝州。","帶雨晚駝鳴遠戍，望鄉孤客倚高樓。","明妃去日花應笑，蔡琰歸時鬢已秋。","一曲單于暮烽起，扶蘇城上月如鉤。"]', '["雕陰無樹水难流，雉堞連云古帝州。","带雨晚駝鳴远戍，望乡孤客倚高楼。","明妃去日花應笑，蔡琰归时鬢已秋。","一曲單于暮烽起，扶蘇城上月如鉤。"]', '诗', 'shi', '', NULL, '綏州作 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57e8a2e9-6299-425b-a852-0d5c05795d53', '與東吳生相遇', '與东吳生相遇', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["十年身事各如萍，白首相逢淚滿纓。","老去不知花有態，亂來唯覺酒多情。","貧疑陋巷春偏少，貴想豪家月最明。","且對一尊開口笑，未衰應見泰階平。"]', '["十年身事各如萍，白首相逢泪满纓。","老去不知花有態，亂来唯覺酒多情。","貧疑陋巷春偏少，貴想豪家月最明。","且对一尊开口笑，未衰應见泰階平。"]', '诗', 'shi', '', NULL, '與東吳生相遇 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4593e8cb-0fb8-42dc-bffc-1f6fd3d27ef0', '庭前桃', '庭前桃', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["曾向桃源爛漫遊，也同漁父泛僊舟。","皆言洞裏千株好，未勝庭前一樹幽。","帶露似垂湘女淚，無言如伴息媯愁。","五陵公子饒春恨，莫引香風上酒樓。"]', '["曾向桃源爛漫游，也同漁父泛僊舟。","皆言洞裏千株好，未勝庭前一樹幽。","带露似垂湘女泪，無言如伴息媯愁。","五陵公子饒春恨，莫引香风上酒楼。"]', '诗', 'shi', '', NULL, '庭前桃 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f1703e7-d04b-4505-9a4b-de9fee595295', '丙辰年鄜州遇寒食城外醉吟五首 一', '丙辰年鄜州遇寒食城外醉吟五首 一', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["滿街楊柳綠絲煙，畫出清明二月天。","好是隔簾花樹動，女郎撩亂送鞦韆。"]', '["满街楊柳綠絲煙，畫出清明二月天。","好是隔簾花樹动，女郎撩亂送鞦韆。"]', '诗', 'shi', '', NULL, '丙辰年鄜州遇寒食城外醉吟五首 一 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86f7170b-c795-4d80-976d-50a418c25be2', '丙辰年鄜州遇寒食城外醉吟五首 二', '丙辰年鄜州遇寒食城外醉吟五首 二', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["雕陰寒食足遊人，金鳳羅衣濕麝薰。","腸斷入城芳草路，淡紅香白一羣羣。"]', '["雕陰寒食足游人，金鳳羅衣濕麝薰。","腸斷入城芳草路，淡紅香白一羣羣。"]', '诗', 'shi', '', NULL, '丙辰年鄜州遇寒食城外醉吟五首 二 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31b2a994-69ac-450e-9990-7daa5fb589ac', '丙辰年鄜州遇寒食城外醉吟五首 三', '丙辰年鄜州遇寒食城外醉吟五首 三', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["開元坡下日初斜，拜掃歸來走鈿車。","可惜數株紅豔好，不知今夜落誰家。"]', '["开元坡下日初斜，拜掃归来走鈿车。","可惜數株紅豔好，不知今夜落誰家。"]', '诗', 'shi', '', NULL, '丙辰年鄜州遇寒食城外醉吟五首 三 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb7de205-d319-4733-95a6-180dca8f2ccf', '丙辰年鄜州遇寒食城外醉吟五首 四', '丙辰年鄜州遇寒食城外醉吟五首 四', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["馬驕風疾玉鞭長，過去唯留一陣香。","閑客不須燒破眼，好花皆屬富家郎。"]', '["马驕风疾玉鞭长，過去唯留一陣香。","闲客不須燒破眼，好花皆屬富家郎。"]', '诗', 'shi', '', NULL, '丙辰年鄜州遇寒食城外醉吟五首 四 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5fe79be-8580-4f5f-a180-8ea68b92f531', '丙辰年鄜州遇寒食城外醉吟五首 五', '丙辰年鄜州遇寒食城外醉吟五首 五', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["雨絲煙柳欲清明，金屋人閑煖鳳笙。","永日迢迢無一事，隔街聞築氣毬聲。"]', '["雨絲煙柳欲清明，金屋人闲煖鳳笙。","永日迢迢無一事，隔街闻築氣毬声。"]', '诗', 'shi', '', NULL, '丙辰年鄜州遇寒食城外醉吟五首 五 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aadf0d8f-e53c-4c0d-b5f5-8f412df86aa2', '宜君縣比卜居不遂留題王秀才別墅二首 一', '宜君縣比卜居不遂留題王秀才別墅二首 一', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["本期同此臥林丘，榾柮爐前擁布裘。","何事却騎羸馬去，白雲紅樹不相留。"]', '["本期同此臥林丘，榾柮爐前擁布裘。","何事却騎羸马去，白云紅樹不相留。"]', '诗', 'shi', '', NULL, '宜君縣比卜居不遂留題王秀才別墅二首 一 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b17f1411-673f-4a4b-b75b-61b01d7f65b4', '宜君縣比卜居不遂留題王秀才別墅二首 二', '宜君縣比卜居不遂留題王秀才別墅二首 二', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["明月嚴霜撲皁貂，羨君高臥正逍遙。","門前積雪深三尺，火滿紅爐酒滿瓢。"]', '["明月嚴霜撲皁貂，羨君高臥正逍遙。","门前積雪深三尺，火满紅爐酒满瓢。"]', '诗', 'shi', '', NULL, '宜君縣比卜居不遂留題王秀才別墅二首 二 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d7122f6-a1d3-4219-8be7-64ddd46aa3c5', '鄜州留別張員外', '鄜州留別張員外', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["江南相送君山下，塞北相逢朔漠中。","三楚故人皆是夢，十年陳事只如風。","莫言身世他時異，且喜琴尊數日同。","惆悵却愁明日別，馬嘶山店雨濛濛。"]', '["江南相送君山下，塞北相逢朔漠中。","三楚故人皆是梦，十年陳事只如风。","莫言身世他时異，且喜琴尊數日同。","惆悵却愁明日別，马嘶山店雨濛濛。"]', '诗', 'shi', '', NULL, '鄜州留別張員外 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5eddc04b-8923-41ae-87b6-653330c8087d', '病中聞相府夜宴戲贈集賢盧學士', '病中闻相府夜宴戲贈集賢盧学士', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["滿筵紅蠟照香鈿，一夜歌鐘欲沸天。","花裏亂飛金錯落，月中爭認繡連乾。","尊前莫話詩三百，醉後寧辭酒十千。","無那兩三新進士，風流長得飲徒憐。"]', '["满筵紅蠟照香鈿，一夜歌鐘欲沸天。","花裏亂飞金錯落，月中爭認繡連乾。","尊前莫話诗三百，醉後寧辞酒十千。","無那兩三新進士，风流长得饮徒怜。"]', '诗', 'shi', '', NULL, '病中聞相府夜宴戲贈集賢盧學士 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d75c1f73-ae54-4f10-9ffc-7f6c00209595', '出關', '出关', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["馬嘶煙岸柳陰斜，東去關山路轉賒。","到處因循緣嗜酒，一生惆悵爲判花。","危時祗合身無著，白日那堪事有涯。","正是灞陵春酬綠，仲宣何事獨辭家。"]', '["马嘶煙岸柳陰斜，东去关山路轉賒。","到处因循緣嗜酒，一生惆悵爲判花。","危时祗合身無著，白日那堪事有涯。","正是灞陵春酬綠，仲宣何事独辞家。"]', '诗', 'shi', '', NULL, '出關 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c0eead3-d227-4a76-a6c8-630d3fbe7c0f', '過樊川舊居', '過樊川旧居', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["却到樊川訪舊遊，夕陽衰草杜陵秋。","應劉去後苔生閣，稽阮歸來雪滿頭。","能說亂離惟有燕，解偷閑暇不如鷗。","千桑萬海無人見，橫笛一聲空淚流。"]', '["却到樊川訪旧游，夕陽衰草杜陵秋。","應劉去後苔生閣，稽阮归来雪满头。","能说亂離惟有燕，解偷闲暇不如鷗。","千桑万海無人见，橫笛一声空泪流。"]', '诗', 'shi', '', NULL, '過樊川舊居 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2aa34f46-9cd6-471a-af8e-e79889cd8fdf', '長安舊里', '长安旧里', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["滿目牆匡春草深，傷時傷事更傷心。","車輪馬跡今何在，十二玉樓無處尋。"]', '["满目牆匡春草深，傷时傷事更傷心。","车輪马跡今何在，十二玉楼無处尋。"]', '诗', 'shi', '', NULL, '長安舊里 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38e6bd79-75ae-4500-9987-530ce51ade47', '過渼陂懷舊', '過渼陂懷旧', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["辛勤曾寄玉峰前，一別雲溪二十年。","三徑荒涼迷竹樹，四鄰凋謝變桑田。","渼陂可是當時事，紫閣空餘舊日煙。","多少亂離無處問，夕陽吟罷涕潸然。"]', '["辛勤曾寄玉峰前，一別云溪二十年。","三徑荒涼迷竹樹，四鄰凋謝变桑田。","渼陂可是當时事，紫閣空餘旧日煙。","多少亂離無处问，夕陽吟罷涕潸然。"]', '诗', 'shi', '', NULL, '過渼陂懷舊 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e9a3500-fb1c-4883-9441-37a4903a9ecd', '汧陽間', '汧陽间', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["汧水悠悠去似絣，遠山如畫翠眉橫。","僧尋野渡歸吳嶽，雁帶斜陽入渭城。","邊靜不收蕃帳馬，地貧惟賣隴山鸚。","牧童何處吹羌笛，一曲梅花出塞聲。"]', '["汧水悠悠去似絣，远山如畫翠眉橫。","僧尋野渡归吳嶽，雁带斜陽入渭城。","邊静不收蕃帳马，地貧惟賣隴山鸚。","牧童何处吹羌笛，一曲梅花出塞声。"]', '诗', 'shi', '', NULL, '汧陽間 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8b2519b-9b24-4f9c-83c0-f66430c0e137', '焦崖閣', '焦崖閣', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["李白曾歌蜀道難，長聞白日上青天。","今朝夜過焦崖閣，始信星河在馬前。"]', '["李白曾歌蜀道难，长闻白日上青天。","今朝夜過焦崖閣，始信星河在马前。"]', '诗', 'shi', '', NULL, '焦崖閣 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8b6a8eb-8f4c-45ab-9030-0ac8d55d6174', '雞公幘', '雞公幘', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["石狀雖如幘，山形可類雞。","向風疑欲鬬，帶雨似聞啼。","蔓織青籠合，松長翠羽低。","不鳴非有意，爲怕客奔齊。"]', '["石狀雖如幘，山形可類雞。","向风疑欲鬬，带雨似闻啼。","蔓织青籠合，松长翠羽低。","不鳴非有意，爲怕客奔齊。"]', '诗', 'shi', '', NULL, '雞公幘 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6065f389-5f50-4804-8c2e-2e094104cc42', '平陵老將', '平陵老將', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["白羽金僕姑，腰懸雙轆轤。","前年蔥嶺北，獨戰雲中胡。","匹馬塞垣老，一身如鳥孤。","歸來辭第宅，却占平陵居。"]', '["白羽金僕姑，腰懸雙轆轤。","前年蔥嶺北，独戰云中胡。","匹马塞垣老，一身如鸟孤。","归来辞第宅，却占平陵居。"]', '诗', 'shi', '', NULL, '平陵老將 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e843268a-0cbd-4f2d-b446-9797ec76e51e', '即事', '即事', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["亂世時偏促，陰天日易昏。","無言搔白首，憔悴倚東門。"]', '["亂世时偏促，陰天日易昏。","無言搔白首，憔悴倚东门。"]', '诗', 'shi', '', NULL, '即事 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87170517-a2da-4b5e-93a1-8c302b707417', '姬人養蠶', '姬人養蠶', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["昔年愛笑蠶家婦，今日辛勤自養蠶。","仍道不愁羅與綺，女郎初解織桑籃。"]', '["昔年愛笑蠶家婦，今日辛勤自養蠶。","仍道不愁羅與綺，女郎初解织桑籃。"]', '诗', 'shi', '', NULL, '姬人養蠶 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa5690a4-1392-4de3-984d-37311fdcda37', '長干塘別徐茂才', '长干塘別徐茂才', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["亂離時節別離輕，別酒應須滿滿傾。","纔喜相逢又相送，有情爭得似無情。"]', '["亂離时節別離轻，別酒應須满满傾。","纔喜相逢又相送，有情爭得似無情。"]', '诗', 'shi', '', NULL, '長干塘別徐茂才 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cb5b066-9685-45d5-8a1d-f2e59d494efb', '勉兒子', '勉兒子', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["養爾逢多難，常憂學已遲。","辟彊爲上相，何必待從師。"]', '["養爾逢多难，常憂学已遲。","辟彊爲上相，何必待從師。"]', '诗', 'shi', '', NULL, '勉兒子 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76bf8b2e-a6dc-4102-9f91-5f029b692596', '乞彩牋歌', '乞彩牋歌', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["浣花溪上如花客，綠闇紅藏人不識。","留得溪頭瑟瑟波，潑成紙上猩猩色。","手把金刀擘綵雲，有時翦破秋天碧。","不使紅霓段段飛，一時驅上丹霞壁。","蜀客才多染不供，卓文醉後開無力。","孔雀銜來向日飛，翩翩壓折黃金翼。","我有歌詩一千首，磨礱山岳羅星斗。","開卷長疑雷電驚，揮毫只怕龍蛇走。","班班布在時人口，滿袖松花都未有。","人間無處買煙霞，須知得自神僊手。","也知價重連城璧，一紙萬金猶不惜。","薛濤昨夜夢中來，殷勤勸向君邊覓。"]', '["浣花溪上如花客，綠闇紅藏人不識。","留得溪头瑟瑟波，潑成紙上猩猩色。","手把金刀擘綵云，有时翦破秋天碧。","不使紅霓段段飞，一时驱上丹霞壁。","蜀客才多染不供，卓文醉後开無力。","孔雀銜来向日飞，翩翩壓折黄金翼。","我有歌诗一千首，磨礱山岳羅星斗。","开卷长疑雷電驚，揮毫只怕龙蛇走。","班班布在时人口，满袖松花都未有。","人间無处買煙霞，須知得自神僊手。","也知價重連城璧，一紙万金猶不惜。","薛濤昨夜梦中来，殷勤勸向君邊覓。"]', '诗', 'shi', '', NULL, '乞彩牋歌 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63428866-f599-4162-a3f1-9052f4d2a8c4', '白牡丹', '白牡丹', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["閨中莫妬新妝歸，陌上須慚傅粉郎。","昨夜月明渾似水，入門唯覺一庭香。"]', '["閨中莫妬新妝归，陌上須慚傅粉郎。","昨夜月明渾似水，入门唯覺一庭香。"]', '诗', 'shi', '', NULL, '白牡丹 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd1a591e-98c5-406d-97e9-6f90592b1bfe', '憫耕者', '憫耕者', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["何代何王不戰爭，盡從離亂見清平。","如今暴骨多於土，猶點鄉兵作戍兵。"]', '["何代何王不戰爭，尽從離亂见清平。","如今暴骨多於土，猶点乡兵作戍兵。"]', '诗', 'shi', '', NULL, '憫耕者 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b6f6b37-fcd3-46aa-8422-094e4d6073fc', '壺關道中作', '壺关道中作', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["處處兵戈路不通，却從山北去江東。","黃昏欲到壺關寨，匹馬寒嘶野草中。"]', '["处处兵戈路不通，却從山北去江东。","黄昏欲到壺关寨，匹马寒嘶野草中。"]', '诗', 'shi', '', NULL, '壺關道中作 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0184140-23d9-4d27-976d-fca298b2ed6e', '題酒家', '題酒家', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["酒綠花紅客愛詩，落花春岸酒家旗。","尋思避世爲逋客，不醉長醒也是癡。"]', '["酒綠花紅客愛诗，落花春岸酒家旗。","尋思避世爲逋客，不醉长醒也是癡。"]', '诗', 'shi', '', NULL, '題酒家 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a05bb44d-92fc-4844-8e29-375615b688e0', '寄舍弟', '寄舍弟', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["每吟富貴他人合，不覺汍瀾又濕衣。","萬里日邊鄉樹遠，何年何路得同歸。"]', '["每吟富貴他人合，不覺汍瀾又濕衣。","万里日邊乡樹远，何年何路得同归。"]', '诗', 'shi', '', NULL, '寄舍弟 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a167cfa-b286-4b7b-85d4-93de02e319a0', '僕者楊金', '僕者楊金', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["半年辛苦葺荒居，不獨單寒腹亦虛。","努力且爲田舍客，他年爲爾覓金魚。"]', '["半年辛苦葺荒居，不独單寒腹亦虛。","努力且爲田舍客，他年爲爾覓金鱼。"]', '诗', 'shi', '', NULL, '僕者楊金 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0d19572-f0e9-4af7-9b32-9c33d722b4c7', '春陌二首 一', '春陌二首 一', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["滿街芳草卓香車，僊子門前白日斜。","腸斷東風各回首，一枝春雪凍梅花。"]', '["满街芳草卓香车，僊子门前白日斜。","腸斷东风各回首，一枝春雪凍梅花。"]', '诗', 'shi', '', NULL, '春陌二首 一 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00729e0e-ac41-4e31-b2df-f09c4c54eff2', '春陌二首 二', '春陌二首 二', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["嫩煙輕染柳絲黃，句引花枝笑凭牆。","馬上王孫莫回首，好風偏逐羽林郎。"]', '["嫩煙轻染柳絲黄，句引花枝笑凭牆。","马上王孫莫回首，好风偏逐羽林郎。"]', '诗', 'shi', '', NULL, '春陌二首 二 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('949fcea1-ca0f-459f-a0c8-f91043bce4ee', '贈姬人', '贈姬人', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["莫恨紅裙破，休嫌白屋低。","請看京與洛，誰在舊香閨。"]', '["莫恨紅裙破，休嫌白屋低。","請看京與洛，誰在旧香閨。"]', '诗', 'shi', '', NULL, '贈姬人 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc053859-773f-4bdf-945d-15dc749b9c49', '中酒', '中酒', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["南鄰酒熟愛相招，蘸甲傾來綠滿瓢。","一醉不知三日事，任他童穉作漁樵。"]', '["南鄰酒熟愛相招，蘸甲傾来綠满瓢。","一醉不知三日事，任他童穉作漁樵。"]', '诗', 'shi', '', NULL, '中酒 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b42a2989-20e1-4283-a5e7-79db9f265518', '暴雨', '暴雨', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["江村入夏多雷雨，曉作狂霖晚又晴。","波浪不知深幾許，南湖今與北湖平。"]', '["江村入夏多雷雨，晓作狂霖晚又晴。","波浪不知深幾許，南湖今與北湖平。"]', '诗', 'shi', '', NULL, '暴雨 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('484213a8-72ee-46a7-80df-3725590b2ce2', '悼亡姬', '悼亡姬', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["鳳去鸞歸不可尋，十洲仙路彩雲深。","若無少女花應老，爲有姮娥月易沈。","竹葉豈能消積恨，丁香空解結同心。"]', '["鳳去鸾归不可尋，十洲仙路彩云深。","若無少女花應老，爲有姮娥月易沈。","竹葉豈能消積恨，丁香空解結同心。"]', '诗', 'shi', '', NULL, '悼亡姬 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65a62527-e0bd-40f1-9d8b-4b6c9a4fff49', '獨吟', '独吟', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["默默無言惻惻悲，閑吟獨傍菊花籬。","只今已作經年別，此後如爲幾歲期。","開篋每尋遺念物，倚樓空綴悼亡詩。","夜來孤枕空腸斷，窗月斜輝夢覺時。"]', '["默默無言惻惻悲，闲吟独傍菊花籬。","只今已作經年別，此後如爲幾歲期。","开篋每尋遺念物，倚楼空綴悼亡诗。","夜来孤枕空腸斷，窗月斜輝梦覺时。"]', '诗', 'shi', '', NULL, '獨吟 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('589d516f-cbb9-442e-90fe-033410af3057', '悔恨', '悔恨', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["六七年來春又秋，也同歡笑也同愁。","纔聞及第心先喜，試說求婚淚便流。","幾爲妒來頻斂黛，每思閑事不梳頭。","如今悔恨將何益，腸斷千休與萬休。"]', '["六七年来春又秋，也同歡笑也同愁。","纔闻及第心先喜，試说求婚泪便流。","幾爲妒来頻斂黛，每思闲事不梳头。","如今悔恨將何益，腸斷千休與万休。"]', '诗', 'shi', '', NULL, '悔恨 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8fb4bc0-33bb-468e-8292-047eacaf2703', '虛席', '虛席', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["一閉香閨後，羅衣盡施僧。","鼠偷筵上果，蛾撲帳前燈。","土蝕釵無鳳，塵生鏡少菱。","有時還影響，花葉曳香繒。"]', '["一閉香閨後，羅衣尽施僧。","鼠偷筵上果，蛾撲帳前灯。","土蝕釵無鳳，塵生镜少菱。","有时還影响，花葉曳香繒。"]', '诗', 'shi', '', NULL, '虛席 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('379bca5e-f317-4c48-abe8-4d5e1269d902', '舊居', '旧居', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["芳草又芳草，故人楊子家。","青雲容易散，白日等閑斜。","皓質留殘雪，香魂逐斷霞。","不知何處笛，一夜呌梅花。"]', '["芳草又芳草，故人楊子家。","青云容易散，白日等闲斜。","皓質留殘雪，香魂逐斷霞。","不知何处笛，一夜呌梅花。"]', '诗', 'shi', '', NULL, '舊居 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83f1050c-d2e0-4552-aa14-0917ab9de08f', '晏起', '晏起', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["爾來中酒起常遲，臥看南山改舊詩。","開戶日高春寂寂，數聲啼鳥上花枝。"]', '["爾来中酒起常遲，臥看南山改旧诗。","开戶日高春寂寂，數声啼鸟上花枝。"]', '诗', 'shi', '', NULL, '晏起 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ed6550a-7281-4ea9-994a-14a2469e7d44', '幽居春思', '幽居春思', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["綠映紅藏江上村，一聲雞犬似山源。","閉門盡日無人到，翠羽春禽滿樹喧。"]', '["綠映紅藏江上村，一声雞犬似山源。","閉门尽日無人到，翠羽春禽满樹喧。"]', '诗', 'shi', '', NULL, '幽居春思 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b39275f0-34a2-46c3-9230-5815af62c677', '思歸引', '思归引', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["越鳥南翔鴈北飛，兩鄉雲路各言歸。","如何我是飄飄者，獨向江頭戀釣磯。"]', '["越鸟南翔鴈北飞，兩乡云路各言归。","如何我是飄飄者，独向江头戀釣磯。"]', '诗', 'shi', '', NULL, '思歸引 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2a48a3c-edfe-4102-941e-8a2c911e9236', '與小女', '與小女', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["見人初解語嘔啞，不肯歸眠戀小車。","一夜嬌啼緣底事，爲嫌衣少縷金華。"]', '["见人初解語嘔啞，不肯归眠戀小车。","一夜嬌啼緣底事，爲嫌衣少縷金华。"]', '诗', 'shi', '', NULL, '與小女 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c53dcfc2-1eee-4f2a-a8ec-d1a476f9d9dd', '虎跡', '虎跡', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["白額頻頻夜到門，水邊蹤跡漸成羣。","我今避世棲巖穴，巖穴如何又見君。"]', '["白額頻頻夜到门，水邊蹤跡漸成羣。","我今避世棲巖穴，巖穴如何又见君。"]', '诗', 'shi', '', NULL, '虎跡 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7722c42-54cc-447a-b197-5499d5fd8336', '買酒不得', '買酒不得', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["停尊待爾怪來遲，手挈空缾毷氉歸。","滿面春愁消不得，更看溪鷺寂寥飛。"]', '["停尊待爾怪来遲，手挈空缾毷氉归。","满面春愁消不得，更看溪鷺寂寥飞。"]', '诗', 'shi', '', NULL, '買酒不得 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cba95d3-3473-4bfa-9d5f-9aaa2915d887', '得故人書', '得故人书', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["正向溪頭自采蘇，青雲忽得故人書。","殷勤問我歸來否，雙闕而今畫不如。"]', '["正向溪头自采蘇，青云忽得故人书。","殷勤问我归来否，雙闕而今畫不如。"]', '诗', 'shi', '', NULL, '得故人書 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d17c423d-4847-42f9-accf-f3d1264db27e', '洪州送僧遊福建', '洪州送僧游福建', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["八月風波似鼓鼙，可堪波上各東西。","殷勤早作歸來計，莫戀猿聲住建溪。"]', '["八月风波似鼓鼙，可堪波上各东西。","殷勤早作归来計，莫戀猿声住建溪。"]', '诗', 'shi', '', NULL, '洪州送僧遊福建 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7bd573e-002b-4310-8074-c1ce93a3f84b', '聞回戈軍', '闻回戈軍', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["上將鏖兵又欲旋，翠華巡幸已三年。","營中不用栽楊柳，願戴儒冠爲控弦。"]', '["上將鏖兵又欲旋，翠华巡幸已三年。","營中不用栽楊柳，願戴儒冠爲控弦。"]', '诗', 'shi', '', NULL, '聞回戈軍 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73024b46-aa81-4846-9870-cdd6d6980ec1', '南鄰公子', '南鄰公子', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["南鄰公子夜歸聲，數炬銀燈隔竹明。","醉凭馬鬃扶不起，更邀紅袖出門迎。"]', '["南鄰公子夜归声，數炬銀灯隔竹明。","醉凭马鬃扶不起，更邀紅袖出门迎。"]', '诗', 'shi', '', NULL, '南鄰公子 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4070be4-79c3-42c9-8a0f-f8385108c5ec', '憶小女銀娘', '憶小女銀娘', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["睦州江上水門西，蕩槳揚帆各解攜。","今日天涯夜深坐，斷腸偏憶阿銀犂。"]', '["睦州江上水门西，蕩槳揚帆各解携。","今日天涯夜深坐，斷腸偏憶阿銀犂。"]', '诗', 'shi', '', NULL, '憶小女銀娘 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3b81d14-d4ed-45e7-84a0-de1c988e7e52', '女僕阿汪', '女僕阿汪', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["念爾辛勤歲已深，亂離相失又相尋。","他年待我門如市，報爾千金與萬金。"]', '["念爾辛勤歲已深，亂離相失又相尋。","他年待我门如市，報爾千金與万金。"]', '诗', 'shi', '', NULL, '女僕阿汪 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64bf645c-5c3a-4fcc-bac2-f2720be4c3dc', '河清縣河亭', '河清縣河亭', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["由來多感莫憑高，竟日衷腸似有刀。","人事任成陵與谷，大河東去自滔滔。"]', '["由来多感莫憑高，竟日衷腸似有刀。","人事任成陵與谷，大河东去自滔滔。"]', '诗', 'shi', '', NULL, '河清縣河亭 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b87efa81-b749-47e4-a2a6-ec43dcbaa306', '鍾陵夜闌作', '鍾陵夜闌作', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["鍾陵風雪夜將深，坐對寒江獨苦吟。","流落天涯誰見問，少卿應識子卿心。"]', '["鍾陵风雪夜將深，坐对寒江独苦吟。","流落天涯誰见问，少卿應識子卿心。"]', '诗', 'shi', '', NULL, '鍾陵夜闌作 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8679bf2-5b5c-45b5-aa89-baaeb8470c7c', '悼楊氏妓琴弦', '悼楊氏妓琴弦', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["魂歸寥廓魄歸煙，只住人間十八年。","昨日施僧裙帶上，斷腸猶繫琵琶弦。"]', '["魂归寥廓魄归煙，只住人间十八年。","昨日施僧裙带上，斷腸猶繫琵琶弦。"]', '诗', 'shi', '', NULL, '悼楊氏妓琴弦 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd45c018-417b-4000-9e1d-b948bc43a48c', '殘花', '殘花', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["江頭沈醉泥斜暉，却向花前慟哭歸。","惆悵一年春又去，碧雲芳草兩依依。"]', '["江头沈醉泥斜暉，却向花前慟哭归。","惆悵一年春又去，碧云芳草兩依依。"]', '诗', 'shi', '', NULL, '殘花 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('885d9525-9c23-4ff2-abc2-60d1988541b5', '歲晏同左生作', '歲晏同左生作', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["歲暮鄉關遠，天涯手重攜。","雪埋江樹短，雲壓夜城低。","寶瑟湘靈怨，清砧杜魄啼。","不須臨皎鏡，年長易淒淒。"]', '["歲暮乡关远，天涯手重携。","雪埋江樹短，云壓夜城低。","寶瑟湘靈怨，清砧杜魄啼。","不須臨皎镜，年长易淒淒。"]', '诗', 'shi', '', NULL, '歲晏同左生作 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3119d358-731f-4bc8-991d-ddf56bcf0f2c', '咸陽懷古', '咸陽懷古', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["城邊人倚夕陽樓，城上雲凝萬古愁。","山色不知秦苑廢，水聲空傍漢宮流。","李斯不向倉中悟，徐福應無物外遊。","莫怪楚吟偏斷骨，野煙蹤跡似東周。"]', '["城邊人倚夕陽楼，城上云凝万古愁。","山色不知秦苑廢，水声空傍漢宮流。","李斯不向倉中悟，徐福應無物外游。","莫怪楚吟偏斷骨，野煙蹤跡似东周。"]', '诗', 'shi', '', NULL, '咸陽懷古 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c162e3ec-4c71-4964-8cc6-c746ef1fc633', '和同年韋學士華下途中見寄', '和同年韋学士华下途中见寄', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["綠楊城郭雨淒淒，過盡千輪與萬蹄。","送我獨遊三蜀路，羨君新上九霄梯。","馬驚門外山如活，花笑尊前客似泥。","正是清和好時節，不堪離恨劍門西。"]', '["綠楊城郭雨淒淒，過尽千輪與万蹄。","送我独游三蜀路，羨君新上九霄梯。","马驚门外山如活，花笑尊前客似泥。","正是清和好时節，不堪離恨劍门西。"]', '诗', 'shi', '', NULL, '和同年韋學士華下途中見寄 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('025b9928-43ed-4424-b271-36169df11222', '春愁', '春愁', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["自有春愁正斷魂，不堪芳草思王孫。","落花寂寂黃昏雨，深院無人獨倚門。"]', '["自有春愁正斷魂，不堪芳草思王孫。","落花寂寂黄昏雨，深院無人独倚门。"]', '诗', 'shi', '', NULL, '春愁 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8995e452-a0e8-40aa-b092-0a0ba33d245d', '傷灼灼', '傷灼灼', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["嘗聞灼灼麗於花，雲髻盤時未破瓜。","桃臉曼長橫綠水，玉肌香膩透紅紗。","多情不住神仙界，薄命曾嫌富貴家。","流落錦江無處問，斷魂飛作碧天霞。"]', '["嘗闻灼灼丽於花，云髻盤时未破瓜。","桃臉曼长橫綠水，玉肌香膩透紅紗。","多情不住神仙界，薄命曾嫌富貴家。","流落錦江無处问，斷魂飞作碧天霞。"]', '诗', 'shi', '', NULL, '傷灼灼 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f180195-2cba-4d01-af74-19a28c90633f', '漢州', '漢州', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["比儂初到漢州城，郭邑樓臺觸目驚。","松桂影中旌斾色，芰荷風裏管弦聲。","人心不似經離亂，時運還應却太平。","十日醉眠金鴈驛，臨岐無恨臉波橫。"]', '["比儂初到漢州城，郭邑楼台觸目驚。","松桂影中旌斾色，芰荷风裏管弦声。","人心不似經離亂，时運還應却太平。","十日醉眠金鴈驛，臨岐無恨臉波橫。"]', '诗', 'shi', '', NULL, '漢州 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78070251-8d63-420c-9c34-56cef2d11c64', '長安清明', '长安清明', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["蚤是傷春夢雨天，可堪芳草更芊芊。","內官初賜清明火，上相閑分白打錢。","紫陌亂嘶紅叱撥，綠[楊]高映畫鞦韆。","遊人記得承平事，暗喜風光似昔年。"]', '["蚤是傷春梦雨天，可堪芳草更芊芊。","內官初賜清明火，上相闲分白打錢。","紫陌亂嘶紅叱撥，綠[楊]高映畫鞦韆。","游人記得承平事，暗喜风光似昔年。"]', '诗', 'shi', '', NULL, '長安清明 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0abe04f0-a0e5-4811-be2e-119834638c1a', '秋霽晚景', '秋霽晚景', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["秋霽禁城晚，六街煙雨殘。","牆頭山色健，林外鳥聲歡。","翹日樓臺麗，清風劒佩寒。","玉人襟袖薄，斜凭翠闌干。"]', '["秋霽禁城晚，六街煙雨殘。","牆头山色健，林外鸟声歡。","翹日楼台丽，清风劒佩寒。","玉人襟袖薄，斜凭翠闌干。"]', '诗', 'shi', '', NULL, '秋霽晚景 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2dea72c-7608-4e44-b12a-00aed6ef1913', '和人春暮書事寄崔秀才', '和人春暮书事寄崔秀才', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["半掩朱門白日長，晚風輕墮落梅妝。","不知芳草情何限，只怪遊人思易傷。","纔見早春鶯出谷，已驚新夏燕巢梁。","相逢只賴如澠酒，一曲狂歌入醉鄉。"]', '["半掩朱门白日长，晚风轻墮落梅妝。","不知芳草情何限，只怪游人思易傷。","纔见早春鶯出谷，已驚新夏燕巢梁。","相逢只賴如澠酒，一曲狂歌入醉乡。"]', '诗', 'shi', '', NULL, '和人春暮書事寄崔秀才 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6051f86-74d0-4457-b0db-d81615f0e488', '古離別', '古離別', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["一生風月供惆悵，到處煙花恨別離。","止竟多情何處好，少年長抱少年悲。"]', '["一生风月供惆悵，到处煙花恨別離。","止竟多情何处好，少年长抱少年悲。"]', '诗', 'shi', '', NULL, '古離別 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93646161-5228-4075-ba0c-16c11c34d8f7', '邊上逢薛秀才話舊', '邊上逢薛秀才話旧', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["前年同醉武陵亭，絕倒閑譚坐到明。","也有絳脣歌白雪，更憐紅袖奪金觥。","秦雲一散如春夢，楚市千燒作故城。","今日皤然對芳草，不勝東望涕交橫。"]', '["前年同醉武陵亭，絕倒闲譚坐到明。","也有絳脣歌白雪，更怜紅袖奪金觥。","秦云一散如春梦，楚市千燒作故城。","今日皤然对芳草，不勝东望涕交橫。"]', '诗', 'shi', '', NULL, '邊上逢薛秀才話舊 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61e25bc2-1a35-40af-b3a6-4f4e48bf91f5', '飲散呈主人', '饮散呈主人', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["夢覺笙歌散，空堂寂寞秋。","更聞城角弄，煙雨不勝愁。"]', '["梦覺笙歌散，空堂寂寞秋。","更闻城角弄，煙雨不勝愁。"]', '诗', 'shi', '', NULL, '飲散呈主人 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fd2e3d4-cca8-4c7d-808b-8ec86a13441b', '使院黃葵花', '使院黄葵花', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["薄妝新著澹黃衣，對捧金爐侍醮遲。","向月似矜傾國貌，倚風如唱步虛詞。","乍開檀炷疑聞語，試與雲和必解吹。","爲報同人看來好，不禁秋露即離披。"]', '["薄妝新著澹黄衣，对捧金爐侍醮遲。","向月似矜傾国貌，倚风如唱步虛词。","乍开檀炷疑闻語，試與云和必解吹。","爲報同人看来好，不禁秋露即離披。"]', '诗', 'shi', '', NULL, '使院黃葵花 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab556704-b0d0-459b-890d-959c5e16ee36', '搖落', '搖落', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["搖落秋天酒易醒，淒淒長似別離情。","黃昏倚柱不歸去，腸斷綠荷風雨聲。"]', '["搖落秋天酒易醒，淒淒长似別離情。","黄昏倚柱不归去，腸斷綠荷风雨声。"]', '诗', 'shi', '', NULL, '搖落 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5d5b599-5c1b-403d-9279-54f55be44374', '奉和觀察郎中春暮憶花言懷見寄四韻之什', '奉和观察郎中春暮憶花言懷见寄四韻之什', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["天畔峨嵋簇簇青，楚雲何處隔重扃。","落花帶雪埋芳草，春雨和風濕畫屏。","對酒莫辭衝暮角，望鄉誰解倚南亭。","惟君信我多惆悵，只願陶陶不願醒。"]', '["天畔峨嵋簇簇青，楚云何处隔重扃。","落花带雪埋芳草，春雨和风濕畫屏。","对酒莫辞衝暮角，望乡誰解倚南亭。","惟君信我多惆悵，只願陶陶不願醒。"]', '诗', 'shi', '', NULL, '奉和觀察郎中春暮憶花言懷見寄四韻之什 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0598ec3-6803-4372-ab49-4058f293fe4e', '奉和左司郎中春物暗度感而成章', '奉和左司郎中春物暗度感而成章', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["纔喜新春已暮春，夕陽吟殺倚樓人。","錦江風散霏霏雨，花市香飄漠漠塵。","今日尚追巫峽夢，少年應遇洛川神。","有時自患多情病，莫是生前宋玉身。"]', '["纔喜新春已暮春，夕陽吟殺倚楼人。","錦江风散霏霏雨，花市香飄漠漠塵。","今日尚追巫峽梦，少年應遇洛川神。","有时自患多情病，莫是生前宋玉身。"]', '诗', 'shi', '', NULL, '奉和左司郎中春物暗度感而成章 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('117f1a06-7426-4142-8b2d-3cffbb7cb45b', '少年行', '少年行', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["五陵豪客多，買酒黃金𧣴。","醉下酒家樓，美人雙翠幰。","揮劒邯鄲市，走馬梁王苑。","樂事殊未央，年華已云晚。"]', '["五陵豪客多，買酒黄金𧣴。","醉下酒家楼，美人雙翠幰。","揮劒邯鄲市，走马梁王苑。","乐事殊未央，年华已云晚。"]', '诗', 'shi', '', NULL, '少年行 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68ea735a-cca0-4f06-a1b8-2bf1f1d667eb', '令狐亭', '令狐亭', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["若非天上神仙宅，須是人間將相家。","想得當時好煙月，管弦吹殺後庭花。"]', '["若非天上神仙宅，須是人间將相家。","想得當时好煙月，管弦吹殺後庭花。"]', '诗', 'shi', '', NULL, '令狐亭 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f728009-17da-499f-923d-ff6e755b11b9', '閨月', '閨月', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["明月照前除，煙華蕙蘭濕。","清風行處來，白露寒蟬急。","美人情易傷，暗上紅樓立。","欲言無處言，但向姮娥泣。"]', '["明月照前除，煙华蕙蘭濕。","清风行处来，白露寒蟬急。","美人情易傷，暗上紅楼立。","欲言無处言，但向姮娥泣。"]', '诗', 'shi', '', NULL, '閨月 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51d9e4e1-1518-447f-8b42-c70be52a22e7', '閨怨', '閨怨', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["戚戚彼何人，明眸利於月。","啼妝曉不乾，素面凝香雪。","良人去淄右，鏡破金簪折。","空藏蘭蕙心，不忍琴中說。"]', '["戚戚彼何人，明眸利於月。","啼妝晓不乾，素面凝香雪。","良人去淄右，镜破金簪折。","空藏蘭蕙心，不忍琴中说。"]', '诗', 'shi', '', NULL, '閨怨 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47f0cad8-c295-4540-a348-ecf0c16ae7a9', '上春詞', '上春词', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["曈曨赫日東方來，禁城煙煖蒸青苔。","金樓美人花屏開，晨妝未罷車聲催。","幽蘭報暖紫芽折，夭花愁豔蝶飛迴。","五陵年少惜花落，酒濃歌極翻如哀。","四時輪環終又始，百年不見南山摧。","遊人陌上騎生塵，顏子門前吹死灰。"]', '["曈曨赫日东方来，禁城煙煖蒸青苔。","金楼美人花屏开，晨妝未罷车声催。","幽蘭報暖紫芽折，夭花愁豔蝶飞迴。","五陵年少惜花落，酒濃歌極翻如哀。","四时輪环終又始，百年不见南山摧。","游人陌上騎生塵，顏子门前吹死灰。"]', '诗', 'shi', '', NULL, '上春詞 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87f9de92-ca54-419c-8482-94a3446f158b', '擣練篇', '擣練篇', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["月華吐豔明燭燭，青樓婦唱擣衣曲。","白袷絲光織魚目，菱花綬帶鴛鴦簇。","臨風縹緲疊秋雪，月下丁冬擣寒玉。","樓蘭欲寄在何鄉，憑人與繫征鴻足。"]', '["月华吐豔明燭燭，青楼婦唱擣衣曲。","白袷絲光织鱼目，菱花綬带鴛鴦簇。","臨风縹緲叠秋雪，月下丁冬擣寒玉。","楼蘭欲寄在何乡，憑人與繫征鴻足。"]', '诗', 'shi', '', NULL, '擣練篇 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37f1b5c3-c60c-4a27-8d83-473822447da3', '雜體聯錦', '杂體聯錦', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["攜手重攜手，夾江金線柳。","江上柳能長，行人戀尊酒。","尊酒意何深，爲郎歌玉簪。","玉簪聲斷續，鈿軸鳴雙轂。","雙轂去何方，隔江春樹綠。","樹綠酒旗高，淚痕沾繡袍。","袍縫紫鵝濕，重持金錯刀。","錯刀何燦爛，使我腸千斷。","腸斷欲何言，簾動真珠繁。","真珠綴秋露，秋露沾金盤。","金盤湛瓊液，仙子無歸跡。","無跡又無言，海煙空寂寂。","寂寂古城道，馬嘶芳岸草。","岸草接長堤，長堤人解攜。","解攜忽已久，緬邈空回首。","回首隔天河，恨唱蓮塘歌。","蓮塘在何許，日暮西山雨。"]', '["携手重携手，夾江金線柳。","江上柳能长，行人戀尊酒。","尊酒意何深，爲郎歌玉簪。","玉簪声斷續，鈿軸鳴雙轂。","雙轂去何方，隔江春樹綠。","樹綠酒旗高，泪痕沾繡袍。","袍縫紫鵝濕，重持金錯刀。","錯刀何燦爛，使我腸千斷。","腸斷欲何言，簾动真珠繁。","真珠綴秋露，秋露沾金盤。","金盤湛瓊液，仙子無归跡。","無跡又無言，海煙空寂寂。","寂寂古城道，马嘶芳岸草。","岸草接长堤，长堤人解携。","解携忽已久，緬邈空回首。","回首隔天河，恨唱蓮塘歌。","蓮塘在何許，日暮西山雨。"]', '诗', 'shi', '', NULL, '雜體聯錦 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f094838-1355-47c9-8c38-8698d7c5527a', '長安春', '长安春', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["長安二月多香塵，六街車馬聲轔轔。","家家樓上如花人，千枝萬枝紅豔新。","簾間笑語自相問，何人占得長安春。","長安春色本無主，古來盡屬紅樓女。","如今無奈杏園人，駿馬輕車擁將去。"]', '["长安二月多香塵，六街车马声轔轔。","家家楼上如花人，千枝万枝紅豔新。","簾间笑語自相问，何人占得长安春。","长安春色本無主，古来尽屬紅楼女。","如今無奈杏园人，駿马轻车擁將去。"]', '诗', 'shi', '', NULL, '長安春 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a816c62d-a75f-4648-8cf7-1beb84156246', '撫盈歌', '撫盈歌', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["鳳縠兮鴛綃，霞疏兮綺寮。","玉庭兮春晝，金屋兮秋宵。","愁瞳兮月皎，笑頰兮花嬌。","羅輕兮濃麝，室煖兮香椒。","鑾輿去兮蕭屑，七絲斷兮泬寥。","主父臥兮漳水，君王幸兮雲軺。","鉛華窅窈兮穠姿，棠公肸蠁兮靡依。","翠華長逝兮莫追，晏相望門兮空悲。"]', '["鳳縠兮鴛綃，霞疏兮綺寮。","玉庭兮春晝，金屋兮秋宵。","愁瞳兮月皎，笑頰兮花嬌。","羅轻兮濃麝，室煖兮香椒。","鑾輿去兮蕭屑，七絲斷兮泬寥。","主父臥兮漳水，君王幸兮云軺。","鉛华窅窈兮穠姿，棠公肸蠁兮靡依。","翠华长逝兮莫追，晏相望门兮空悲。"]', '诗', 'shi', '', NULL, '撫盈歌 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2ce27cb-87c1-4ba9-858b-d553c678d124', '贈峨嵋山彈琴李處士', '贈峨嵋山彈琴李处士', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["峨嵋山下能琴客，似醉似狂人不測。","何須見我眼偏青，未見我身頭已白。","茫茫四海本無家，一片愁雲颺秋碧。","壺中醉臥日月明，世上長遊天地窄。","晉朝叔夜舊相知，蜀郡文君小來識。","後生常建彼何人，贈我篇章苦雕刻。","名卿名相盡知音，遇酒遇琴無間隔。","如今世亂獨翛然，天外鴻飛招不得。","余今正泣楊朱淚，八月邊城風刮地。","霓旌絳斾忽相尋，爲我尊前橫綠綺。","一彈猛雨隨手來，再彈白雪連天起。","淒淒清清松上風，咽咽幽幽隴頭水。","吟蜂遶樹去不來，別鶴引雛飛又止。","錦麟不動惟側頭，白馬仰聽空豎耳。","廣陵故事無人知，古人不說今人疑。","子期子野俱不見，烏啼鬼哭空傷悲。","坐中詞客悄無語，簾外月華庭欲午。","爲君吟作聽琴歌，爲我留名係仙譜。"]', '["峨嵋山下能琴客，似醉似狂人不測。","何須见我眼偏青，未见我身头已白。","茫茫四海本無家，一片愁云颺秋碧。","壺中醉臥日月明，世上长游天地窄。","晉朝叔夜旧相知，蜀郡文君小来識。","後生常建彼何人，贈我篇章苦雕刻。","名卿名相尽知音，遇酒遇琴無间隔。","如今世亂独翛然，天外鴻飞招不得。","余今正泣楊朱泪，八月邊城风刮地。","霓旌絳斾忽相尋，爲我尊前橫綠綺。","一彈猛雨隨手来，再彈白雪連天起。","淒淒清清松上风，咽咽幽幽隴头水。","吟蜂遶樹去不来，別鹤引雛飞又止。","錦麟不动惟側头，白马仰听空豎耳。","廣陵故事無人知，古人不说今人疑。","子期子野俱不见，烏啼鬼哭空傷悲。","坐中词客悄無語，簾外月华庭欲午。","爲君吟作听琴歌，爲我留名係仙譜。"]', '诗', 'shi', '', NULL, '贈峨嵋山彈琴李處士 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02bfa763-8e00-4356-a31a-4ba3a0b12254', '江臯贈別', '江臯贈別', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["金管多情恨解攜，一聲歌罷客如泥。","江亭繫馬綠楊短，野岸維舟春草齊。","帝子夢魂煙水闊，謝公詩思碧雲低。","風前不用頻揮手，我有家山白日西。"]', '["金管多情恨解携，一声歌罷客如泥。","江亭繫马綠楊短，野岸維舟春草齊。","帝子梦魂煙水闊，謝公诗思碧云低。","风前不用頻揮手，我有家山白日西。"]', '诗', 'shi', '', NULL, '江臯贈別 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0acefef6-61ee-4a97-8b3c-0209486de6ff', '南陽小將張彥硤口鎮稅人場射虎歌', '南陽小將張彥硤口鎮稅人場射虎歌', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["海內昔年狎太平，橫目穰穰何崢嶸。","天生天殺豈天怒，忍使朝朝餵猛虎。","關東驛路多丘荒，行人最忌稅人場。","張彥雄特制殘暴，見之叱起如叱羊。","鳴弦霹靂越幽阻，往往依林猶抵拒。","草際旋看委錦茵，腰間不更抽白羽。","老饕已斃衆雛恐，童稚揶揄皆自勇。","忠良效順勢亦然，一劒猜狂敢輕動。","有文有武方爲國，不是英雄伏不得。","試徵張彥作將軍，幾箇將軍願策勳。"]', '["海內昔年狎太平，橫目穰穰何崢嶸。","天生天殺豈天怒，忍使朝朝餵猛虎。","关东驛路多丘荒，行人最忌稅人場。","張彥雄特制殘暴，见之叱起如叱羊。","鳴弦霹靂越幽阻，往往依林猶抵拒。","草際旋看委錦茵，腰间不更抽白羽。","老饕已斃衆雛恐，童稚揶揄皆自勇。","忠良效順勢亦然，一劒猜狂敢轻动。","有文有武方爲国，不是英雄伏不得。","試徵張彥作將軍，幾箇將軍願策勳。"]', '诗', 'shi', '', NULL, '南陽小將張彥硤口鎮稅人場射虎歌 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2731c0f4-aaa0-4647-8cfa-27e1cd2fa588', '下邽感舊', '下邽感旧', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["昔爲童稚不知愁，竹馬閑乘遶縣遊。","曾爲看花偷出郭，也因逃學暫登樓。","招他邑客來還醉，儳得先生去始休。","今日故人何處問，夕陽衰草盡荒丘。"]', '["昔爲童稚不知愁，竹马闲乘遶縣游。","曾爲看花偷出郭，也因逃学暫登楼。","招他邑客来還醉，儳得先生去始休。","今日故人何处问，夕陽衰草尽荒丘。"]', '诗', 'shi', '', NULL, '下邽感舊 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c956a22-3724-46ee-ab11-dabaf0b3e779', '塗次逢李氏兄弟感舊', '塗次逢李氏兄弟感旧', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["御溝四面朱門宅，記得當時好弟兄。","曉傍柳陰騎竹馬，夜隈燈影弄先生。","巡街趂蝶衣裳破，上屋探雛手脚輕。","今日相逢俱老大，憂家憂國盡公卿。"]', '["御溝四面朱门宅，記得當时好弟兄。","晓傍柳陰騎竹马，夜隈灯影弄先生。","巡街趂蝶衣裳破，上屋探雛手脚轻。","今日相逢俱老大，憂家憂国尽公卿。"]', '诗', 'shi', '', NULL, '塗次逢李氏兄弟感舊 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4adaa050-5773-4ccc-b353-0df7198a7f3f', '龍潭', '龙潭', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["激石懸流雪滿灣，九龍潛處野雲閑。","欲行甘雨四天下，且隱澄潭一頃間。","浪引浮槎依北岸，波分晚日見東山。","垂髯儻遇穆王駕，閬苑周流應未還。"]', '["激石懸流雪满灣，九龙潛处野云闲。","欲行甘雨四天下，且隐澄潭一頃间。","浪引浮槎依北岸，波分晚日见东山。","垂髯儻遇穆王駕，閬苑周流應未還。"]', '诗', 'shi', '', NULL, '龍潭 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f77cc56b-83a4-45e6-b39c-a721f7f69cba', '江上別李秀才', '江上別李秀才', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["前年相送灞陵春，今日天涯各避秦。","莫向尊前惜沈醉，與君俱是異鄉人。"]', '["前年相送灞陵春，今日天涯各避秦。","莫向尊前惜沈醉，與君俱是異乡人。"]', '诗', 'shi', '', NULL, '江上別李秀才 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9dfab20e-5fa7-4034-9eee-4d3c382850f3', '句', '句', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["印將金鏁鏁，簾用玉鉤鉤。","不隨妖豔開，獨媚玄冥節。","豈是爲窮常見隔，只應嫌酒不相過。"]', '["印將金鏁鏁，簾用玉鉤鉤。","不隨妖豔开，独媚玄冥節。","豈是爲窮常见隔，只應嫌酒不相過。"]', '诗', 'shi', '', NULL, '句 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0d8b5f9-b29c-4ad6-b22b-91721f742a6d', '擬塞外征行', '擬塞外征行', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["寇騎滿雞田，都護欲臨邊。","青泥方絕漠，懷劍始辭燕。","旌旗挂龍虎，壯士募鷹鸇。","長城威十萬，高嶺奮三千。","行行向馬邑，去去指祁連。","鼓聲遙赤塞，兵氣遠衝天。","對陣雲初上，臨城月始懸。","風驚烽易滅，沙暗馬難前。","恩重恆思報，勞心屢損年。","微功一可立，身輕不自憐。"]', '["寇騎满雞田，都護欲臨邊。","青泥方絕漠，懷劍始辞燕。","旌旗挂龙虎，壯士募鷹鸇。","长城威十万，高嶺奮三千。","行行向马邑，去去指祁連。","鼓声遙赤塞，兵氣远衝天。","对陣云初上，臨城月始懸。","风驚烽易滅，沙暗马难前。","恩重恆思報，勞心屢損年。","微功一可立，身轻不自怜。"]', '诗', 'shi', '', NULL, '擬塞外征行 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f4dc728-d7b7-4567-913c-e862f7270a2d', '蘆葦', '蘆葦', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["高士想江湖，湖閑庭植蘆。","清風時有至，綠竹興何殊。","嫩喜日光薄，疎憂雨點麤。","驚蛙跳得過，鬬雀裊如無。","未織巴籬護，幾擡邛竹扶。","惹煙輕弱柳，蘸水漱清蒲。","溉灌情偏重，琴樽賞不孤。","穿花思釣叟，吹葉少羌雛。","寒色暮天映，秋聲遠籟俱。","郎吟應有趣，瀟灑十餘株。"]', '["高士想江湖，湖闲庭植蘆。","清风时有至，綠竹兴何殊。","嫩喜日光薄，疎憂雨点麤。","驚蛙跳得過，鬬雀裊如無。","未织巴籬護，幾擡邛竹扶。","惹煙轻弱柳，蘸水漱清蒲。","溉灌情偏重，琴樽賞不孤。","穿花思釣叟，吹葉少羌雛。","寒色暮天映，秋声远籟俱。","郎吟應有趣，瀟灑十餘株。"]', '诗', 'shi', '', NULL, '蘆葦 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e8be69d-0088-4692-89fa-3d18edd76c4e', '田舍曲', '田舍曲', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["古今利名路，只在儂門前。","至老不離家，一生常晏眠。","牛羊晚自歸，兒童戲野田。","豈思封侯貴，唯只待豐年。","征賦豈辭苦，但願時官賢。","時官苟貪濁，田舍生憂煎。"]', '["古今利名路，只在儂门前。","至老不離家，一生常晏眠。","牛羊晚自归，兒童戲野田。","豈思封侯貴，唯只待豐年。","征賦豈辞苦，但願时官賢。","时官苟貪濁，田舍生憂煎。"]', '诗', 'shi', '', NULL, '田舍曲 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32f0efe9-8688-4b01-b1a0-4d636f5e76f2', '妾薄命', '妾薄命', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["薄命頭欲白，頻年嫁不成。","秦娥未十五，昨夜事公卿。","豈有機杼力，空傳歌舞名。","妾專脩婦德，媒氏却相輕。"]', '["薄命头欲白，頻年嫁不成。","秦娥未十五，昨夜事公卿。","豈有機杼力，空傳歌舞名。","妾專脩婦德，媒氏却相轻。"]', '诗', 'shi', '', NULL, '妾薄命 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1199ea6-7e22-4fde-954d-5e319dbaea19', '湘妃怨', '湘妃怨', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["舜欲省蠻陬，南巡非逸遊。","九江沉白日，二女泣滄洲。","目極楚雲斷，恨深湘水流。","至今聞鼓瑟，咽絕不勝愁。"]', '["舜欲省蠻陬，南巡非逸游。","九江沉白日，二女泣滄洲。","目極楚云斷，恨深湘水流。","至今闻鼓瑟，咽絕不勝愁。"]', '诗', 'shi', '', NULL, '湘妃怨 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98a00e95-2867-40a4-80b9-9a3e5f33cdb4', '長門怨二首 一', '长门怨二首 一', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["寂寞故宮春，殘燈曉尚存。","從來非妾過，偶爾失君恩。","花落傷容鬢，鶯啼驚夢魂。","翠華如可待，應免老長門。"]', '["寂寞故宮春，殘灯晓尚存。","從来非妾過，偶爾失君恩。","花落傷容鬢，鶯啼驚梦魂。","翠华如可待，應免老长门。"]', '诗', 'shi', '', NULL, '長門怨二首 一 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61930a0e-bcf7-40db-9305-da177f83b988', '長門怨二首 二', '长门怨二首 二', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["葉落長門靜，苔生永巷幽。","相思對明月，獨坐向空樓。","鑾駕迷終轉，蛾眉老自愁。","昭陽歌舞伴，此夕未知秋。"]', '["葉落长门静，苔生永巷幽。","相思对明月，独坐向空楼。","鑾駕迷終轉，蛾眉老自愁。","昭陽歌舞伴，此夕未知秋。"]', '诗', 'shi', '', NULL, '長門怨二首 二 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0144770-0ab5-41f8-a8bf-160c92093ad6', '有所思', '有所思', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["芙蓉出水時，偶爾便分離。","自此無因見，長教挂所思。","殘春不入夢，芳信欲傳誰。","寂寞秋堂下，空吟小謝詩。"]', '["芙蓉出水时，偶爾便分離。","自此無因见，长教挂所思。","殘春不入梦，芳信欲傳誰。","寂寞秋堂下，空吟小謝诗。"]', '诗', 'shi', '', NULL, '有所思 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1219e15-2f83-436c-8d1a-0dc2329a016b', '短歌', '短歌', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["物候來相續，新蟬送晚鶯。","百年休倚賴，一夢甚分明。","金鼎神仙隱，銅壺晝夜傾。","不如早立德，萬古有其名。"]', '["物候来相續，新蟬送晚鶯。","百年休倚賴，一梦甚分明。","金鼎神仙隐，銅壺晝夜傾。","不如早立德，万古有其名。"]', '诗', 'shi', '', NULL, '短歌 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07155ffa-86ee-46df-8fac-d864bb4362b4', '御溝水', '御溝水', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["一帶御溝水，綠槐相蔭清。","此中涵帝澤，無處濯塵纓。","鳥道來雖險，龍池到自平。","朝宗本心切，願向急流傾。"]', '["一带御溝水，綠槐相蔭清。","此中涵帝澤，無处濯塵纓。","鸟道来雖險，龙池到自平。","朝宗本心切，願向急流傾。"]', '诗', 'shi', '', NULL, '御溝水 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('990a9e14-8b30-457c-b9e6-72615f7270ee', '少年行二首 一', '少年行二首 一', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["遊讌不知厭，杜陵狂少年。","花時輕暖酒，春服薄裝綿。","戲馬上林苑，鬬雞寒食天。","魯儒甘被笑，對策鬢皤然。"]', '["游讌不知厭，杜陵狂少年。","花时轻暖酒，春服薄裝綿。","戲马上林苑，鬬雞寒食天。","魯儒甘被笑，对策鬢皤然。"]', '诗', 'shi', '', NULL, '少年行二首 一 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('651f7be3-023a-4ec8-95ef-007e7b754566', '少年行二首 二', '少年行二首 二', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["弱冠投邊急，驅兵夜渡河。","追奔鐵馬走，殺虜寶刀訛。","威靜黑山路，氣含清海波。","常聞爲突騎，天子賜長戈。"]', '["弱冠投邊急，驱兵夜渡河。","追奔鐵马走，殺虜寶刀訛。","威静黑山路，氣含清海波。","常闻爲突騎，天子賜长戈。"]', '诗', 'shi', '', NULL, '少年行二首 二 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffb281d2-cd57-4383-91fb-41ddc1849010', '塞上曲', '塞上曲', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["歲歲但防虜，西征早晚休。","匈奴不繫頸，漢將但封侯。","夕照低烽火，寒笳咽戍樓。","燕然山上字，男子見須羞。"]', '["歲歲但防虜，西征早晚休。","匈奴不繫頸，漢將但封侯。","夕照低烽火，寒笳咽戍楼。","燕然山上字，男子见須羞。"]', '诗', 'shi', '', NULL, '塞上曲 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea516347-32e6-4fa7-b33a-2d4105558f49', '長安道', '长安道', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["曉鼓人已行，暮鼓人未息。","梯航萬國來，爭先貢金帛。","不問賢與愚，但論官與職。","如何貧書生，只獻安邊策。"]', '["晓鼓人已行，暮鼓人未息。","梯航万国来，爭先貢金帛。","不问賢與愚，但論官與職。","如何貧书生，只獻安邊策。"]', '诗', 'shi', '', NULL, '長安道 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d5d0008-954b-42a6-b6ab-fb82135159b4', '洛陽道', '洛陽道', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["喧喧洛陽路，奔走爭先步。","唯恐著鞭遲，誰能更迴顧。","覆車雖在前，潤屋何曾懼。","賢哉只二疏，東門掛冠去。"]', '["喧喧洛陽路，奔走爭先步。","唯恐著鞭遲，誰能更迴顧。","覆车雖在前，潤屋何曾懼。","賢哉只二疏，东门掛冠去。"]', '诗', 'shi', '', NULL, '洛陽道 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('223f6361-8149-43bc-aa51-8db381e5ed6a', '度關山', '度关山', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["只領千餘騎，長驅磧邑間。","雲州多警急，雪夜度關山。","石響鈴聲遠，天寒弓力慳。","秦樓休悵望，不日凱歌還。"]', '["只領千餘騎，长驱磧邑间。","云州多警急，雪夜度关山。","石响鈴声远，天寒弓力慳。","秦楼休悵望，不日凱歌還。"]', '诗', 'shi', '', NULL, '度關山 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb38dfd8-614d-447a-b8a5-47654f379ab3', '出自薊北門行', '出自薊北门行', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["薊北連極塞，塞色晝冥冥。","戰地骸骨滿，長時風雨腥。","沙河留不定，春草凍難青。","萬戶封侯者，何謀靜虜庭。"]', '["薊北連極塞，塞色晝冥冥。","戰地骸骨满，长时风雨腥。","沙河留不定，春草凍难青。","万戶封侯者，何謀静虜庭。"]', '诗', 'shi', '', NULL, '出自薊北門行 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c02ee7a-e1ec-4af7-8ef3-d10c0bfc1b93', '從軍行', '從軍行', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["從軍朔方久，未省用干戈。","秪以恩信及，自然戎虜和。","邊聲動白草，燒色入枯河。","每度因看獵，令人勇氣多。"]', '["從軍朔方久，未省用干戈。","秪以恩信及，自然戎虜和。","邊声动白草，燒色入枯河。","每度因看獵，令人勇氣多。"]', '诗', 'shi', '', NULL, '從軍行 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('666fbd5e-7376-4efb-b43f-1d309d06e4d3', '古悔從軍行', '古悔從軍行', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["憶昔仗孤劍，十年從武威。","論兵親玉帳，逐虜過金微。","隴水秋先凍，關雲寒不飛。","辛懃功業在，麟閣志猶違。"]', '["憶昔仗孤劍，十年從武威。","論兵親玉帳，逐虜過金微。","隴水秋先凍，关云寒不飞。","辛懃功業在，麟閣志猶違。"]', '诗', 'shi', '', NULL, '古悔從軍行 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4eacf00c-af1c-4eb9-992f-deb062a6e2f6', '胡笳曲', '胡笳曲', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["隴底悲笳引，隴頭鳴北風。","一輪霜月落，萬里塞天空。","戍卒淚應盡，胡兒哭未終。","爭教班定遠，不念玉關中。"]', '["隴底悲笳引，隴头鳴北风。","一輪霜月落，万里塞天空。","戍卒泪應尽，胡兒哭未終。","爭教班定远，不念玉关中。"]', '诗', 'shi', '', NULL, '胡笳曲 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc7c6f0f-57ee-4f63-bfaf-a974ee3ad0ea', '入塞', '入塞', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["玉殿論兵事，君王詔出征。","新除羽林將，曾破月支兵。","慣歷塞垣險，能分部落情。","從今一戰勝，不使虜塵生。"]', '["玉殿論兵事，君王詔出征。","新除羽林將，曾破月支兵。","慣歷塞垣險，能分部落情。","從今一戰勝，不使虜塵生。"]', '诗', 'shi', '', NULL, '入塞 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('458d9efc-e91e-4d2a-9fee-d56b271b6728', '遊僊', '游僊', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["我家三島上，洞戶眺波濤。","醉背雲屏臥，誰知海日高。","露香紅玉樹，風綻碧蟠桃。","悔與仙子別，思歸夢釣鼇。"]', '["我家三島上，洞戶眺波濤。","醉背云屏臥，誰知海日高。","露香紅玉樹，风綻碧蟠桃。","悔與仙子別，思归梦釣鼇。"]', '诗', 'shi', '', NULL, '遊僊 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38a52265-adaf-46e2-8cf8-0baa3d40cfd9', '歌', '歌', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["誰唱關西曲，寂寞夜景深。","一聲長在耳，萬恨重經心。","調古清風起，曲終涼月沉。","却應筵上客，未必是知音。"]', '["誰唱关西曲，寂寞夜景深。","一声长在耳，万恨重經心。","調古清风起，曲終涼月沉。","却應筵上客，未必是知音。"]', '诗', 'shi', '', NULL, '歌 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbed4d44-b9ab-41db-a5ff-c335969a3c42', '經故洛城', '經故洛城', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["卜世何久遠，由來仰聖明。","山河徒自壯，周召不長生。","幾主任姦諂，諸侯各戰爭。","但餘崩壘在，今古共傷情。"]', '["卜世何久远，由来仰聖明。","山河徒自壯，周召不长生。","幾主任姦諂，諸侯各戰爭。","但餘崩壘在，今古共傷情。"]', '诗', 'shi', '', NULL, '經故洛城 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52a1875d-293c-4cbe-971b-b372ecfa9230', '金陵', '金陵', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["六代江山在，繁華古帝都。","亂來城不守，戰後地多蕪。","寒日隨潮落，歸帆與鳥孤。","興亡多少事，回首一長吁。"]', '["六代江山在，繁华古帝都。","亂来城不守，戰後地多蕪。","寒日隨潮落，归帆與鸟孤。","兴亡多少事，回首一长吁。"]', '诗', 'shi', '', NULL, '金陵 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5dd9ffd8-e4da-4514-8618-10b2ccf34d3b', '金陵懷古', '金陵懷古', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["恃險不種德，興亡歎數窮。","石城幾換主，天塹謾連空。","御路疊民塚，臺基聚牧童。","折碑猶有字，多記晉英雄。"]', '["恃險不種德，兴亡歎數窮。","石城幾換主，天塹謾連空。","御路叠民塚，台基聚牧童。","折碑猶有字，多記晉英雄。"]', '诗', 'shi', '', NULL, '金陵懷古 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1a79e67-9a12-4829-a7f0-4d87fbff07c7', '商山', '商山', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["商山名利路，夜亦有人行。","四皓臥雲處，千秋疊蘚生。","晝燒籠澗黑，殘雪隔林明。","我待酬恩了，來聽水石聲。"]', '["商山名利路，夜亦有人行。","四皓臥云处，千秋叠蘚生。","晝燒籠澗黑，殘雪隔林明。","我待酬恩了，来听水石声。"]', '诗', 'shi', '', NULL, '商山 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ae3ae53-6f0c-4e0d-a387-9c6b0bb921ac', '廬山', '廬山', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["嶽立鎮南楚，雄名天下聞。","五峰高閡日，九疊翠連雲。","夏谷雪猶在，陰巖晝不分。","唯應嵩與華，清峻得爲羣。"]', '["嶽立鎮南楚，雄名天下闻。","五峰高閡日，九叠翠連云。","夏谷雪猶在，陰巖晝不分。","唯應嵩與华，清峻得爲羣。"]', '诗', 'shi', '', NULL, '廬山 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('719aca7b-b7e4-4c71-8304-fed39379519f', '終南山', '終南山', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["終朝異五岳，列翠滿長安。","地去搜揚近，人謀隱遁難。","水穿諸苑過，雪照一城寒。","爲問紅塵裏，誰同駐馬看。"]', '["終朝異五岳，列翠满长安。","地去搜揚近，人謀隐遁难。","水穿諸苑過，雪照一城寒。","爲问紅塵裏，誰同駐马看。"]', '诗', 'shi', '', NULL, '終南山 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b1a7cc8-2849-4347-af5f-932938d300c3', '寄鄭谷', '寄鄭谷', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["五百首新詩，緘封寄去時。","秪憑夫子鑒，不要俗人知。","火鼠重收布，冰蠶乍吐絲。","直須天上手，裁作領巾披。"]', '["五百首新诗，緘封寄去时。","秪憑夫子鑒，不要俗人知。","火鼠重收布，冰蠶乍吐絲。","直須天上手，裁作領巾披。"]', '诗', 'shi', '', NULL, '寄鄭谷 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c966095-35dd-452a-8496-dd3c6b3e8213', '題嚴陵釣臺', '題嚴陵釣台', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["山色四時碧，溪聲七里清。","嚴陵愛此景，下視漢公卿。","垂釣月初上，放歌風正輕。","應憐渭濱叟，匡國正論兵。"]', '["山色四时碧，溪声七里清。","嚴陵愛此景，下視漢公卿。","垂釣月初上，放歌风正轻。","應怜渭濱叟，匡国正論兵。"]', '诗', 'shi', '', NULL, '題嚴陵釣臺 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e880fca-acc1-4bcb-a650-71516cec4510', '曉泊漢陽渡', '晓泊漢陽渡', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["落月臨古渡，武昌城未開。","殘燈明市井，曉色辨樓臺。","雲自蒼梧去，水從嶓冢來。","芳洲號鸚鵡，用記禰生才。"]', '["落月臨古渡，武昌城未开。","殘灯明市井，晓色辨楼台。","云自蒼梧去，水從嶓冢来。","芳洲號鸚鵡，用記禰生才。"]', '诗', 'shi', '', NULL, '曉泊漢陽渡 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67fe5088-387a-4eab-8db4-230688cb4291', '隨計', '隨計', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["徒步隨計吏，辛勤鬢易凋。","歸期無定日，鄉思羨迴潮。","冒雨投前驛，侵星過斷橋。","何堪穆陵路，霜葉更瀟瀟。"]', '["徒步隨計吏，辛勤鬢易凋。","归期無定日，乡思羨迴潮。","冒雨投前驛，侵星過斷橋。","何堪穆陵路，霜葉更瀟瀟。"]', '诗', 'shi', '', NULL, '隨計 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e356f4e-0997-4f89-8cd3-960d80c3faaa', '白牡丹', '白牡丹', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["穀雨洗纖素，裁爲白牡丹。","異香開玉合，輕粉泥銀盤。","曉貯露華濕，宵傾月魄寒。","家人淡粧罷，無語倚朱欄。"]', '["穀雨洗纖素，裁爲白牡丹。","異香开玉合，轻粉泥銀盤。","晓貯露华濕，宵傾月魄寒。","家人淡粧罷，無語倚朱欄。"]', '诗', 'shi', '', NULL, '白牡丹 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aef21a8f-1a5a-48e3-be6c-5be80d024a88', '述松', '述松', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["遠谷呈材幹，何由入棟粱。","歲寒虛勝竹，功績不如桑。","秋露落松子，春深裛嫩黃。","雖蒙匠者顧，樵採日難防。"]', '["远谷呈材幹，何由入棟粱。","歲寒虛勝竹，功績不如桑。","秋露落松子，春深裛嫩黄。","雖蒙匠者顧，樵採日难防。"]', '诗', 'shi', '', NULL, '述松 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e9fe395-6ef2-4708-b766-ee4b4e662667', '宮池產瑞蓮', '宮池產瑞蓮', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["雨露及萬物，嘉祥有瑞蓮。","香飄雞樹近，榮占鳳池先。","聖日臨雙麗，恩波照並妍。","願同指佞草，生向帝堯前。"]', '["雨露及万物，嘉祥有瑞蓮。","香飄雞樹近，榮占鳳池先。","聖日臨雙丽，恩波照並妍。","願同指佞草，生向帝堯前。"]', '诗', 'shi', '', NULL, '宮池產瑞蓮 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('261b1934-825b-473c-9822-8e51169b3371', '送友人南歸', '送友人南归', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["南國菖蒲老，知君憶釣船。","離京近殘暑，歸路有新蟬。","峴首白雲起，洞庭秋月懸。","若教吟興足，西笑是何年。"]', '["南国菖蒲老，知君憶釣船。","離京近殘暑，归路有新蟬。","峴首白云起，洞庭秋月懸。","若教吟兴足，西笑是何年。"]', '诗', 'shi', '', NULL, '送友人南歸 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4145d5a4-a43d-4347-b4cb-811e72f39864', '送馬明府歸山', '送马明府归山', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["辭秩入匡廬，重脩靖節居。","免遭黑綬束，不與白雲疎。","送吏各獻酒，羣兒自擔書。","到時看瀑布，爲我謝清虛。"]', '["辞秩入匡廬，重脩靖節居。","免遭黑綬束，不與白云疎。","送吏各獻酒，羣兒自擔书。","到时看瀑布，爲我謝清虛。"]', '诗', 'shi', '', NULL, '送馬明府歸山 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12e84743-0225-4aa8-8e79-b59b78dab05b', '送韓從事歸本道', '送韓從事归本道', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["獻捷靈州倅，歸時寵拜新。","論邊多稱旨，許國誓亡身。","馬渴黃河凍，雁回青塚春。","到蕃唯促戰，應不肯和親。"]', '["獻捷靈州倅，归时寵拜新。","論邊多稱旨，許国誓亡身。","马渴黄河凍，雁回青塚春。","到蕃唯促戰，應不肯和親。"]', '诗', 'shi', '', NULL, '送韓從事歸本道 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71a985ba-f0e8-4f00-a512-67b60623362f', '秋日旅懷寄右省鄭拾遺', '秋日旅懷寄右省鄭拾遺', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["永夕愁不寐，草蟲喧客庭。","半窗分曉月，當枕落殘星。","鬢髮遊梁白，家山近越青。","知音在諫省，苦調有誰聽。"]', '["永夕愁不寐，草蟲喧客庭。","半窗分晓月，當枕落殘星。","鬢髮游梁白，家山近越青。","知音在諫省，苦調有誰听。"]', '诗', 'shi', '', NULL, '秋日旅懷寄右省鄭拾遺 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a78a3e4b-66b1-448c-86b7-561757e79769', '贈劉凝評事', '贈劉凝評事', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["棘寺官初罷，梁園靜掩扉。","春深顏子巷，花映老萊衣。","談史曾無滯，攻書已造微。","即膺新寵命，稱慶向庭闈。"]', '["棘寺官初罷，梁园静掩扉。","春深顏子巷，花映老萊衣。","談史曾無滯，攻书已造微。","即膺新寵命，稱慶向庭闈。"]', '诗', 'shi', '', NULL, '贈劉凝評事 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f517805a-e85f-4db5-a3f1-6268926da391', '憶張處士', '憶張处士', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["天台張處士，詩句造玄微。","古藥知音少，名言與俗違。","山風入松徑，海月上巖扉。","畢世唯高臥，無人說是非。"]', '["天台張处士，诗句造玄微。","古藥知音少，名言與俗違。","山风入松徑，海月上巖扉。","畢世唯高臥，無人说是非。"]', '诗', 'shi', '', NULL, '憶張處士 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a400727a-d4ca-41cf-bd11-568edd8348c9', '雲居長老', '云居长老', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["巘路躡雲上，來參出世僧。","松高半巖雪，竹覆一溪冰。","不說有爲法，非傳無盡燈。","了然方寸內，應秪見南能。"]', '["巘路躡云上，来參出世僧。","松高半巖雪，竹覆一溪冰。","不说有爲法，非傳無尽灯。","了然方寸內，應秪见南能。"]', '诗', 'shi', '', NULL, '雲居長老 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac19d50b-93ae-40bb-b41f-067f6722fad8', '洗竹', '洗竹', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["道院竹繁教畧洗，鳴琴酌酒看扶疎。","不圖結實來雙鳳，且要長竿釣巨魚。","錦籜裁冠添散逸，玉芽脩饌稱清虛。","有時記得三天事，自向琅玕節下書。"]', '["道院竹繁教畧洗，鳴琴酌酒看扶疎。","不圖結實来雙鳳，且要长竿釣巨鱼。","錦籜裁冠添散逸，玉芽脩饌稱清虛。","有时記得三天事，自向琅玕節下书。"]', '诗', 'shi', '', NULL, '洗竹 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96b981e6-2ec3-41b4-89d2-d6999cff08ca', '庾樓曉望', '庾楼晓望', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["獨凭朱檻亦凌晨，山色初明水色新。","竹霧曉籠銜嶺月，蘋風暖送過江春。","子城陰處猶殘雪，衙鼓聲前未有塵。","三百年來庾樓上，曾經多少望鄉人。"]', '["独凭朱檻亦凌晨，山色初明水色新。","竹霧晓籠銜嶺月，蘋风暖送過江春。","子城陰处猶殘雪，衙鼓声前未有塵。","三百年来庾楼上，曾經多少望乡人。"]', '诗', 'shi', '', NULL, '庾樓曉望 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f792611-cd25-48c9-b9ae-222d1f9dded2', '送芮尊師', '送芮尊師', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["石上菖蒲節節靈，先生服食得長生。","早知避世憂身老，近日登山覺步輕。","黃鶴待傳蓬島信，丹書應換蘂宮名。","他年控鯉昇天去，廬岳逋民願從行。"]', '["石上菖蒲節節靈，先生服食得长生。","早知避世憂身老，近日登山覺步轻。","黄鹤待傳蓬島信，丹书應換蘂宮名。","他年控鯉昇天去，廬岳逋民願從行。"]', '诗', 'shi', '', NULL, '送芮尊師 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0683764e-f711-46ba-9ba4-f1f4cde32c99', '折楊柳三首 一', '折楊柳三首 一', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["枝枝交影鎖長門，嫩色曾沾雨露恩。","鳳輦不來春欲盡，空留鶯語到黃昏。"]', '["枝枝交影鎖长门，嫩色曾沾雨露恩。","鳳輦不来春欲尽，空留鶯語到黄昏。"]', '诗', 'shi', '', NULL, '折楊柳三首 一 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c9764a9-234c-46da-b8cb-1ea0aeef5c79', '折楊柳三首 二', '折楊柳三首 二', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["水殿年年占早芳，柔條風裏御爐香。","如今萬乘多巡狩，輦路無陰綠草長。"]', '["水殿年年占早芳，柔條风裏御爐香。","如今万乘多巡狩，輦路無陰綠草长。"]', '诗', 'shi', '', NULL, '折楊柳三首 二 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bafac919-3509-4d91-b700-809818965980', '折楊柳三首 三', '折楊柳三首 三', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["嫩葉初齊不耐寒，風和時拂玉欄干。","征人去日曾攀折，泣雨傷春翠黛殘。"]', '["嫩葉初齊不耐寒，风和时拂玉欄干。","征人去日曾攀折，泣雨傷春翠黛殘。"]', '诗', 'shi', '', NULL, '折楊柳三首 三 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('349419cc-03cc-4404-9985-f6d130dac81a', '遠聞本郡行春到舊山二首 一', '远闻本郡行春到旧山二首 一', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["一身從宦留京邑，五馬遙聞到舊山。","已領煙霞光野徑，深慙老幼候柴關。"]', '["一身從宦留京邑，五马遙闻到旧山。","已領煙霞光野徑，深慙老幼候柴关。"]', '诗', 'shi', '', NULL, '遠聞本郡行春到舊山二首 一 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dac0b35e-cbd5-458f-9364-a50424698c81', '遠聞本郡行春到舊山二首 二', '远闻本郡行春到旧山二首 二', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["清風借響松筠外，畫隼停暉水石間。","定掩溪名在圖傳，共知軒蓋此登攀。"]', '["清风借响松筠外，畫隼停暉水石间。","定掩溪名在圖傳，共知軒蓋此登攀。"]', '诗', 'shi', '', NULL, '遠聞本郡行春到舊山二首 二 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45932bac-3957-4849-ae55-4e2fdaab10c2', '宿新安村步', '宿新安村步', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["淅淅寒流漲淺沙，月明空渚徧蘆花。","離人偶宿孤邨下，永夜聞砧一兩家。"]', '["淅淅寒流漲淺沙，月明空渚徧蘆花。","離人偶宿孤邨下，永夜闻砧一兩家。"]', '诗', 'shi', '', NULL, '宿新安村步 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b30f9b2-7222-4141-9ccb-87b494bf3b02', '僊巖二首 一', '僊巖二首 一', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["白煙晝起丹竈，紅葉秋書篆文。","二十四巖天上，一雞啼破晴雲。"]', '["白煙晝起丹竈，紅葉秋书篆文。","二十四巖天上，一雞啼破晴云。"]', '诗', 'shi', '', NULL, '僊巖二首 一 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f75bf04-5754-4640-a8cc-95b2e77f94fb', '僊巖二首 二', '僊巖二首 二', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["風呼山鬼服役，月照衡薇結花。","江暖客尋瑤草，洞深人嚥丹霞。"]', '["风呼山鬼服役，月照衡薇結花。","江暖客尋瑤草，洞深人嚥丹霞。"]', '诗', 'shi', '', NULL, '僊巖二首 二 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1f1ccf9-4d5a-4ebd-afbc-8bbdafd01f6e', '雨後從陶郎中登庾樓', '雨後從陶郎中登庾楼', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["庾樓逢霽色，夏日欲西曛。","虹截半江雨，風驅大澤雲。","島邊漁艇聚，天畔鳥行分。","此景堪誰畫，文翁請綴文。"]', '["庾楼逢霽色，夏日欲西曛。","虹截半江雨，风驱大澤云。","島邊漁艇聚，天畔鸟行分。","此景堪誰畫，文翁請綴文。"]', '诗', 'shi', '', NULL, '雨後從陶郎中登庾樓 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('369e6a49-eed7-4a28-abc6-6983aff9640d', '九日長安作', '九日长安作', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["無酒泛金菊，登高但憶秋。","歸心隨旅雁，萬里在滄洲。","殘照明天闕，孤砧隔御溝。","誰能思落帽，兩鬢已添愁。"]', '["無酒泛金菊，登高但憶秋。","归心隨旅雁，万里在滄洲。","殘照明天闕，孤砧隔御溝。","誰能思落帽，兩鬢已添愁。"]', '诗', 'shi', '', NULL, '九日長安作 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c88d837-c717-4f35-950d-cb6d4b6bb4b5', '曉發蕭關', '晓發蕭关', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["早發長風裏，邊城曙色間。","數鴻寒背磧，片月落臨關。","隴上明星沒，沙中夜探還。","歸程不可問，幾日到家山。"]', '["早發长风裏，邊城曙色间。","數鴻寒背磧，片月落臨关。","隴上明星沒，沙中夜探還。","归程不可问，幾日到家山。"]', '诗', 'shi', '', NULL, '曉發蕭關 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e640728d-789a-48ac-bfee-3c4744c7114d', '釣臺', '釣台', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["異代有巢許，方知嚴子情。","舊交雖建國，高臥不求榮。","溪鳥寒來浴，汀蘭暖重生。","何顏吟過此，辛苦得浮名。"]', '["異代有巢許，方知嚴子情。","旧交雖建国，高臥不求榮。","溪鸟寒来浴，汀蘭暖重生。","何顏吟過此，辛苦得浮名。"]', '诗', 'shi', '', NULL, '釣臺 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5d27c21-7045-4e33-8a1e-f50862de0e25', '寄天台葉尊師', '寄天台葉尊師', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["師住天台久，長聞過石橋。","晴峯見滄海，深洞徹丹霄。","採藥霞衣濕，煎芝古鼎焦。","念予無俗骨，頻與鶴書招。"]', '["師住天台久，长闻過石橋。","晴峯见滄海，深洞徹丹霄。","採藥霞衣濕，煎芝古鼎焦。","念予無俗骨，頻與鹤书招。"]', '诗', 'shi', '', NULL, '寄天台葉尊師 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2737bdf7-c299-4081-86b2-9b3efbb4e5d2', '御試後進詩', '御試後進诗', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["三時賜食天廚近，再宿偷吟禁漏清。","二十五家齊拔宅，人間已寫上昇名。"]', '["三时賜食天廚近，再宿偷吟禁漏清。","二十五家齊拔宅，人间已寫上昇名。"]', '诗', 'shi', '', NULL, '御試後進詩 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14874375-0d55-47f8-a8a4-c5b4c093fe2d', '春日詠梅花', '春日詠梅花', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["靚妝纔罷粉痕新，迨曉風迴散玉塵。","若遣有情應悵望，已兼殘雪又兼春。"]', '["靚妝纔罷粉痕新，迨晓风迴散玉塵。","若遣有情應悵望，已兼殘雪又兼春。"]', '诗', 'shi', '', NULL, '春日詠梅花 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2226812f-a839-4943-9bcb-aa27fd9461fd', '句', '句', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["太陽雖不照，梁棟每重陰。","白髮未逢媒，對景且裴回。","別酒莫辭今夜醉，故人知我幾時來。","改貫永留鄉黨額，減租重感郡侯恩。"]', '["太陽雖不照，梁棟每重陰。","白髮未逢媒，对景且裴回。","別酒莫辞今夜醉，故人知我幾时来。","改貫永留乡黨額，減租重感郡侯恩。"]', '诗', 'shi', '', NULL, '句 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d66281b-96e0-4f20-a42f-4f1ac5cbd3f6', '登單于臺', '登單于台', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["邊兵春盡迴，獨上單于臺。","白日地中出，黃河天外來。","沙翻痕似浪，風急響疑雷。","欲向陰關度，陰關曉不開。"]', '["邊兵春尽迴，独上單于台。","白日地中出，黄河天外来。","沙翻痕似浪，风急响疑雷。","欲向陰关度，陰关晓不开。"]', '诗', 'shi', '', NULL, '登單于臺 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8883b48a-866a-4c98-86dd-416d3c8821cc', '寄友人', '寄友人', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["戀道欲何如，東西遠索居。","長疑即見面，翻致久無書。","甸麥深藏雉，淮苔淺露魚。","相思不我會，明月幾盈虛。"]', '["戀道欲何如，东西远索居。","长疑即见面，翻致久無书。","甸麦深藏雉，淮苔淺露鱼。","相思不我會，明月幾盈虛。"]', '诗', 'shi', '', NULL, '寄友人 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44b0faa4-22cd-4ba8-9655-2fcc5048c83c', '和崔監丞春遊鄭僕射東園', '和崔監丞春游鄭僕射东园', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["春興隨花盡，東園自養閒。","不離三畝地，似入萬重山。","白鳥穿蘿去，清泉抵石遠。","豈同秦代客，無位隱商山。"]', '["春兴隨花尽，东园自養閒。","不離三畝地，似入万重山。","白鸟穿蘿去，清泉抵石远。","豈同秦代客，無位隐商山。"]', '诗', 'shi', '', NULL, '和崔監丞春遊鄭僕射東園 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1c25888-cffb-417e-9fb4-8f394b3e482f', '過蕭關', '過蕭关', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["出得蕭關北，儒衣不稱身。","隴狐來試客，沙鶻下欺人。","曉戍殘烽火，晴原起獵塵。","邊戎莫相忌，非是霍家親。"]', '["出得蕭关北，儒衣不稱身。","隴狐来試客，沙鶻下欺人。","晓戍殘烽火，晴原起獵塵。","邊戎莫相忌，非是霍家親。"]', '诗', 'shi', '', NULL, '過蕭關 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7ca59d0-69fd-42a0-aa39-15cb3dd55a68', '盆池', '盆池', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["圓內陶化功，外絕衆流通。","選處離松影，穿時減藥叢。","別疑天在地，長對月當空。","每使登門客，煙波入夢中。"]', '["圓內陶化功，外絕衆流通。","選处離松影，穿时減藥叢。","別疑天在地，长对月當空。","每使登门客，煙波入梦中。"]', '诗', 'shi', '', NULL, '盆池 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a9a7b99-f1b2-4fec-9282-74f893c83c8c', '野泉', '野泉', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["遠出白雲中，長年聽不同。","清聲縈亂石，寒色入長空。","挂壁聊成雨，穿林別起風。","溫泉非爾數，源發在深空。"]', '["远出白云中，长年听不同。","清声縈亂石，寒色入长空。","挂壁聊成雨，穿林別起风。","溫泉非爾數，源發在深空。"]', '诗', 'shi', '', NULL, '野泉 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e0d4d39-b290-4fdd-8f26-375de2449827', '送成州牧', '送成州牧', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["清時爲塞郡，自古有儒流。","素望知難愜，新恩且用酬。","犬牙連蜀國，兵額貫秦州。","秪作三年別，誰能聽邑留。"]', '["清时爲塞郡，自古有儒流。","素望知难愜，新恩且用酬。","犬牙連蜀国，兵額貫秦州。","秪作三年別，誰能听邑留。"]', '诗', 'shi', '', NULL, '送成州牧 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4691bf04-5ef8-4553-94ff-5b1a46cc5161', '薊北書事', '薊北书事', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["度磧如經海，茫然但見空。","戍樓承落日，沙塞礙驚蓬。","暑過燕僧出，時平虜客通。","逢人皆上將，誰有定邊功。"]', '["度磧如經海，茫然但见空。","戍楼承落日，沙塞礙驚蓬。","暑過燕僧出，时平虜客通。","逢人皆上將，誰有定邊功。"]', '诗', 'shi', '', NULL, '薊北書事 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bff74753-3209-47cf-8bc4-662c9b6d34ea', '送徐州薛尚書', '送徐州薛尚书', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["上將出儒中，論詩擬立功。","州從禹後別，軍自漢來雄。","遠驛銷寒日，嚴城肅暮空。","龍顏有遺廟，猶得奠英風。"]', '["上將出儒中，論诗擬立功。","州從禹後別，軍自漢来雄。","远驛銷寒日，嚴城肅暮空。","龙顏有遺廟，猶得奠英风。"]', '诗', 'shi', '', NULL, '送徐州薛尚書 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c228bd5d-bee3-4a1a-8808-0585b1c4c0ef', '貽曹郎中', '貽曹郎中', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["所作高前古，封章自曲臺。","細看明主意，終用出人才。","省印尋僧鎖，書樓領鶴開。","南山有舊友，時向白雲來。"]', '["所作高前古，封章自曲台。","細看明主意，終用出人才。","省印尋僧鎖，书楼領鹤开。","南山有旧友，时向白云来。"]', '诗', 'shi', '', NULL, '貽曹郎中 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ac8678a-1d5b-470c-a7c9-a5ca97cd7610', '送縉雲尉', '送縉云尉', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["釋褐從仙尉，之官興若何。","去程唯水石，公署在雲蘿。","野飯樓中迥，晴峰案上多。","三年罷趨府，應更戰高科。"]', '["釋褐從仙尉，之官兴若何。","去程唯水石，公署在云蘿。","野飯楼中迥，晴峰案上多。","三年罷趨府，應更戰高科。"]', '诗', 'shi', '', NULL, '送縉雲尉 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f54e6868-143d-4ab6-91aa-69baeeb4c5a0', '送董卿赴台州', '送董卿赴台州', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["九陌除書出，尋僧問海城。","家從中路挈，吏隔數州迎。","夜蚌侵燈影，春禽雜櫓聲。","開圖見異跡，思上石橋行。"]', '["九陌除书出，尋僧问海城。","家從中路挈，吏隔數州迎。","夜蚌侵灯影，春禽杂櫓声。","开圖见異跡，思上石橋行。"]', '诗', 'shi', '', NULL, '送董卿赴台州 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('424a85f0-f480-4111-82a1-5a069a2785fd', '送友人赴涇州幕', '送友人赴涇州幕', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["杏園沈飲散，榮別就佳招。","日月相期盡，山川獨去遙。","府樓明蜀雪，關磧轉胡鵰。","縱有煙塵動，應隨上策銷。"]', '["杏园沈饮散，榮別就佳招。","日月相期尽，山川独去遙。","府楼明蜀雪，关磧轉胡鵰。","縱有煙塵动，應隨上策銷。"]', '诗', 'shi', '', NULL, '送友人赴涇州幕 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b1b2eec-8a9a-48a3-8ad2-5f4d37312677', '逢漳州崔使君北歸', '逢漳州崔使君北归', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["在郡多殊稱，無人不望回。","離城攜客去，度嶺擔猿來。","障寫經冬蘂，瓶緘落暑梅。","長安有歸宅，歸見鎖青苔。"]', '["在郡多殊稱，無人不望回。","離城携客去，度嶺擔猿来。","障寫經冬蘂，瓶緘落暑梅。","长安有归宅，归见鎖青苔。"]', '诗', 'shi', '', NULL, '逢漳州崔使君北歸 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('056b58c6-0902-42aa-97d9-c8adef05ef77', '雲朔逢山友', '云朔逢山友', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["會面却生疑，居然似夢歸。","塞深行客少，家遠識人稀。","戰馬分旗牧，驚禽曳箭飛。","將軍雖異禮，難便脫麻衣。"]', '["會面却生疑，居然似梦归。","塞深行客少，家远識人稀。","戰马分旗牧，驚禽曳箭飞。","將軍雖異禮，难便脫麻衣。"]', '诗', 'shi', '', NULL, '雲朔逢山友 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7526030b-d50b-4cb1-b3ba-8b2f9e303aba', '別後寄友生', '別後寄友生', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["上馬如飛鳥，飄然隔去塵。","共看今夜月，獨作異鄉人。","就養江南熟，移居井賦新。","襄陽曾卜隱，應與孟家鄰。"]', '["上马如飞鸟，飄然隔去塵。","共看今夜月，独作異乡人。","就養江南熟，移居井賦新。","襄陽曾卜隐，應與孟家鄰。"]', '诗', 'shi', '', NULL, '別後寄友生 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28c345b7-7090-4b3d-be4c-c08e8d275f8e', '邊遊別友人', '邊游別友人', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["欲別不止淚，當杯難強歌。","家貧隨日長，身病涉寒多。","雨雪迷燕路，田園隔楚波。","良時未自致，歸去欲如何。"]', '["欲別不止泪，當杯难強歌。","家貧隨日长，身病涉寒多。","雨雪迷燕路，田园隔楚波。","良时未自致，归去欲如何。"]', '诗', 'shi', '', NULL, '邊遊別友人 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ed3648c-3514-428e-bb3e-4aaf64bb7695', '邊庭送別', '邊庭送別', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["一生雖達理，遠別亦相悲。","白髮無修處，青松有老時。","暮煙傳戍起，寒日隔沙垂。","若是長安去，何難定後期。"]', '["一生雖達理，远別亦相悲。","白髮無修处，青松有老时。","暮煙傳戍起，寒日隔沙垂。","若是长安去，何难定後期。"]', '诗', 'shi', '', NULL, '邊庭送別 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('733e08d1-b8bf-43a2-b7f2-f997e3c87905', '將之京師留別親友', '將之京師留別親友', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["達命何勞問，西遊且自期。","至公如有日，知我豈無時。","野迥蟬相答，堤長柳對垂。","酣歌一舉袂，明發不堪思。"]', '["達命何勞问，西游且自期。","至公如有日，知我豈無时。","野迥蟬相答，堤长柳对垂。","酣歌一舉袂，明發不堪思。"]', '诗', 'shi', '', NULL, '將之京師留別親友 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6866b4a-2733-46f7-8b6e-acfa942745e9', '贈別山友', '贈別山友', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["從容無限意，不獨爲離羣。","年長驚黃葉，時清厭白雲。","舊山迴馬見，寒瀑別家聞。","相與存吾道，窮通各自分。"]', '["從容無限意，不独爲離羣。","年长驚黄葉，时清厭白云。","旧山迴马见，寒瀑別家闻。","相與存吾道，窮通各自分。"]', '诗', 'shi', '', NULL, '贈別山友 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22923d09-b7eb-481e-9268-da7f1a920c0b', '途次績溪先寄陳明府', '途次績溪先寄陳明府', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["入境風煙好，幽人不易傳。","新居多是客，舊隱半成仙。","山斷雲衝騎，溪長柳拂船。","何當許過縣，聞有篋中篇。"]', '["入境风煙好，幽人不易傳。","新居多是客，旧隐半成仙。","山斷云衝騎，溪长柳拂船。","何當許過縣，闻有篋中篇。"]', '诗', 'shi', '', NULL, '途次績溪先寄陳明府 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cda2a3c2-9f4c-4004-b23e-0e622f0fcc4e', '送友人歸武陵', '送友人归武陵', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["聞近桃源住，無村不是花。","戍旗招海客，廟鼓集江鴉。","別島垂橙實，閑田長荻[芽]。","遊秦未得意，看即更離家。"]', '["闻近桃源住，無村不是花。","戍旗招海客，廟鼓集江鴉。","別島垂橙實，闲田长荻[芽]。","游秦未得意，看即更離家。"]', '诗', 'shi', '', NULL, '送友人歸武陵 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9471aab-9a5e-45f5-b13f-a6d99507445c', '亂中寄友人', '亂中寄友人', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["別來難覓信，何處避艱危。","鬢黑無多日，塵清是幾時。","人情將厭武，王澤即興詩。","若便懷深隱，還應聖主知。"]', '["別来难覓信，何处避艱危。","鬢黑無多日，塵清是幾时。","人情將厭武，王澤即兴诗。","若便懷深隐，還應聖主知。"]', '诗', 'shi', '', NULL, '亂中寄友人 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7dad5eb4-1f34-4def-aa0e-5a0e494e765f', '哭建州李員外', '哭建州李員外', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["詩名不易出，名出又何爲。","捷到重科早，官終一郡卑。","素風無後嗣，遺跡有生祠。","自罷羊公市，溪猿哭舊時。"]', '["诗名不易出，名出又何爲。","捷到重科早，官終一郡卑。","素风無後嗣，遺跡有生祠。","自罷羊公市，溪猿哭旧时。"]', '诗', 'shi', '', NULL, '哭建州李員外 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40ed7a97-e705-44d1-be65-2f01d6df965a', '弔孟浩然', '弔孟浩然', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["每每樵家說，孤墳亦夜吟。","若重生此世，應更苦前心。","名與襄陽遠，詩同漢水深。","親栽鹿門樹，猶蓋石牀陰。"]', '["每每樵家说，孤墳亦夜吟。","若重生此世，應更苦前心。","名與襄陽远，诗同漢水深。","親栽鹿门樹，猶蓋石牀陰。"]', '诗', 'shi', '', NULL, '弔孟浩然 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07288408-593c-4f8e-b616-02e813e22efc', '送友人及第歸', '送友人及第归', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["家林滄海東，未曉日先紅。","作貢諸蕃別，登科幾國同。","遠聲魚呷浪，層氣蜃迎風。","鄉俗稀攀桂，爭來問月宮。"]', '["家林滄海东，未晓日先紅。","作貢諸蕃別，登科幾国同。","远声鱼呷浪，層氣蜃迎风。","乡俗稀攀桂，爭来问月宮。"]', '诗', 'shi', '', NULL, '送友人及第歸 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6608ef1-e7e4-4321-88dc-e1989d2be883', '次韻和友人冬月書齋', '次韻和友人冬月书斋', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["四季多花木，窮冬亦不凋。","薄冰行處斷，殘火睡來消。","象版簽書帙，蠻藤絡酒[瓢]。","公卿有知己，時得一相招。"]', '["四季多花木，窮冬亦不凋。","薄冰行处斷，殘火睡来消。","象版簽书帙，蠻藤絡酒[瓢]。","公卿有知己，时得一相招。"]', '诗', 'shi', '', NULL, '次韻和友人冬月書齋 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b3a1cef-5c22-4eb7-b2e2-e92bfccbd604', '過山家', '過山家', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["避暑得探幽，忘言遂久留。","雲深窗失曙，松合徑先秋。","響谷傳人語，鳴泉洗客愁。","家山不在此，至此可歸休。"]', '["避暑得探幽，忘言遂久留。","云深窗失曙，松合徑先秋。","响谷傳人語，鳴泉洗客愁。","家山不在此，至此可归休。"]', '诗', 'shi', '', NULL, '過山家 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20c1984f-1540-4915-856e-2958e94703d8', '宿山驛', '宿山驛', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["驛在千峰裏，寒宵獨此身。","古墳時見火，荒壁悄無隣。","月白翻驚鳥，雲閑欲就人。","秪應明日鬢，更與老相親。"]', '["驛在千峰裏，寒宵独此身。","古墳时见火，荒壁悄無隣。","月白翻驚鸟，云闲欲就人。","秪應明日鬢，更與老相親。"]', '诗', 'shi', '', NULL, '宿山驛 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bf36fc9-76cc-4378-a027-f5ad3bee19ac', '宿開照寺光澤上人院', '宿开照寺光澤上人院', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["靜室譚玄旨，清宵獨細聽。","真身非有像，至理本無經。","鐘定遙聞水，樓高別見星。","不教人觸穢，偏說此山靈。"]', '["静室譚玄旨，清宵独細听。","真身非有像，至理本無經。","鐘定遙闻水，楼高別见星。","不教人觸穢，偏说此山靈。"]', '诗', 'shi', '', NULL, '宿開照寺光澤上人院 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6288b803-c05e-404e-bddf-7f81d7e0ffe3', '宿山寺', '宿山寺', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["中峰半夜起，忽覺有青冥。","此界自生雨，上方猶有星。","樓高鐘尚遠，殿古像多靈。","好是潺湲水，房房伴誦經。"]', '["中峰半夜起，忽覺有青冥。","此界自生雨，上方猶有星。","楼高鐘尚远，殿古像多靈。","好是潺湲水，房房伴誦經。"]', '诗', 'shi', '', NULL, '宿山寺 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe9e5b40-d5a4-48ba-b488-c9e8079e5cbb', '題紫閣院', '題紫閣院', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["上方人海外，苔徑上千層。","洞壑有靈藥，房廊無老僧。","古巖雕素像，喬木挂寒燈。","每到思修隱，將回苦不能。"]', '["上方人海外，苔徑上千層。","洞壑有靈藥，房廊無老僧。","古巖雕素像，喬木挂寒灯。","每到思修隐，將回苦不能。"]', '诗', 'shi', '', NULL, '題紫閣院 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('456a210f-0864-430e-bd45-b69c820ab291', '白菊', '白菊', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["秋天木葉乾，猶有白花殘。","舉世稀栽得，豪家却畫看。","片苔相應綠，諸卉獨宜寒。","幾度攜佳客，登高欲折難。"]', '["秋天木葉乾，猶有白花殘。","舉世稀栽得，豪家却畫看。","片苔相應綠，諸卉独宜寒。","幾度携佳客，登高欲折难。"]', '诗', 'shi', '', NULL, '白菊 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19d5299e-b287-432c-9c23-87e45dd7b53f', '叢葦', '叢葦', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["叢叢寒水邊，曾折打魚船。","忽與亭臺近，翻嫌島嶼偏。","花明無月夜，聲急正秋天。","遙憶巴陵渡，殘陽一望煙。"]', '["叢叢寒水邊，曾折打鱼船。","忽與亭台近，翻嫌島嶼偏。","花明無月夜，声急正秋天。","遙憶巴陵渡，殘陽一望煙。"]', '诗', 'shi', '', NULL, '叢葦 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26535eff-108e-4625-bb84-938efe54e109', '鄭轂補闕山松', '鄭轂補闕山松', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["心將積雪欺，根與白雲離。","遠寄僧猶憶，高看鶴未知。","影交新長葉，皴匝舊生枝。","多少同時種，深山不得移。"]', '["心將積雪欺，根與白云離。","远寄僧猶憶，高看鹤未知。","影交新长葉，皴匝旧生枝。","多少同时種，深山不得移。"]', '诗', 'shi', '', NULL, '鄭轂補闕山松 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79b9e220-89e2-4de3-9457-8d6526e2386f', '新竹', '新竹', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["新鞭暗入庭，初長兩三莖。","不是他山少，無如此地生。","垂梢叢上出，柔葉籜間成。","何用高唐峽，風枝埽月明。"]', '["新鞭暗入庭，初长兩三莖。","不是他山少，無如此地生。","垂梢叢上出，柔葉籜间成。","何用高唐峽，风枝埽月明。"]', '诗', 'shi', '', NULL, '新竹 張蠙 shi');
